{
  "name": "Thai Leave Management System",
  "description": "A comprehensive calendar-based leave management system for hospital departments with visual statistics and AI-powered insights."
}

import React from 'react';
import ReactDOM from 'react-dom/client';
import App from './App';

const rootElement = document.getElementById('root');
if (!rootElement) {
  throw new Error("Could not find root element to mount to");
}

const root = ReactDOM.createRoot(rootElement);
root.render(
  <React.StrictMode>
    <App />
  </React.StrictMode>
);

export enum Department {
  OPD = 'เวชระเบียนผู้ป่วยนอก',
  IPD = 'เวชระเบียนผู้ป่วยใน',
  DATA_CENTER = 'ศูนย์ข้อมูล'
}

export enum LeaveType {
  PERSONAL = 'ลากิจส่วนตัว',
  SICK = 'ลาป่วย',
  VACATION = 'ลาพักผ่อน',
  MATERNITY = 'ลาคลอดบุตร',
  ORDINATION = 'ลาอุปสมบท'
}

export interface Employee {
  id: string;
  name: string;
  department: Department;
}

export interface LeaveRecord {
  id: string;
  employeeId: string;
  date: string; // ISO String YYYY-MM-DD
  type: LeaveType;
  note?: string;
}

export const LEAVE_COLORS: Record<LeaveType, string> = {
  [LeaveType.PERSONAL]: 'bg-blue-500',
  [LeaveType.SICK]: 'bg-red-500',
  [LeaveType.VACATION]: 'bg-green-500',
  [LeaveType.MATERNITY]: 'bg-pink-500',
  [LeaveType.ORDINATION]: 'bg-yellow-500'
};

export const LEAVE_TEXT_COLORS: Record<LeaveType, string> = {
  [LeaveType.PERSONAL]: 'text-blue-600',
  [LeaveType.SICK]: 'text-red-600',
  [LeaveType.VACATION]: 'text-green-600',
  [LeaveType.MATERNITY]: 'text-pink-600',
  [LeaveType.ORDINATION]: 'text-yellow-600'
};

import { Department, Employee, LeaveType, LeaveRecord } from './types';

// Mock Employees
export const INITIAL_EMPLOYEES: Employee[] = [
  { id: '1', name: 'สมชาย ใจดี', department: Department.OPD },
  { id: '2', name: 'สมหญิง รักงาน', department: Department.OPD },
  { id: '3', name: 'วิชัย เก่งกล้า', department: Department.OPD },
  { id: '4', name: 'มานี มีตา', department: Department.IPD },
  { id: '5', name: 'ปิติ พอใจ', department: Department.IPD },
  { id: '6', name: 'ชูใจ ใจสู้', department: Department.DATA_CENTER },
  { id: '7', name: 'วีระ กล้าหาญ', department: Department.DATA_CENTER },
  { id: '8', name: 'มานะ อดทน', department: Department.DATA_CENTER },
];

// Helper to generate some initial past leaves for visualization
const generateMockLeaves = (): LeaveRecord[] => {
  const leaves: LeaveRecord[] = [];
  const year = new Date().getFullYear();

  // Random leaves for visual population
  leaves.push({ id: 'l1', employeeId: '1', date: `${year}-01-15`, type: LeaveType.SICK });
  leaves.push({ id: 'l2', employeeId: '1', date: `${year}-01-16`, type: LeaveType.SICK });
  leaves.push({ id: 'l3', employeeId: '1', date: `${year}-04-10`, type: LeaveType.VACATION });
  leaves.push({ id: 'l4', employeeId: '6', date: `${year}-02-20`, type: LeaveType.PERSONAL });
  leaves.push({ id: 'l5', employeeId: '6', date: `${year}-07-05`, type: LeaveType.ORDINATION });
  leaves.push({ id: 'l6', employeeId: '4', date: `${year}-09-12`, type: LeaveType.MATERNITY });

  return leaves;
};

export const INITIAL_LEAVES = generateMockLeaves();

export const DEPARTMENTS = [
  { id: Department.OPD, label: Department.OPD, icon: 'Users', color: 'bg-blue-600' },
  { id: Department.IPD, label: Department.IPD, icon: 'Activity', color: 'bg-teal-600' },
  { id: Department.DATA_CENTER, label: Department.DATA_CENTER, icon: 'Database', color: 'bg-indigo-600' },
];

import { GoogleGenAI } from "@google/genai";
import { LeaveRecord, Employee, LeaveType } from "../types";

// Initialize Gemini Client
// Note: In a real app, API Key comes from process.env.API_KEY
// The user prompt forbids asking for input, so we assume it exists or fail gracefully.
const ai = new GoogleGenAI({ apiKey: process.env.API_KEY || 'YOUR_API_KEY_HERE' });

export const analyzeLeaveData = async (
  employeeName: string,
  leaves: LeaveRecord[],
  allEmployees: Employee[]
): Promise<string> => {
  try {
    if (!process.env.API_KEY) {
      return "กรุณาตั้งค่า API KEY เพื่อใช้งานฟีเจอร์ AI";
    }

    const employeeLeaves = leaves.filter(l => {
       const emp = allEmployees.find(e => e.id === l.employeeId);
       return emp?.name === employeeName;
    });

    const context = `
      ข้อมูลการลาของพนักงานชื่อ: ${employeeName}
      รายการลาทั้งหมด: ${JSON.stringify(employeeLeaves)}
      ประเภทการลาที่มี: ${Object.values(LeaveType).join(', ')}
    `;

    const response = await ai.models.generateContent({
      model: 'gemini-3-flash-preview',
      contents: `
        ${context}

        ช่วยวิเคราะห์สรุปพฤติกรรมการลาของพนักงานคนนี้ให้หน่อย โดยตอบเป็นภาษาไทย
        1. สรุปจำนวนวันลาแต่ละประเภท
        2. แนวโน้มการลา (เช่น ลาป่วยบ่อยช่วงต้นปี)
        3. ข้อความให้กำลังใจสั้นๆ
      `,
    });

    return response.text || "ไม่สามารถวิเคราะห์ข้อมูลได้ในขณะนี้";
  } catch (error) {
    console.error("Gemini Error:", error);
    return "เกิดข้อผิดพลาดในการเชื่อมต่อกับ AI";
  }
};

import React, { useMemo } from 'react';
import { BarChart, Bar, XAxis, YAxis, CartesianGrid, Tooltip, Legend, ResponsiveContainer } from 'recharts';
import { LeaveRecord, LeaveType } from '../types';

interface StatsChartProps {
  leaves: LeaveRecord[];
  currentYear: number;
}

const StatsChart: React.FC<StatsChartProps> = ({ leaves, currentYear }) => {
  const data = useMemo(() => {
    // Filter leaves for current year
    const yearLeaves = leaves.filter(l => new Date(l.date).getFullYear() === currentYear);

    // Initialize counters
    const period1 = { // Jan - May (Month 0 - 4)
      name: 'ม.ค. - พ.ค.',
      [LeaveType.PERSONAL]: 0,
      [LeaveType.SICK]: 0,
      [LeaveType.VACATION]: 0,
      [LeaveType.MATERNITY]: 0,
      [LeaveType.ORDINATION]: 0,
    };

    const period2 = { // Jun - Dec (Month 5 - 11)
      name: 'มิ.ย. - ธ.ค.',
      [LeaveType.PERSONAL]: 0,
      [LeaveType.SICK]: 0,
      [LeaveType.VACATION]: 0,
      [LeaveType.MATERNITY]: 0,
      [LeaveType.ORDINATION]: 0,
    };

    yearLeaves.forEach(leave => {
      const month = new Date(leave.date).getMonth();
      const type = leave.type;

      if (month >= 0 && month <= 4) {
        if (period1[type] !== undefined) period1[type]++;
      } else {
        if (period2[type] !== undefined) period2[type]++;
      }
    });

    return [period1, period2];
  }, [leaves, currentYear]);

  return (
    <div className="bg-white p-4 rounded-xl shadow-md h-80 w-full">
      <h3 className="text-lg font-bold text-gray-700 mb-4">สถิติการลาประจำปี {currentYear + 543}</h3>
      <ResponsiveContainer width="100%" height="100%">
        <BarChart
          data={data}
          margin={{
            top: 5,
            right: 30,
            left: 20,
            bottom: 5,
          }}
        >
          <CartesianGrid strokeDasharray="3 3" vertical={false} />
          <XAxis dataKey="name" />
          <YAxis allowDecimals={false} />
          <Tooltip 
            contentStyle={{ borderRadius: '8px', border: 'none', boxShadow: '0 4px 6px -1px rgb(0 0 0 / 0.1)' }}
            cursor={{ fill: '#f1f5f9' }}
          />
          <Legend />
          <Bar dataKey={LeaveType.PERSONAL} name="กิจส่วนตัว" fill="#3b82f6" radius={[4, 4, 0, 0]} />
          <Bar dataKey={LeaveType.SICK} name="ป่วย" fill="#ef4444" radius={[4, 4, 0, 0]} />
          <Bar dataKey={LeaveType.VACATION} name="พักผ่อน" fill="#22c55e" radius={[4, 4, 0, 0]} />
          <Bar dataKey={LeaveType.MATERNITY} name="คลอดบุตร" fill="#ec4899" radius={[4, 4, 0, 0]} />
          <Bar dataKey={LeaveType.ORDINATION} name="อุปสมบท" fill="#eab308" radius={[4, 4, 0, 0]} />
        </BarChart>
      </ResponsiveContainer>
    </div>
  );
};

export default StatsChart;

import React, { useState, useMemo } from 'react';
import { ChevronLeft, ChevronRight, Info } from 'lucide-react';
import { LeaveRecord, LeaveType, LEAVE_COLORS } from '../types';

interface CalendarViewProps {
  leaves: LeaveRecord[];
  onDateClick: (dateStr: string) => void;
  selectedEmployeeId: string | null;
}

const CalendarView: React.FC<CalendarViewProps> = ({ leaves, onDateClick, selectedEmployeeId }) => {
  const [currentDate, setCurrentDate] = useState(new Date());

  const year = currentDate.getFullYear();
  const month = currentDate.getMonth();

  const daysInMonth = new Date(year, month + 1, 0).getDate();
  const firstDayOfMonth = new Date(year, month, 1).getDay(); // 0 = Sunday

  const prevMonth = () => setCurrentDate(new Date(year, month - 1, 1));
  const nextMonth = () => setCurrentDate(new Date(year, month + 1, 1));

  // Filter leaves for this view
  const leavesMap = useMemo(() => {
    const map: Record<string, LeaveType> = {};
    leaves.forEach(l => {
      // Only show leaves for the selected employee if one is selected, 
      // otherwise show visual indication that *someone* took leave (simplified for this UI to just user's)
      if (selectedEmployeeId && l.employeeId === selectedEmployeeId) {
        map[l.date] = l.type;
      }
    });
    return map;
  }, [leaves, selectedEmployeeId]);

  const renderDays = () => {
    const days = [];

    // Padding for days before start of month
    for (let i = 0; i < firstDayOfMonth; i++) {
      days.push(<div key={`empty-${i}`} className="h-24 md:h-32 bg-gray-50/50 border border-gray-100"></div>);
    }

    // Days of month
    for (let i = 1; i <= daysInMonth; i++) {
      const dayStr = i.toString().padStart(2, '0');
      const monthStr = (month + 1).toString().padStart(2, '0');
      const dateStr = `${year}-${monthStr}-${dayStr}`;
      const leaveType = leavesMap[dateStr];
      const isToday = new Date().toDateString() === new Date(year, month, i).toDateString();

      days.push(
        <div 
          key={i} 
          onClick={() => selectedEmployeeId && onDateClick(dateStr)}
          className={`h-24 md:h-32 border border-gray-100 p-2 relative transition-all duration-200 
            ${selectedEmployeeId ? 'cursor-pointer hover:bg-gray-50' : 'cursor-not-allowed opacity-80'}
            ${isToday ? 'bg-blue-50/30' : 'bg-white'}
          `}
        >
          <div className="flex justify-between items-start">
            <span className={`text-sm font-medium h-7 w-7 flex items-center justify-center rounded-full ${isToday ? 'bg-primary text-white' : 'text-gray-700'}`}>
              {i}
            </span>
          </div>

          {leaveType && (
            <div className={`mt-2 p-1.5 rounded text-xs text-white font-medium truncate shadow-sm ${LEAVE_COLORS[leaveType]}`}>
              {leaveType}
            </div>
          )}

          {!selectedEmployeeId && i === 1 && (
            <div className="absolute inset-0 flex items-center justify-center bg-gray-100/50 backdrop-blur-[1px] text-gray-400 text-xs text-center p-1">
              เลือกรายชื่อก่อน
            </div>
          )}
        </div>
      );
    }
    return days;
  };

  const thaiMonths = [
    "มกราคม", "กุมภาพันธ์", "มีนาคม", "เมษายน", "พฤษภาคม", "มิถุนายน",
    "กรกฎาคม", "สิงหาคม", "กันยายน", "ตุลาคม", "พฤศจิกายน", "ธันวาคม"
  ];

  return (
    <div className="bg-white rounded-xl shadow-lg overflow-hidden border border-gray-200">
      <div className="p-4 flex items-center justify-between bg-gradient-to-r from-gray-800 to-gray-700 text-white">
        <button onClick={prevMonth} className="p-2 hover:bg-white/20 rounded-full transition-colors">
          <ChevronLeft className="w-6 h-6" />
        </button>
        <h2 className="text-xl font-bold font-sans">
          {thaiMonths[month]} {year + 543}
        </h2>
        <button onClick={nextMonth} className="p-2 hover:bg-white/20 rounded-full transition-colors">
          <ChevronRight className="w-6 h-6" />
        </button>
      </div>

      <div className="grid grid-cols-7 bg-gray-50 border-b border-gray-200">
        {['อา', 'จ', 'อ', 'พ', 'พฤ', 'ศ', 'ส'].map((d, i) => (
          <div key={i} className={`py-3 text-center text-sm font-bold ${i === 0 || i === 6 ? 'text-red-500' : 'text-gray-600'}`}>
            {d}
          </div>
        ))}
      </div>

      <div className="grid grid-cols-7">
        {renderDays()}
      </div>

      {!selectedEmployeeId && (
        <div className="p-3 bg-yellow-50 text-yellow-800 text-sm flex items-center gap-2">
            <Info className="w-4 h-4"/> กรุณาค้นหาและเลือกรายชื่อพนักงานเพื่อดูหรือบันทึกการลา
        </div>
      )}
    </div>
  );
};

export default CalendarView;

import React, { useState, useEffect, useMemo } from 'react';
import { 
  Users, Activity, Database, Search, Calendar as CalendarIcon, 
  ArrowLeft, PlusCircle, CheckCircle2, AlertCircle, Bot
} from 'lucide-react';
import { Department, Employee, LeaveRecord, LeaveType, LEAVE_COLORS } from './types';
import { INITIAL_EMPLOYEES, INITIAL_LEAVES, DEPARTMENTS } from './constants';
import CalendarView from './components/CalendarView';
import StatsChart from './components/StatsChart';
import { analyzeLeaveData } from './services/geminiService';

function App() {
  const [currentDepartment, setCurrentDepartment] = useState<Department | null>(null);
  const [searchQuery, setSearchQuery] = useState('');
  const [selectedEmployee, setSelectedEmployee] = useState<Employee | null>(null);
  const [leaves, setLeaves] = useState<LeaveRecord[]>(INITIAL_LEAVES);

  // Modal State
  const [isModalOpen, setIsModalOpen] = useState(false);
  const [selectedDate, setSelectedDate] = useState<string>('');
  const [leaveType, setLeaveType] = useState<LeaveType>(LeaveType.PERSONAL);

  // AI State
  const [aiAnalysis, setAiAnalysis] = useState<string>('');
  const [isAiLoading, setIsAiLoading] = useState(false);
  const [isAiModalOpen, setIsAiModalOpen] = useState(false);

  // Filter employees based on department and search
  const filteredEmployees = useMemo(() => {
    if (!currentDepartment) return [];
    return INITIAL_EMPLOYEES.filter(emp => {
      const matchDept = emp.department === currentDepartment;
      const matchSearch = emp.name.toLowerCase().includes(searchQuery.toLowerCase());
      return matchDept && matchSearch;
    });
  }, [currentDepartment, searchQuery]);

  // Handle department selection
  const handleDepartmentSelect = (dept: Department) => {
    setCurrentDepartment(dept);
    setSearchQuery('');
    setSelectedEmployee(null);
  };

  // Handle user selection from autocomplete
  const handleUserSelect = (emp: Employee) => {
    setSelectedEmployee(emp);
    setSearchQuery(emp.name); // Set input to selected name
  };

  // Handle Calendar Date Click
  const handleDateClick = (dateStr: string) => {
    if (!selectedEmployee) return;
    setSelectedDate(dateStr);

    // Check if leave already exists
    const existing = leaves.find(l => l.employeeId === selectedEmployee.id && l.date === dateStr);
    if (existing) {
        // Maybe handle edit/delete later, for now just pre-select type
        setLeaveType(existing.type);
    } else {
        setLeaveType(LeaveType.PERSONAL);
    }

    setIsModalOpen(true);
  };

  // Save Leave
  const handleSaveLeave = () => {
    if (!selectedEmployee || !selectedDate) return;

    setLeaves(prev => {
      // Remove existing for this date if any
      const filtered = prev.filter(l => !(l.employeeId === selectedEmployee.id && l.date === selectedDate));
      return [...filtered, {
        id: Math.random().toString(36).substr(2, 9),
        employeeId: selectedEmployee.id,
        date: selectedDate,
        type: leaveType
      }];
    });
    setIsModalOpen(false);
  };

  // Trigger AI Analysis
  const handleAiAnalyze = async () => {
    if (!selectedEmployee) return;
    setIsAiModalOpen(true);
    setIsAiLoading(true);
    setAiAnalysis('');

    const result = await analyzeLeaveData(selectedEmployee.name, leaves, INITIAL_EMPLOYEES);
    setAiAnalysis(result);
    setIsAiLoading(false);
  };

  // Render Landing Page
  if (!currentDepartment) {
    return (
      <div className="min-h-screen bg-gradient-to-br from-slate-100 to-slate-200 flex flex-col items-center justify-center p-6">
        <div className="text-center mb-12">
          <h1 className="text-4xl md:text-5xl font-bold text-slate-800 mb-4 font-sans">ระบบบันทึกการลาออนไลน์</h1>
          <p className="text-slate-500 text-lg">กรุณาเลือกหน่วยงานของท่านเพื่อเข้าสู่ระบบ</p>
        </div>

        <div className="grid grid-cols-1 md:grid-cols-3 gap-8 max-w-6xl w-full">
          {DEPARTMENTS.map((dept) => {
            const Icon = dept.icon === 'Users' ? Users : dept.icon === 'Activity' ? Activity : Database;
            return (
              <button
                key={dept.id}
                onClick={() => handleDepartmentSelect(dept.id as Department)}
                className="group relative bg-white rounded-2xl p-8 shadow-xl hover:shadow-2xl transition-all duration-300 transform hover:-translate-y-2 border border-slate-100 overflow-hidden"
              >
                <div className={`absolute top-0 left-0 w-full h-2 ${dept.color}`}></div>
                <div className={`${dept.color} bg-opacity-10 w-20 h-20 rounded-2xl flex items-center justify-center mb-6 mx-auto group-hover:scale-110 transition-transform duration-300`}>
                  <Icon className={`w-10 h-10 ${dept.color.replace('bg-', 'text-')}`} />
                </div>
                <h3 className="text-2xl font-bold text-slate-800 mb-2">{dept.label}</h3>
                <p className="text-slate-400 text-sm">คลิกเพื่อเข้าสู่ปฏิทินการลา</p>
              </button>
            );
          })}
        </div>
      </div>
    );
  }

  // Render Dashboard
  return (
    <div className="min-h-screen bg-slate-50 flex flex-col">
      {/* Header */}
      <header className="bg-white shadow-sm border-b border-slate-200 sticky top-0 z-30">
        <div className="max-w-7xl mx-auto px-4 py-4 flex items-center justify-between">
          <div className="flex items-center gap-4">
            <button 
              onClick={() => setCurrentDepartment(null)}
              className="p-2 hover:bg-slate-100 rounded-full text-slate-500 transition-colors"
            >
              <ArrowLeft className="w-6 h-6" />
            </button>
            <div>
              <h1 className="text-xl font-bold text-slate-800">{currentDepartment}</h1>
              <p className="text-xs text-slate-500">ระบบจัดการวันลา</p>
            </div>
          </div>

          <div className="flex items-center gap-2">
            <div className="hidden md:flex items-center gap-2 mr-4">
              {Object.entries(LEAVE_COLORS).map(([type, color]) => (
                <div key={type} className="flex items-center gap-1">
                  <span className={`w-3 h-3 rounded-full ${color}`}></span>
                  <span className="text-xs text-slate-600">{type}</span>
                </div>
              ))}
            </div>
          </div>
        </div>
      </header>

      {/* Main Content */}
      <main className="flex-1 max-w-7xl w-full mx-auto p-4 md:p-6 grid grid-cols-1 lg:grid-cols-12 gap-6">

        {/* Sidebar / Controls */}
        <div className="lg:col-span-4 space-y-6">
          {/* User Search Card */}
          <div className="bg-white p-6 rounded-xl shadow-sm border border-slate-200">
            <label className="block text-sm font-medium text-slate-700 mb-2">ค้นหารายชื่อพนักงาน</label>
            <div className="relative">
              <Search className="absolute left-3 top-1/2 -translate-y-1/2 text-slate-400 w-5 h-5" />
              <input
                type="text"
                className="w-full pl-10 pr-4 py-3 bg-slate-50 border border-slate-200 rounded-lg focus:ring-2 focus:ring-blue-500 focus:border-transparent outline-none transition-all"
                placeholder="พิมพ์ชื่อ หรืออักษรย่อ..."
                value={searchQuery}
                onChange={(e) => {
                    setSearchQuery(e.target.value);
                    if (selectedEmployee && e.target.value !== selectedEmployee.name) {
                        setSelectedEmployee(null);
                    }
                }}
              />

              {/* Autocomplete Dropdown */}
              {searchQuery && !selectedEmployee && filteredEmployees.length > 0 && (
                <div className="absolute top-full left-0 right-0 mt-1 bg-white rounded-lg shadow-xl border border-slate-100 max-h-60 overflow-y-auto z-50">
                  {filteredEmployees.map(emp => (
                    <button
                      key={emp.id}
                      onClick={() => handleUserSelect(emp)}
                      className="w-full text-left px-4 py-3 hover:bg-blue-50 flex items-center gap-3 transition-colors border-b border-slate-50 last:border-0"
                    >
                      <div className="w-8 h-8 rounded-full bg-blue-100 text-blue-600 flex items-center justify-center font-bold text-xs">
                        {emp.name.charAt(0)}
                      </div>
                      <span className="text-slate-700 font-medium">{emp.name}</span>
                    </button>
                  ))}
                </div>
              )}
            </div>

            {selectedEmployee && (
              <div className="mt-4 p-4 bg-blue-50 rounded-lg border border-blue-100 flex items-center justify-between animate-fade-in">
                 <div className="flex items-center gap-3">
                    <div className="w-10 h-10 rounded-full bg-blue-500 text-white flex items-center justify-center font-bold">
                        {selectedEmployee.name.charAt(0)}
                    </div>
                    <div>
                        <p className="font-bold text-slate-800">{selectedEmployee.name}</p>
                        <p className="text-xs text-blue-600">พนักงาน {currentDepartment}</p>
                    </div>
                 </div>
                 <CheckCircle2 className="text-blue-500 w-6 h-6" />
              </div>
            )}

             {/* Gemini AI Feature */}
            {selectedEmployee && (
                <button 
                  onClick={handleAiAnalyze}
                  className="mt-4 w-full flex items-center justify-center gap-2 bg-gradient-to-r from-purple-600 to-indigo-600 text-white py-2 rounded-lg hover:shadow-lg transition-all"
                >
                    <Bot className="w-5 h-5" />
                    วิเคราะห์ประวัติการลา (AI)
                </button>
            )}
          </div>

          {/* Stats Chart */}
