             <div>
                <h2 className="text-2xl font-bold text-slate-800 flex items-baseline gap-2">
                {thaiMonths[month]} <span className="text-slate-400 font-light">|</span> {year + 543}
                </h2>
                <p className="text-xs text-slate-400 font-medium">ปฏิทินการทำงาน</p>
             </div>
        </div>

        <div className="flex items-center gap-1 bg-slate-50 p-1 rounded-xl border border-slate-100">
            <button onClick={prevMonth} className="p-2 hover:bg-white hover:shadow-sm rounded-lg text-slate-500 transition-all">
            <ChevronLeft className="w-5 h-5" />
            </button>
            <div className="w-px h-6 bg-slate-200 mx-1"></div>
            <button onClick={nextMonth} className="p-2 hover:bg-white hover:shadow-sm rounded-lg text-slate-500 transition-all">
            <ChevronRight className="w-5 h-5" />
            </button>
        </div>
      </div>

      {/* Weekdays */}
      <div className="grid grid-cols-7 bg-slate-50/50 border-b border-slate-100">
        {['อาทิตย์', 'จันทร์', 'อังคาร', 'พุธ', 'พฤหัสบดี', 'ศุกร์', 'เสาร์'].map((d, i) => (
          <div key={i} className={`py-4 text-center text-sm font-semibold ${i === 0 || i === 6 ? 'text-red-500' : 'text-slate-600'}`}>
            <span className="hidden md:inline">{d}</span>
            <span className="md:hidden">{d.charAt(0)}</span>
          </div>
        ))}
      </div>

      {/* Days Grid */}
      <div className="grid grid-cols-7 flex-1 auto-rows-fr">
        {renderDays()}
      </div>

      {!selectedEmployeeId && (
        <div className="p-4 bg-yellow-50 border-t border-yellow-100 text-yellow-800 text-sm flex items-center justify-center gap-2">
            <Info className="w-5 h-5"/> 
            <span>กรุณาค้นหาและเลือกรายชื่อพนักงานจากแถบด้านซ้าย เพื่อจัดการข้อมูล</span>
        </div>
      )}
    </div>
  );
};

