import React, { useMemo } from 'react';
import { BarChart, Bar, XAxis, YAxis, CartesianGrid, Tooltip, Legend, ResponsiveContainer } from 'recharts';
import { LeaveRecord, LeaveType } from '../types';

interface StatsChartProps {
  leaves: LeaveRecord[];
  currentYear: number;
}

const StatsChart: React.FC<StatsChartProps> = ({ leaves, currentYear }) => {
  const data = useMemo(() => {
    // Filter leaves for current year
    const yearLeaves = leaves.filter(l => new Date(l.date).getFullYear() === currentYear);

    // Initialize counters
    const period1 = { // Jan - May (Month 0 - 4)
      name: 'ม.ค. - พ.ค.',
      [LeaveType.PERSONAL]: 0,
      [LeaveType.SICK]: 0,
      [LeaveType.VACATION]: 0,
      [LeaveType.MATERNITY]: 0,
      [LeaveType.ORDINATION]: 0,
    };

    const period2 = { // Jun - Dec (Month 5 - 11)
      name: 'มิ.ย. - ธ.ค.',
      [LeaveType.PERSONAL]: 0,
      [LeaveType.SICK]: 0,
      [LeaveType.VACATION]: 0,
      [LeaveType.MATERNITY]: 0,
      [LeaveType.ORDINATION]: 0,
    };

    yearLeaves.forEach(leave => {
      const month = new Date(leave.date).getMonth();
      const type = leave.type;

      if (month >= 0 && month <= 4) {
        if (period1[type] !== undefined) period1[type]++;
      } else {
        if (period2[type] !== undefined) period2[type]++;
      }
    });

    return [period1, period2];
  }, [leaves, currentYear]);

  // Custom Tooltip for better aesthetics
  const CustomTooltip = ({ active, payload, label }: any) => {
    if (active && payload && payload.length) {
      return (
        <div className="bg-white p-3 rounded-lg shadow-xl border border-slate-100 text-xs">
          <p className="font-bold text-slate-700 mb-2">{label}</p>
          {payload.map((entry: any, index: number) => (
             entry.value > 0 && (
                <div key={index} className="flex items-center gap-2 mb-1">
                    <div className="w-2 h-2 rounded-full" style={{ backgroundColor: entry.color }}></div>
                    <span className="text-slate-500">{entry.name}:</span>
                    <span className="font-bold text-slate-700">{entry.value} วัน</span>
                </div>
             )
          ))}
        </div>
      );
    }
    return null;
  };

  return (
    <div className="w-full h-[300px]">
      <ResponsiveContainer width="100%" height="100%">
        <BarChart
          data={data}
          margin={{
            top: 10,
            right: 10,
            left: -20, // Negative margin to pull chart left since numbers are small
            bottom: 0,
          }}
          barSize={20}
        >
          <CartesianGrid strokeDasharray="3 3" vertical={false} stroke="#f1f5f9" />
          <XAxis 
            dataKey="name" 
            axisLine={false} 
            tickLine={false} 
            tick={{ fill: '#94a3b8', fontSize: 12 }} 
            dy={10}
          />
          <YAxis 
            axisLine={false} 
            tickLine={false} 
            tick={{ fill: '#94a3b8', fontSize: 12 }} 
            allowDecimals={false}
          />
          <Tooltip content={<CustomTooltip />} cursor={{ fill: '#f8fafc' }} />
          <Legend 
            wrapperStyle={{ paddingTop: '20px', fontSize: '12px' }} 
            iconType="circle"
          />
          <Bar dataKey={LeaveType.PERSONAL} name="กิจส่วนตัว" fill="#3b82f6" radius={[4, 4, 0, 0]} stackId="a" />
          <Bar dataKey={LeaveType.SICK} name="ป่วย" fill="#ef4444" radius={[4, 4, 0, 0]} stackId="a" />
          <Bar dataKey={LeaveType.VACATION} name="พักผ่อน" fill="#22c55e" radius={[4, 4, 0, 0]} stackId="a" />
          <Bar dataKey={LeaveType.MATERNITY} name="คลอดบุตร" fill="#ec4899" radius={[4, 4, 0, 0]} stackId="a" />
          <Bar dataKey={LeaveType.ORDINATION} name="อุปสมบท" fill="#eab308" radius={[4, 4, 0, 0]} stackId="a" />
        </BarChart>
      </ResponsiveContainer>
    </div>
  );
};

