import React, { useState, useMemo } from 'react';
import { ChevronLeft, ChevronRight, Info, Calendar as CalendarIcon } from 'lucide-react';
import { LeaveRecord, LeaveType, LEAVE_COLORS } from '../types';

interface CalendarViewProps {
  leaves: LeaveRecord[];
  onDateClick: (dateStr: string) => void;
  selectedEmployeeId: string | null;
}

const CalendarView: React.FC<CalendarViewProps> = ({ leaves, onDateClick, selectedEmployeeId }) => {
  const [currentDate, setCurrentDate] = useState(new Date());

  const year = currentDate.getFullYear();
  const month = currentDate.getMonth();

  const daysInMonth = new Date(year, month + 1, 0).getDate();
  const firstDayOfMonth = new Date(year, month, 1).getDay(); // 0 = Sunday

  const prevMonth = () => setCurrentDate(new Date(year, month - 1, 1));
  const nextMonth = () => setCurrentDate(new Date(year, month + 1, 1));

  // Filter leaves for this view
  const leavesMap = useMemo(() => {
    const map: Record<string, LeaveType> = {};
    leaves.forEach(l => {
      if (selectedEmployeeId && l.employeeId === selectedEmployeeId) {
        map[l.date] = l.type;
      }
    });
    return map;
  }, [leaves, selectedEmployeeId]);

  const renderDays = () => {
    const days = [];

    // Padding
    for (let i = 0; i < firstDayOfMonth; i++) {
      days.push(<div key={`empty-${i}`} className="min-h-[100px] md:min-h-[120px] bg-slate-50/20 border-r border-b border-slate-100"></div>);
    }

    // Days
    for (let i = 1; i <= daysInMonth; i++) {
      const dayStr = i.toString().padStart(2, '0');
      const monthStr = (month + 1).toString().padStart(2, '0');
      const dateStr = `${year}-${monthStr}-${dayStr}`;
      const leaveType = leavesMap[dateStr];
      const isToday = new Date().toDateString() === new Date(year, month, i).toDateString();
      const isWeekend = new Date(year, month, i).getDay() === 0 || new Date(year, month, i).getDay() === 6;

      days.push(
        <div 
          key={i} 
          onClick={() => selectedEmployeeId && onDateClick(dateStr)}
          className={`min-h-[100px] md:min-h-[120px] border-r border-b border-slate-100 p-2 relative transition-all duration-150 group
            ${selectedEmployeeId ? 'cursor-pointer hover:bg-slate-50' : 'cursor-not-allowed opacity-60'}
            ${isToday ? 'bg-blue-50/40' : 'bg-white'}
          `}
        >
          <div className="flex justify-between items-start mb-1">
            <span className={`
                text-sm font-medium h-7 w-7 flex items-center justify-center rounded-full
                ${isToday ? 'bg-blue-700 text-white' : isWeekend ? 'text-red-500' : 'text-slate-700'}
            `}>
              {i}
            </span>
          </div>

          {leaveType && (
            <div className={`
                mt-1.5 px-2 py-1 rounded text-[10px] text-white font-medium truncate shadow-sm 
                ${LEAVE_COLORS[leaveType]}
            `}>
              {leaveType}
            </div>
          )}

          {!selectedEmployeeId && i === 1 && (
            <div className="absolute inset-0 flex items-center justify-center p-2 pointer-events-none">
                <span className="bg-slate-100 text-slate-400 text-[10px] px-2 py-1 rounded border border-slate-200 whitespace-nowrap">
                    เลือกพนักงาน
                </span>
            </div>
          )}
        </div>
      );
    }
    return days;
  };

  const thaiMonths = [
    "มกราคม", "กุมภาพันธ์", "มีนาคม", "เมษายน", "พฤษภาคม", "มิถุนายน",
    "กรกฎาคม", "สิงหาคม", "กันยายน", "ตุลาคม", "พฤศจิกายน", "ธันวาคม"
  ];

  return (
    <div className="bg-white h-full flex flex-col">
      {/* Header */}
      <div className="px-6 py-4 flex items-center justify-between border-b border-slate-200 bg-white">
        <div className="flex items-center gap-3">
             <div className="bg-white border border-slate-200 p-2 rounded-md shadow-sm">
                 <CalendarIcon className="w-5 h-5 text-slate-700" />
             </div>
             <div>
                <h2 className="text-xl font-bold text-slate-800 flex items-baseline gap-2">
                {thaiMonths[month]} <span className="text-slate-300 font-light">|</span> {year + 543}
                </h2>
             </div>
        </div>

        <div className="flex items-center gap-1 bg-white border border-slate-200 rounded-md p-0.5 shadow-sm">
            <button onClick={prevMonth} className="p-1.5 hover:bg-slate-100 rounded text-slate-600 transition-all">
            <ChevronLeft className="w-5 h-5" />
            </button>
            <div className="w-px h-5 bg-slate-200 mx-1"></div>
            <button onClick={nextMonth} className="p-1.5 hover:bg-slate-100 rounded text-slate-600 transition-all">
            <ChevronRight className="w-5 h-5" />
            </button>
        </div>
      </div>

      {/* Weekdays */}
      <div className="grid grid-cols-7 border-b border-slate-200 bg-slate-50">
        {['อาทิตย์', 'จันทร์', 'อังคาร', 'พุธ', 'พฤหัสบดี', 'ศุกร์', 'เสาร์'].map((d, i) => (
          <div key={i} className={`py-3 text-center text-xs font-bold border-r border-slate-200 last:border-r-0 ${i === 0 || i === 6 ? 'text-red-600' : 'text-slate-600'}`}>
            <span className="hidden md:inline">{d}</span>
            <span className="md:hidden">{d.charAt(0)}</span>
          </div>
        ))}
      </div>

      {/* Days Grid */}
      <div className="grid grid-cols-7 flex-1 auto-rows-fr bg-slate-200 gap-px border-b border-slate-200">
        {renderDays()}
      </div>

      {!selectedEmployeeId && (
        <div className="p-3 bg-slate-50 border-t border-slate-200 text-slate-500 text-xs flex items-center justify-center gap-2">
            <Info className="w-4 h-4"/> 
            <span>กรุณาค้นหาและเลือกรายชื่อพนักงานจากแถบด้านซ้าย เพื่อจัดการข้อมูล</span>
        </div>
      )}
    </div>
  );
};

export default CalendarView;

import React, { useMemo } from 'react';
import { BarChart, Bar, XAxis, YAxis, CartesianGrid, Tooltip, Legend, ResponsiveContainer } from 'recharts';
import { LeaveRecord, LeaveType } from '../types';

interface StatsChartProps {
  leaves: LeaveRecord[];
  currentYear: number;
}

const StatsChart: React.FC<StatsChartProps> = ({ leaves, currentYear }) => {
  const data = useMemo(() => {
    // Filter leaves for current year
    const yearLeaves = leaves.filter(l => new Date(l.date).getFullYear() === currentYear);

    // Initialize counters
    const period1 = { // Jan - May (Month 0 - 4)
      name: 'ม.ค. - พ.ค.',
      [LeaveType.PERSONAL]: 0,
      [LeaveType.SICK]: 0,
      [LeaveType.VACATION]: 0,
      [LeaveType.MATERNITY]: 0,
      [LeaveType.ORDINATION]: 0,
    };

    const period2 = { // Jun - Dec (Month 5 - 11)
      name: 'มิ.ย. - ธ.ค.',
      [LeaveType.PERSONAL]: 0,
      [LeaveType.SICK]: 0,
      [LeaveType.VACATION]: 0,
      [LeaveType.MATERNITY]: 0,
      [LeaveType.ORDINATION]: 0,
    };

    yearLeaves.forEach(leave => {
      const month = new Date(leave.date).getMonth();
      const type = leave.type;

      if (month >= 0 && month <= 4) {
        if (period1[type] !== undefined) period1[type]++;
      } else {
        if (period2[type] !== undefined) period2[type]++;
      }
    });

    return [period1, period2];
  }, [leaves, currentYear]);

  // Custom Tooltip for better aesthetics
  const CustomTooltip = ({ active, payload, label }: any) => {
    if (active && payload && payload.length) {
      return (
        <div className="bg-white p-3 rounded shadow-lg border border-slate-200 text-xs">
          <p className="font-bold text-slate-800 mb-2 border-b border-slate-100 pb-1">{label}</p>
          {payload.map((entry: any, index: number) => (
             entry.value > 0 && (
                <div key={index} className="flex items-center justify-between gap-4 mb-1">
                    <div className="flex items-center gap-2">
                        <div className="w-2 h-2 rounded-sm" style={{ backgroundColor: entry.color }}></div>
                        <span className="text-slate-600">{entry.name}</span>
                    </div>
                    <span className="font-bold text-slate-800">{entry.value} วัน</span>
                </div>
             )
          ))}
        </div>
      );
    }
    return null;
  };

  return (
    <div className="w-full h-[250px]">
      <ResponsiveContainer width="100%" height="100%">
        <BarChart
          data={data}
          margin={{
            top: 10,
            right: 0,
            left: -25, 
            bottom: 0,
          }}
          barSize={16}
        >
          <CartesianGrid strokeDasharray="3 3" vertical={false} stroke="#e2e8f0" />
          <XAxis 
            dataKey="name" 
            axisLine={false} 
            tickLine={false} 
            tick={{ fill: '#64748b', fontSize: 11, fontWeight: 500 }} 
            dy={10}
          />
          <YAxis 
            axisLine={false} 
            tickLine={false} 
            tick={{ fill: '#64748b', fontSize: 11 }} 
            allowDecimals={false}
          />
          <Tooltip content={<CustomTooltip />} cursor={{ fill: '#f8fafc' }} />
          <Legend 
            wrapperStyle={{ paddingTop: '15px', fontSize: '11px', color: '#475569' }} 
            iconType="square"
          />
          {/* Using formal colors from types.ts logic implicitly via direct hex codes */}
          <Bar dataKey={LeaveType.PERSONAL} name="กิจส่วนตัว" fill="#2563eb" stackId="a" />
          <Bar dataKey={LeaveType.SICK} name="ป่วย" fill="#dc2626" stackId="a" />
          <Bar dataKey={LeaveType.VACATION} name="พักผ่อน" fill="#059669" stackId="a" />
          <Bar dataKey={LeaveType.MATERNITY} name="คลอดบุตร" fill="#db2777" stackId="a" />
          <Bar dataKey={LeaveType.ORDINATION} name="อุปสมบท" fill="#d97706" stackId="a" />
        </BarChart>
      </ResponsiveContainer>
    </div>
  );
};

export default StatsChart;

