          {holidayName && (
             <div className="mt-1 mb-1 relative z-10 shrink-0">
                <span className="text-[10px] leading-tight text-slate-600 font-semibold bg-slate-200/70 px-1.5 py-0.5 rounded border border-slate-200 block w-fit max-w-full truncate shadow-sm">
