                    } else {
                        // Others: Faded out
                        styleClass = 'opacity-30 grayscale-[30%] z-0';
                    }
                } else {
                    // Normal view
                    styleClass = 'opacity-90 hover:opacity-100';
                }

                return (
                    <div 
                        key={idx}
