                    <p className="text-indigo-100 text-xs">
                        รายงานสรุปผลสุขภาพการทำงานและวันลาของ: <span className="font-semibold text-white">{selectedEmployee?.name}</span>
                    </p>
                </div>
                <button onClick={() => setIsAiModalOpen(false)} className="text-indigo-200 hover:text-white">
                    <X className="w-5 h-5" />
                </button>
            </div>

            <div className="p-6 overflow-y-auto bg-white min-h-[300px]">
                {isAiLoading ? (
                    <div className="flex flex-col items-center justify-center py-12 text-slate-400">
                        <Activity className="w-8 h-8 animate-spin mb-3 text-indigo-500" />
                        <p className="font-medium text-sm">กำลังวิเคราะห์ข้อมูล...</p>
