          </div>

          {/* Stats Section */}
          <div className="bg-white rounded-lg shadow-sm border border-slate-200 overflow-hidden">
             <div className="px-5 py-4 border-b border-slate-100 bg-slate-50/50 flex items-center justify-between">
                <h2 className="text-slate-800 font-bold text-sm uppercase tracking-wide flex items-center gap-2">
                   <LayoutDashboard className="w-4 h-4 text-slate-500" />
                   สถิติประจำปี
                </h2>
                <span className="text-xs font-bold bg-white border border-slate-200 text-slate-600 px-2 py-0.5 rounded">
                    {new Date().getFullYear() + 543}
                </span>
             </div>
             <div className="p-4">
                <StatsChart 
                    leaves={selectedEmployee 
