                <button onClick={() => setIsLeaveModalOpen(false)} className="text-slate-400 hover:text-slate-600">
                    <X className="w-5 h-5" />
                </button>
            </div>

            <div className="p-6">
                <div className="grid grid-cols-2 gap-4 mb-4">
                    <div>
                        <label className="block text-xs font-semibold text-slate-600 mb-1.5">จากวันที่</label>
                        <div className="relative group cursor-pointer">
                            <div className="w-full flex items-center bg-white border border-slate-300 rounded-md overflow-hidden transition-colors group-hover:border-blue-400 h-[38px]">
