import React, { useState, useMemo, useRef } from 'react';
import { 
  Users, Activity, Database, Search, Calendar as CalendarIcon, 
  ArrowLeft, CheckCircle2, Bot, LayoutDashboard, ChevronRight, UserPlus, X, Briefcase,
  Pencil, Trash2, Save, AlertTriangle, CalendarRange, Clock
} from 'lucide-react';
import { Department, Employee, LeaveRecord, LeaveType, LEAVE_COLORS } from './types';
import { INITIAL_EMPLOYEES, INITIAL_LEAVES, DEPARTMENTS, getHolidayName } from './constants';
import CalendarView from './components/CalendarView';
import StatsChart from './components/StatsChart';
import { analyzeLeaveData } from './services/geminiService';

function App() {
  const [currentDepartment, setCurrentDepartment] = useState<Department | null>(null);
  const [employees, setEmployees] = useState<Employee[]>(INITIAL_EMPLOYEES);
  const [searchQuery, setSearchQuery] = useState('');
  const [selectedEmployee, setSelectedEmployee] = useState<Employee | null>(null);
  const [leaves, setLeaves] = useState<LeaveRecord[]>(INITIAL_LEAVES);

  // Modal State: Leave
  const [isLeaveModalOpen, setIsLeaveModalOpen] = useState(false);
  const [leaveStartDate, setLeaveStartDate] = useState<string>('');
  const [leaveEndDate, setLeaveEndDate] = useState<string>('');
  const [leaveType, setLeaveType] = useState<LeaveType>(LeaveType.PERSONAL);
  const [skipWeekends, setSkipWeekends] = useState(false);
  const [skipHolidays, setSkipHolidays] = useState(false);

  // Modal State: User Management (Add/Edit/List)
  const [isManageUserModalOpen, setIsManageUserModalOpen] = useState(false);
  const [userForm, setUserForm] = useState({ name: '', position: '' });
  const [editingEmployeeId, setEditingEmployeeId] = useState<string | null>(null);

  // Modal State: Delete Confirmation
  const [deleteConfirm, setDeleteConfirm] = useState<{isOpen: boolean, id: string | null, name: string}>({
    isOpen: false, id: null, name: ''
  });

  // AI State
  const [aiAnalysis, setAiAnalysis] = useState<string>('');
  const [isAiLoading, setIsAiLoading] = useState(false);
  const [isAiModalOpen, setIsAiModalOpen] = useState(false);

  // Refs for date inputs to programmatic control
  const startDateRef = useRef<HTMLInputElement>(null);
  const endDateRef = useRef<HTMLInputElement>(null);

  // Filter employees based on department (for management list)
  const departmentEmployees = useMemo(() => {
    if (!currentDepartment) return [];
    return employees.filter(emp => emp.department === currentDepartment);
  }, [currentDepartment, employees]);

  // Filter employees based on department and search (for sidebar)
  const filteredEmployees = useMemo(() => {
    if (!currentDepartment) return [];
    return employees.filter(emp => {
      const matchDept = emp.department === currentDepartment;
      const matchSearch = emp.name.toLowerCase().includes(searchQuery.toLowerCase());
      return matchDept && matchSearch;
    });
  }, [currentDepartment, searchQuery, employees]);

  // Helper to format date for display (DD/MM/YYYY + 543)
  const formatDateDisplay = (dateStr: string) => {
    if (!dateStr) return "";
    const [y, m, d] = dateStr.split('-');
    return `${d}/${m}/${parseInt(y) + 543}`;
  };

  // Calculate leave dates dynamically for display and saving
  const calculatedDatesToAdd = useMemo(() => {
    if (!leaveStartDate || !leaveEndDate) return [];

    const start = new Date(leaveStartDate);
    const end = new Date(leaveEndDate);

    // Safety check
    if (isNaN(start.getTime()) || isNaN(end.getTime()) || start > end) return [];

    const dates: string[] = [];
    const loopDate = new Date(start);

    while (loopDate <= end) {
        const dateStr = loopDate.toISOString().split('T')[0];

        let shouldAdd = true;
        const dayOfWeek = loopDate.getUTCDay(); // 0 = Sunday, 6 = Saturday

        if (skipWeekends && (dayOfWeek === 0 || dayOfWeek === 6)) {
            shouldAdd = false;
        }

        if (shouldAdd && skipHolidays) {
            const [y, m, d] = dateStr.split('-').map(Number);
            const checkDate = new Date(y, m - 1, d); 
            if (getHolidayName(checkDate)) {
                shouldAdd = false;
            }
        }

        if (shouldAdd) {
            dates.push(dateStr);
        }

        loopDate.setDate(loopDate.getDate() + 1);
    }
    return dates;
  }, [leaveStartDate, leaveEndDate, skipWeekends, skipHolidays]);

  // Handle department selection
  const handleDepartmentSelect = (dept: Department) => {
    setCurrentDepartment(dept);
    setSearchQuery('');
    setSelectedEmployee(null);
  };

  // Handle user selection from autocomplete
  const handleUserSelect = (emp: Employee) => {
    setSelectedEmployee(emp);
    setSearchQuery(emp.name); // Set input to selected name
  };

  // Handle Calendar Date Click
  const handleDateClick = (dateStr: string) => {
    // Keeping logic: Must select employee to add leave.
    if (!selectedEmployee) return;

    setLeaveStartDate(dateStr);
    setLeaveEndDate(dateStr); // Default end date is same as start date
    setSkipWeekends(true); // Default nice-to-have
    setSkipHolidays(true); // Default nice-to-have

    // Check if leave already exists on start date to pre-fill type
    const existing = leaves.find(l => l.employeeId === selectedEmployee.id && l.date === dateStr);
    if (existing) {
        setLeaveType(existing.type);
    } else {
        setLeaveType(LeaveType.PERSONAL);
    }

    setIsLeaveModalOpen(true);
  };

  // Save Leave
  const handleSaveLeave = () => {
    if (!selectedEmployee || calculatedDatesToAdd.length === 0) return;

    setLeaves(prev => {
      // Remove existing records for this user that overlap with the new dates to be added (overwrite)
      const filtered = prev.filter(l => !(l.employeeId === selectedEmployee.id && calculatedDatesToAdd.includes(l.date)));

      const newLeaves = calculatedDatesToAdd.map(date => ({
        id: Math.random().toString(36).substr(2, 9),
        employeeId: selectedEmployee.id!,
        date: date,
        type: leaveType
      }));

      return [...filtered, ...newLeaves];
    });
    setIsLeaveModalOpen(false);
  };

  // --- User Management Logic ---

  const handleUserSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    if (!userForm.name || !userForm.position || !currentDepartment) return;

    if (editingEmployeeId) {
        // Update Existing
        setEmployees(prev => prev.map(emp => 
            emp.id === editingEmployeeId 
                ? { ...emp, name: userForm.name, position: userForm.position }
                : emp
        ));

        // Update selected employee if it was the one edited
        if (selectedEmployee?.id === editingEmployeeId) {
            setSelectedEmployee(prev => prev ? { ...prev, name: userForm.name, position: userForm.position } : null);
            setSearchQuery(userForm.name);
        }

        setEditingEmployeeId(null);
    } else {
        // Add New
        const newEmp: Employee = {
            id: Math.random().toString(36).substr(2, 9),
            name: userForm.name,
            position: userForm.position,
            department: currentDepartment
        };
        setEmployees(prev => [...prev, newEmp]);
    }

    // Reset form but keep modal open
    setUserForm({ name: '', position: '' });
  };

  const handleEditUserClick = (emp: Employee) => {
    setEditingEmployeeId(emp.id);
    setUserForm({ name: emp.name, position: emp.position });
  };

  const handleDeleteUserClick = (emp: Employee) => {
    setDeleteConfirm({ isOpen: true, id: emp.id, name: emp.name });
  };

  const executeDeleteUser = () => {
    const id = deleteConfirm.id;
    if (!id) return;

    setEmployees(prev => prev.filter(e => e.id !== id));
    setLeaves(prev => prev.filter(l => l.employeeId !== id)); // Cleanup leaves
    if (selectedEmployee?.id === id) {
        setSelectedEmployee(null);
        setSearchQuery('');
    }
    // If editing this user, cancel edit
    if (editingEmployeeId === id) {
        setEditingEmployeeId(null);
        setUserForm({ name: '', position: '' });
    }
    setDeleteConfirm({ isOpen: false, id: null, name: '' });
  };

  const handleCancelEdit = () => {
    setEditingEmployeeId(null);
    setUserForm({ name: '', position: '' });
  };

  // Trigger AI Analysis
  const handleAiAnalyze = async () => {
    if (!selectedEmployee) return;
    setIsAiModalOpen(true);
    setIsAiLoading(true);
    setAiAnalysis('');

    const result = await analyzeLeaveData(selectedEmployee.name, leaves, employees);
    setAiAnalysis(result);
    setIsAiLoading(false);
  };

  // Render Landing Page
  if (!currentDepartment) {
    return (
      <div className="min-h-screen bg-slate-50 flex flex-col items-center justify-center p-6 relative">
        <div className="text-center mb-12 relative z-10">
          <div className="inline-flex items-center gap-2 bg-white px-4 py-2 rounded-md shadow-sm border border-slate-200 mb-6 text-slate-600 text-sm font-medium">
             <CalendarIcon className="w-4 h-4 text-slate-500" />
             <span className="tracking-wide">ระบบบริหารจัดการวันลาออนไลน์</span>
          </div>
          <h1 className="text-3xl md:text-5xl font-bold text-slate-800 mb-4 tracking-tight">
             กรุณาเลือก<span className="text-blue-700">หน่วยงาน</span>ต้นสังกัด
          </h1>
          <p className="text-slate-500 text-base md:text-lg max-w-2xl mx-auto font-light">
            ระบบสารสนเทศเพื่อการจัดการทรัพยากรบุคคลและประวัติการลา
          </p>
        </div>

        <div className="grid grid-cols-1 md:grid-cols-3 gap-6 max-w-5xl w-full relative z-10 px-4">
          {DEPARTMENTS.map((dept) => {
            const Icon = dept.icon === 'Users' ? Users : dept.icon === 'Activity' ? Activity : Database;
            return (
              <button
                key={dept.id}
                onClick={() => handleDepartmentSelect(dept.id as Department)}
                className="group relative bg-white rounded-lg p-8 shadow-sm hover:shadow-md transition-all duration-200 border border-slate-200 hover:border-blue-300 text-left"
              >
                <div className={`absolute top-0 left-0 w-1 h-full ${dept.color} transition-all duration-200 group-hover:w-2 rounded-l-lg`}></div>
                <div className="flex flex-col h-full justify-between gap-6">
                  <div className="flex items-start justify-between">
                     <div className="bg-slate-50 p-3 rounded-lg border border-slate-100 group-hover:bg-blue-50 group-hover:border-blue-100 transition-colors">
                        <Icon className={`w-6 h-6 text-slate-700 group-hover:text-blue-700`} />
                     </div>
                  </div>

                  <div>
                    <h3 className="text-xl font-bold text-slate-800 mb-1">{dept.label}</h3>
                    <div className="flex items-center text-slate-400 text-sm gap-1 group-hover:text-blue-700 transition-colors font-medium">
                      <span>เข้าสู่ระบบ</span>
                      <ChevronRight className="w-4 h-4" />
                    </div>
                  </div>
                </div>
              </button>
            );
          })}
        </div>
      </div>
    );
  }

  // Render Dashboard
  return (
    <div className="min-h-screen bg-slate-50 flex flex-col font-sans">
      {/* Navbar - Formal Style */}
      <nav className="bg-white shadow-sm border-b border-slate-200 sticky top-0 z-40">
        <div className="max-w-[1600px] mx-auto px-4 md:px-6 py-4 flex items-center justify-between">
          <div className="flex items-center gap-4">
            <button 
              onClick={() => setCurrentDepartment(null)}
              className="p-2 hover:bg-slate-100 rounded-lg text-slate-600 transition-colors border border-transparent"
            >
              <ArrowLeft className="w-5 h-5" />
            </button>
            <div className="flex flex-col">
                <h1 className="text-xl font-bold text-slate-800 leading-none">{currentDepartment}</h1>
                <span className="text-xs text-slate-500 mt-1">HR Management System</span>
            </div>
          </div>

          <div className="flex items-center gap-4">
             <div className="hidden lg:flex items-center gap-2 bg-slate-50 px-4 py-2 rounded-lg border border-slate-200">
               {Object.entries(LEAVE_COLORS).map(([type, color]) => (
                <div key={type} className="flex items-center gap-2 mr-4 last:mr-0">
                  <div className={`w-2 h-2 rounded-sm ${color}`}></div>
                  <span className="text-xs text-slate-600 font-medium">{type}</span>
                </div>
              ))}
             </div>
             <div className="h-9 w-9 rounded-full bg-slate-800 flex items-center justify-center text-white shadow-sm">
                <Users className="w-4 h-4" />
             </div>
          </div>
        </div>
      </nav>

      {/* Main Content */}
      <main className="flex-1 max-w-[1600px] w-full mx-auto p-4 md:p-6 grid grid-cols-1 lg:grid-cols-12 gap-6 items-start">

        {/* Sidebar */}
        <aside className="lg:col-span-3 space-y-6 lg:sticky lg:top-24">

          {/* Search & Actions Card */}
          <div className="bg-white rounded-lg shadow-sm border border-slate-200 overflow-hidden">
             <div className="px-5 py-4 border-b border-slate-100 bg-slate-50/50 flex justify-between items-center">
                <h2 className="text-slate-800 font-bold text-sm uppercase tracking-wide flex items-center gap-2">
                   <Search className="w-4 h-4 text-slate-500" />
                   รายชื่อพนักงาน
                </h2>
                <button 
                    onClick={() => setIsManageUserModalOpen(true)}
                    className="text-xs flex items-center gap-1 bg-white border border-slate-200 px-2 py-1 rounded text-blue-700 hover:border-blue-300 hover:bg-blue-50 transition-all font-medium"
                >
                    <UserPlus className="w-3 h-3" />
                    จัดการรายชื่อ
                </button>
             </div>

             <div className="p-5">
                <div className="relative mb-4">
                  <Search className="absolute left-3 top-1/2 -translate-y-1/2 text-slate-400 w-4 h-4" />
                  <input
                    type="text"
                    className="w-full pl-10 pr-4 py-2.5 bg-white border border-slate-200 rounded-lg focus:ring-1 focus:ring-blue-500 focus:border-blue-500 outline-none transition-all text-sm text-slate-900 placeholder-slate-400 font-medium"
                    placeholder="ค้นหาชื่อ หรืออักษรย่อ..."
                    value={searchQuery}
                    onChange={(e) => {
                        setSearchQuery(e.target.value);
                        if (selectedEmployee && e.target.value !== selectedEmployee.name) {
                            setSelectedEmployee(null);
                        }
                    }}
                  />

                  {/* Autocomplete */}
                  {searchQuery && !selectedEmployee && filteredEmployees.length > 0 && (
                    <div className="absolute top-full left-0 right-0 mt-1 bg-white rounded-lg shadow-lg border border-slate-200 max-h-60 overflow-y-auto z-50">
                      {filteredEmployees.map(emp => (
                        <button
                          key={emp.id}
                          onClick={() => handleUserSelect(emp)}
                          className="w-full text-left px-4 py-2.5 hover:bg-slate-50 flex items-center gap-3 transition-colors border-b border-slate-50 last:border-0"
                        >
                          <div className="w-7 h-7 rounded bg-slate-100 text-slate-600 flex items-center justify-center font-bold text-xs shrink-0 border border-slate-200">
                            {emp.name.charAt(0)}
                          </div>
                          <div>
                              <p className="text-slate-800 text-sm font-medium">{emp.name}</p>
                              <p className="text-xs text-slate-500">{emp.position}</p>
                          </div>
                        </button>
                      ))}
                    </div>
                  )}
                </div>

                {selectedEmployee ? (
                  <div className="bg-slate-50 border border-slate-200 rounded-lg p-4 animate-fade-in">
                      <div className="flex items-start justify-between mb-4">
                         <div className="flex items-start gap-3">
                            <div className="w-10 h-10 rounded-lg bg-white border border-slate-200 text-slate-700 flex items-center justify-center font-bold text-lg shadow-sm">
                                {selectedEmployee.name.charAt(0)}
                            </div>
                            <div>
                                <h3 className="font-bold text-slate-800 text-sm">{selectedEmployee.name}</h3>
                                <p className="text-xs text-slate-500 flex items-center gap-1 mt-0.5">
                                    <Briefcase className="w-3 h-3" />
                                    {selectedEmployee.position}
                                </p>
                            </div>
                         </div>
                         <CheckCircle2 className="text-blue-600 w-5 h-5" />
                      </div>

                      <button 
                        onClick={handleAiAnalyze}
                        className="w-full flex items-center justify-center gap-2 bg-white border border-indigo-200 text-indigo-700 py-2 rounded-md hover:bg-indigo-50 transition-all text-xs font-semibold shadow-sm"
                      >
                          <Bot className="w-3.5 h-3.5" />
                          วิเคราะห์ข้อมูล (AI Insight)
                      </button>
                  </div>
                ) : (
                  <div className="text-center py-8 px-4 border border-dashed border-slate-300 rounded-lg">
                     <Users className="w-6 h-6 text-slate-300 mx-auto mb-2" />
                     <p className="text-xs text-slate-400">เลือกรายชื่อเพื่อดูข้อมูล หรือบันทึกวันลา</p>
                  </div>
                )}
             </div>
          </div>

          {/* Stats Section */}
          <div className="bg-white rounded-lg shadow-sm border border-slate-200 overflow-hidden">
             <div className="px-5 py-4 border-b border-slate-100 bg-slate-50/50 flex items-center justify-between">
                <h2 className="text-slate-800 font-bold text-sm uppercase tracking-wide flex items-center gap-2">
                   <LayoutDashboard className="w-4 h-4 text-slate-500" />
                   สถิติประจำปี
                </h2>
                <span className="text-xs font-bold bg-white border border-slate-200 text-slate-600 px-2 py-0.5 rounded">
                    {new Date().getFullYear() + 543}
                </span>
             </div>
             <div className="p-4">
                <StatsChart 
                    leaves={selectedEmployee 
                        ? leaves.filter(l => l.employeeId === selectedEmployee.id) 
                        : leaves.filter(l => departmentEmployees.some(e => e.id === l.employeeId)) // Show dept stats if no user selected
                    }
                    currentYear={new Date().getFullYear()} 
                />
             </div>
          </div>
        </aside>

        {/* Calendar View */}
        <section className="lg:col-span-9 h-full">
            <div className="bg-white rounded-lg shadow-sm border border-slate-200 overflow-hidden min-h-[650px]">
                <CalendarView 
                    leaves={leaves}
                    employees={departmentEmployees}
                    selectedEmployeeId={selectedEmployee?.id || null}
                    onDateClick={handleDateClick}
                />
            </div>
        </section>
      </main>

      {/* Modal: Leave Recording */}
      {isLeaveModalOpen && (
        <div className="fixed inset-0 bg-slate-900/40 backdrop-blur-sm z-50 flex items-center justify-center p-4">
          <style>{`
            /* CSS Hack to make the entire date input clickable to open the picker */
            .date-picker-trigger::-webkit-calendar-picker-indicator {
                position: absolute;
                top: 0;
                left: 0;
                right: 0;
                bottom: 0;
                width: auto;
                height: auto;
                color: transparent;
                background: transparent;
                cursor: pointer;
            }
          `}</style>
          <div className="bg-white rounded-lg shadow-2xl w-full max-w-md p-0 overflow-hidden animate-in fade-in zoom-in-95 duration-200">
            <div className="bg-slate-50 px-6 py-4 border-b border-slate-100 flex justify-between items-center">
                <h3 className="font-bold text-slate-800 flex items-center gap-2">
                    <CalendarRange className="w-5 h-5 text-blue-600" />
                    บันทึกการลา
                </h3>
                <button onClick={() => setIsLeaveModalOpen(false)} className="text-slate-400 hover:text-slate-600">
                    <X className="w-5 h-5" />
                </button>
            </div>

            <div className="p-6">
                <div className="grid grid-cols-2 gap-4 mb-4">
                    <div>
                        <label className="block text-xs font-semibold text-slate-600 mb-1.5">จากวันที่</label>
                        <div className="relative group cursor-pointer">
                            <div className="w-full flex items-center bg-white border border-slate-300 rounded-md overflow-hidden transition-colors group-hover:border-blue-400 h-[38px]">
                                <div className="flex-1 px-3 text-sm text-slate-800 truncate">
                                     {leaveStartDate ? formatDateDisplay(leaveStartDate) : <span className="text-slate-400">วว/ดด/ปปปป</span>}
                                </div>
                                <div className="bg-slate-50 border-l border-slate-200 h-full px-3 flex items-center justify-center group-hover:bg-blue-50 transition-colors">
                                    <CalendarIcon className="w-4 h-4 text-slate-500 group-hover:text-blue-600" />
                                </div>
                            </div>
                            <input 
                                ref={startDateRef}
                                type="date" 
                                value={leaveStartDate}
                                onChange={(e) => {
                                    setLeaveStartDate(e.target.value);
                                    if (e.target.value > leaveEndDate) {
                                        setLeaveEndDate(e.target.value);
                                    }
                                }}
                                className="date-picker-trigger absolute inset-0 w-full h-full opacity-0 cursor-pointer z-10"
                            />
                        </div>
                    </div>
                    <div>
                        <label className="block text-xs font-semibold text-slate-600 mb-1.5">ถึงวันที่</label>
                        <div className="relative group cursor-pointer">
                            <div className="w-full flex items-center bg-white border border-slate-300 rounded-md overflow-hidden transition-colors group-hover:border-blue-400 h-[38px]">
                                <div className="flex-1 px-3 text-sm text-slate-800 truncate">
                                    {leaveEndDate ? formatDateDisplay(leaveEndDate) : <span className="text-slate-400">วว/ดด/ปปปป</span>}
                                </div>
                                <div className="bg-slate-50 border-l border-slate-200 h-full px-3 flex items-center justify-center group-hover:bg-blue-50 transition-colors">
                                    <CalendarIcon className="w-4 h-4 text-slate-500 group-hover:text-blue-600" />
                                </div>
                            </div>
                            <input 
                                ref={endDateRef}
                                type="date" 
                                value={leaveEndDate}
                                min={leaveStartDate}
                                onChange={(e) => setLeaveEndDate(e.target.value)}
                                className="date-picker-trigger absolute inset-0 w-full h-full opacity-0 cursor-pointer z-10"
                            />
                        </div>
                    </div>
                </div>

                {/* Duration Display */}
                <div className="mb-4 flex items-center justify-between p-3 bg-indigo-50 border border-indigo-100 rounded-md text-indigo-900">
                    <div className="flex items-center gap-2 text-sm font-semibold">
                        <Clock className="w-4 h-4 text-indigo-600" />
                        <span>รวมจำนวนวันลา</span>
                    </div>
                    <span className="text-lg font-bold text-indigo-700">{calculatedDatesToAdd.length} วัน</span>
                </div>

                <div className="flex flex-col gap-2 mb-4 bg-slate-50 p-3 rounded-md border border-slate-200">
                    <label className="flex items-center gap-2 text-sm text-slate-700 cursor-pointer select-none">
                        <input 
                            type="checkbox" 
                            checked={skipWeekends}
                            onChange={e => setSkipWeekends(e.target.checked)}
                            className="w-4 h-4 rounded text-blue-600 focus:ring-blue-500 border-gray-300"
                        />
                        <span>ข้ามวันเสาร์ - อาทิตย์</span>
                    </label>
                    <label className="flex items-center gap-2 text-sm text-slate-700 cursor-pointer select-none">
                        <input 
                            type="checkbox" 
                            checked={skipHolidays}
                            onChange={e => setSkipHolidays(e.target.checked)}
                            className="w-4 h-4 rounded text-blue-600 focus:ring-blue-500 border-gray-300"
                        />
                        <span>ข้ามวันหยุดนักขัตฤกษ์</span>
                    </label>
                </div>

                <div className="space-y-2 mb-6 max-h-[200px] overflow-y-auto custom-scrollbar pr-1">
                {Object.values(LeaveType).map((type) => (
                    <button
                    key={type}
                    onClick={() => setLeaveType(type)}
                    className={`w-full px-4 py-3 rounded-md border text-sm flex items-center justify-between transition-all ${
                        leaveType === type 
                        ? `border-blue-600 bg-blue-50 text-blue-700 font-semibold shadow-sm`
                        : 'border-slate-200 hover:border-slate-300 hover:bg-slate-50 text-slate-600'
                    }`}
                    >
                    <span>{type}</span>
                    {leaveType === type && <CheckCircle2 className="w-4 h-4" />}
                    </button>
                ))}
                </div>

                <div className="flex gap-3 pt-2 border-t border-slate-100">
                    <button 
                        onClick={() => setIsLeaveModalOpen(false)}
                        className="flex-1 py-2.5 rounded-md border border-slate-300 text-slate-700 hover:bg-slate-50 font-medium text-sm"
                    >
                        ยกเลิก
                    </button>
                    <button 
                        onClick={handleSaveLeave}
                        className="flex-1 py-2.5 rounded-md bg-blue-700 text-white hover:bg-blue-800 font-medium text-sm shadow-sm"
