import React, { useMemo } from 'react';
import { BarChart, Bar, XAxis, YAxis, CartesianGrid, Tooltip, ResponsiveContainer, Cell, LabelList } from 'recharts';
import { LeaveRecord, LeaveType } from '../types';

interface StatsChartProps {
  leaves: LeaveRecord[];
  currentYear: number;
}

// Hex colors matching Tailwind classes in types.ts
const CHART_COLORS: Record<LeaveType, string> = {
  [LeaveType.PERSONAL]: '#2563eb', // blue-600
  [LeaveType.SICK]: '#dc2626',     // red-600
  [LeaveType.VACATION]: '#059669', // emerald-600
  [LeaveType.MATERNITY]: '#db2777',// pink-600
  [LeaveType.ORDINATION]: '#d97706'// amber-600
};

const StatsChart: React.FC<StatsChartProps> = ({ leaves, currentYear }) => {
  const data = useMemo(() => {
    // Filter leaves for current year
    const yearLeaves = leaves.filter(l => new Date(l.date).getFullYear() === currentYear);

    // Count totals per type
    const counts = yearLeaves.reduce((acc, leave) => {
      acc[leave.type] = (acc[leave.type] || 0) + 1;
      return acc;
    }, {} as Record<LeaveType, number>);

    // Specific Order: กิจส่วนตัว, คลอดบุตร, ป่วย, พักผ่อน, อุปสมบท
    const order = [
      LeaveType.PERSONAL,
      LeaveType.MATERNITY,
      LeaveType.SICK,
      LeaveType.VACATION,
      LeaveType.ORDINATION
    ];

    return order.map(type => ({
      name: type,
      count: counts[type] || 0,
      color: CHART_COLORS[type]
    }));
  }, [leaves, currentYear]);

  // Custom Tooltip
  const CustomTooltip = ({ active, payload, label }: any) => {
    if (active && payload && payload.length) {
