import React, { useMemo } from 'react';
import { BarChart, Bar, XAxis, YAxis, CartesianGrid, Tooltip, ResponsiveContainer, Cell, Legend } from 'recharts';
import { LeaveRecord, LeaveType } from '../types';

interface StatsChartProps {
  leaves: LeaveRecord[];
  currentYear: number;
}

// Color pairs: [Light version for P1, Main version for P2]
const CHART_COLORS: Record<LeaveType, [string, string]> = {
  [LeaveType.PERSONAL]: ['#93c5fd', '#2563eb'], // blue-300, blue-600
  [LeaveType.MATERNITY]: ['#f9a8d4', '#db2777'], // pink-300, pink-600
  [LeaveType.SICK]: ['#fca5a5', '#dc2626'],     // red-300, red-600
  [LeaveType.VACATION]: ['#6ee7b7', '#059669'], // emerald-300, emerald-600
  [LeaveType.ORDINATION]: ['#fcd34d', '#d97706']// amber-300, amber-600
};

const StatsChart: React.FC<StatsChartProps> = ({ leaves, currentYear }) => {
  const data = useMemo(() => {
    // Filter leaves for current year
    const yearLeaves = leaves.filter(l => new Date(l.date).getFullYear() === currentYear);

    // Initial structure for counts
    const counts = {
      [LeaveType.PERSONAL]: { p1: 0, p2: 0 },
      [LeaveType.MATERNITY]: { p1: 0, p2: 0 },
      [LeaveType.SICK]: { p1: 0, p2: 0 },
      [LeaveType.VACATION]: { p1: 0, p2: 0 },
      [LeaveType.ORDINATION]: { p1: 0, p2: 0 }
    };

    yearLeaves.forEach(leave => {
      const month = new Date(leave.date).getMonth(); // 0-11
      // P1: Jan-May (0-4), P2: Jun-Dec (5-11)
      if (month <= 4) {
        counts[leave.type].p1 += 1;
      } else {
        counts[leave.type].p2 += 1;
      }
    });

    // Specific Order: กิจส่วนตัว, คลอดบุตร, ป่วย, พักผ่อน, อุปสมบท
    const order = [
      LeaveType.PERSONAL,
      LeaveType.MATERNITY,
      LeaveType.SICK,
      LeaveType.VACATION,
      LeaveType.ORDINATION
    ];

    return order.map(type => ({
      name: type,
      p1: counts[type].p1,
      p2: counts[type].p2,
      colorP1: CHART_COLORS[type][0],
      colorP2: CHART_COLORS[type][1]
    }));
  }, [leaves, currentYear]);

  // Custom Tooltip
  const CustomTooltip = ({ active, payload, label }: any) => {
    if (active && payload && payload.length) {
      return (
        <div className="bg-white p-3 rounded shadow-xl border border-slate-200 text-xs z-50">
          <p className="font-bold text-slate-800 mb-2 border-b pb-1">{label}</p>
          <div className="space-y-1">
            <div className="flex items-center justify-between gap-4">
              <span className="text-slate-500">ม.ค. - พ.ค.:</span>
              <span className="font-bold text-slate-800">{payload[0].value} วัน</span>
            </div>
            <div className="flex items-center justify-between gap-4">
              <span className="text-slate-500">มิ.ย. - ธ.ค.:</span>
              <span className="font-bold text-slate-800">{payload[1].value} วัน</span>
            </div>
          </div>
        </div>
      );
    }
    return null;
  };

  return (
    <div className="w-full h-[300px]">
      <ResponsiveContainer width="100%" height="100%">
        <BarChart
          layout="vertical"
          data={data}
          margin={{
            top: 5,
            right: 30,
            left: 20,
            bottom: 20,
          }}
          barGap={2}
          barSize={12}
        >
          <CartesianGrid strokeDasharray="3 3" horizontal={false} stroke="#f1f5f9" />

          <XAxis 
            type="number" 
            axisLine={false} 
            tickLine={false} 
            tick={{ fill: '#94a3b8', fontSize: 10 }}
            allowDecimals={false}
          />

          <YAxis 
            dataKey="name" 
            type="category" 
            axisLine={false} 
            tickLine={false}
            width={90}
            tick={{ fill: '#475569', fontSize: 11, fontWeight: 500 }}
          />

          <Tooltip content={<CustomTooltip />} cursor={{ fill: '#f8fafc' }} />

          <Legend 
            verticalAlign="bottom" 
            height={36} 
            content={(props) => (
              <div className="flex justify-center gap-6 mt-4 text-[10px] font-bold uppercase tracking-wider text-slate-400">
                <div className="flex items-center gap-2">
                  <div className="w-3 h-3 rounded-sm bg-slate-300"></div>
                  <span>ม.ค. - พ.ค.</span>
                </div>
                <div className="flex items-center gap-2">
                  <div className="w-3 h-3 rounded-sm bg-slate-600"></div>
                  <span>มิ.ย. - ธ.ค.</span>
                </div>
              </div>
            )}
          />

          <Bar name="ม.ค. - พ.ค." dataKey="p1" radius={[0, 4, 4, 0]}>
            {data.map((entry, index) => (
              <Cell key={`cell-p1-${index}`} fill={entry.colorP1} />
            ))}
          </Bar>

          <Bar name="มิ.ย. - ธ.ค." dataKey="p2" radius={[0, 4, 4, 0]}>
            {data.map((entry, index) => (
              <Cell key={`cell-p2-${index}`} fill={entry.colorP2} />
            ))}
          </Bar>
        </BarChart>
      </ResponsiveContainer>
    </div>
  );
};

export default StatsChart;

import React, { useState, useMemo, useRef } from 'react';
import { 
  Users, Activity, Database, Search, Calendar as CalendarIcon, 
  ArrowLeft, CheckCircle2, Bot, LayoutDashboard, ChevronRight, UserPlus, X, Briefcase,
  Pencil, Trash2, Save, AlertTriangle, CalendarRange, Clock
} from 'lucide-react';
import { Department, Employee, LeaveRecord, LeaveType, LEAVE_COLORS } from './types';
import { INITIAL_EMPLOYEES, INITIAL_LEAVES, DEPARTMENTS, getHolidayName } from './constants';
import CalendarView from './components/CalendarView';
import StatsChart from './components/StatsChart';
import { analyzeLeaveData } from './services/geminiService';

function App() {
  const [currentDepartment, setCurrentDepartment] = useState<Department | null>(null);
  const [employees, setEmployees] = useState<Employee[]>(INITIAL_EMPLOYEES);
  const [searchQuery, setSearchQuery] = useState('');
  const [selectedEmployee, setSelectedEmployee] = useState<Employee | null>(null);
  const [leaves, setLeaves] = useState<LeaveRecord[]>(INITIAL_LEAVES);

  // Modal State: Leave
  const [isLeaveModalOpen, setIsLeaveModalOpen] = useState(false);
  const [leaveStartDate, setLeaveStartDate] = useState<string>('');
  const [leaveEndDate, setLeaveEndDate] = useState<string>('');
  const [leaveType, setLeaveType] = useState<LeaveType>(LeaveType.PERSONAL);
  const [skipWeekends, setSkipWeekends] = useState(false);
  const [skipHolidays, setSkipHolidays] = useState(false);

  // Modal State: User Management (Add/Edit/List)
  const [isManageUserModalOpen, setIsManageUserModalOpen] = useState(false);
  const [userForm, setUserForm] = useState({ name: '', position: '' });
  const [editingEmployeeId, setEditingEmployeeId] = useState<string | null>(null);

  // Modal State: Delete Confirmation
  const [deleteConfirm, setDeleteConfirm] = useState<{isOpen: boolean, id: string | null, name: string}>({
    isOpen: false, id: null, name: ''
  });

  // AI State
  const [aiAnalysis, setAiAnalysis] = useState<string>('');
  const [isAiLoading, setIsAiLoading] = useState(false);
  const [isAiModalOpen, setIsAiModalOpen] = useState(false);

  // Refs for date inputs to programmatic control
  const startDateRef = useRef<HTMLInputElement>(null);
  const endDateRef = useRef<HTMLInputElement>(null);

  // Filter employees based on department (for management list)
  const departmentEmployees = useMemo(() => {
    if (!currentDepartment) return [];
    return employees.filter(emp => emp.department === currentDepartment);
  }, [currentDepartment, employees]);

  // Filter employees based on department and search (for sidebar)
  const filteredEmployees = useMemo(() => {
    if (!currentDepartment) return [];
    return employees.filter(emp => {
      const matchDept = emp.department === currentDepartment;
      const matchSearch = emp.name.toLowerCase().includes(searchQuery.toLowerCase());
      return matchDept && matchSearch;
    });
  }, [currentDepartment, searchQuery, employees]);

  // Helper to format date for display (DD/MM/YYYY + 543)
  const formatDateDisplay = (dateStr: string) => {
    if (!dateStr) return "";
    const [y, m, d] = dateStr.split('-');
    return `${d}/${m}/${parseInt(y) + 543}`;
  };

  // Calculate leave dates dynamically for display and saving
  const calculatedDatesToAdd = useMemo(() => {
    if (!leaveStartDate || !leaveEndDate) return [];

    const start = new Date(leaveStartDate);
    const end = new Date(leaveEndDate);

    // Safety check
    if (isNaN(start.getTime()) || isNaN(end.getTime()) || start > end) return [];

    const dates: string[] = [];
    const loopDate = new Date(start);

    while (loopDate <= end) {
        const dateStr = loopDate.toISOString().split('T')[0];

        let shouldAdd = true;
        const dayOfWeek = loopDate.getUTCDay(); // 0 = Sunday, 6 = Saturday

        if (skipWeekends && (dayOfWeek === 0 || dayOfWeek === 6)) {
            shouldAdd = false;
        }

        if (shouldAdd && skipHolidays) {
            const [y, m, d] = dateStr.split('-').map(Number);
            const checkDate = new Date(y, m - 1, d); 
            if (getHolidayName(checkDate)) {
                shouldAdd = false;
            }
        }

        if (shouldAdd) {
            dates.push(dateStr);
        }

        loopDate.setDate(loopDate.getDate() + 1);
    }
    return dates;
  }, [leaveStartDate, leaveEndDate, skipWeekends, skipHolidays]);

  // Handle department selection
  const handleDepartmentSelect = (dept: Department) => {
    setCurrentDepartment(dept);
    setSearchQuery('');
    setSelectedEmployee(null);
  };

  // Handle user selection from autocomplete
  const handleUserSelect = (emp: Employee) => {
    setSelectedEmployee(emp);
    setSearchQuery(emp.name); // Set input to selected name
  };

  // Handle Calendar Date Click
  const handleDateClick = (dateStr: string) => {
    // Keeping logic: Must select employee to add leave.
    if (!selectedEmployee) return;

    setLeaveStartDate(dateStr);
    setLeaveEndDate(dateStr); // Default end date is same as start date
    setSkipWeekends(true); // Default nice-to-have
    setSkipHolidays(true); // Default nice-to-have

    // Check if leave already exists on start date to pre-fill type
    const existing = leaves.find(l => l.employeeId === selectedEmployee.id && l.date === dateStr);
    if (existing) {
        setLeaveType(existing.type);
    } else {
        setLeaveType(LeaveType.PERSONAL);
    }

    setIsLeaveModalOpen(true);
  };

  // Save Leave
  const handleSaveLeave = () => {
    if (!selectedEmployee || calculatedDatesToAdd.length === 0) return;

    setLeaves(prev => {
      // Remove existing records for this user that overlap with the new dates to be added (overwrite)
      const filtered = prev.filter(l => !(l.employeeId === selectedEmployee.id && calculatedDatesToAdd.includes(l.date)));

      const newLeaves = calculatedDatesToAdd.map(date => ({
        id: Math.random().toString(36).substr(2, 9),
        employeeId: selectedEmployee.id!,
        date: date,
        type: leaveType
      }));

      return [...filtered, ...newLeaves];
    });
    setIsLeaveModalOpen(false);
  };

  // --- User Management Logic ---

  const handleUserSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    if (!userForm.name || !userForm.position || !currentDepartment) return;

    if (editingEmployeeId) {
        // Update Existing
        setEmployees(prev => prev.map(emp => 
            emp.id === editingEmployeeId 
                ? { ...emp, name: userForm.name, position: userForm.position }
                : emp
        ));

        // Update selected employee if it was the one edited
        if (selectedEmployee?.id === editingEmployeeId) {
            setSelectedEmployee(prev => prev ? { ...prev, name: userForm.name, position: userForm.position } : null);
            setSearchQuery(userForm.name);
        }

        setEditingEmployeeId(null);
    } else {
        // Add New
        const newEmp: Employee = {
            id: Math.random().toString(36).substr(2, 9),
            name: userForm.name,
            position: userForm.position,
            department: currentDepartment
        };
        setEmployees(prev => [...prev, newEmp]);
    }

    // Reset form but keep modal open
    setUserForm({ name: '', position: '' });
  };

  const handleEditUserClick = (emp: Employee) => {
    setEditingEmployeeId(emp.id);
    setUserForm({ name: emp.name, position: emp.position });
  };

  const handleDeleteUserClick = (emp: Employee) => {
    setDeleteConfirm({ isOpen: true, id: emp.id, name: emp.name });
  };

  const executeDeleteUser = () => {
    const id = deleteConfirm.id;
    if (!id) return;

    setEmployees(prev => prev.filter(e => e.id !== id));
    setLeaves(prev => prev.filter(l => l.employeeId !== id)); // Cleanup leaves
    if (selectedEmployee?.id === id) {
        setSelectedEmployee(null);
        setSearchQuery('');
    }
    // If editing this user, cancel edit
    if (editingEmployeeId === id) {
        setEditingEmployeeId(null);
        setUserForm({ name: '', position: '' });
    }
    setDeleteConfirm({ isOpen: false, id: null, name: '' });
  };

  const handleCancelEdit = () => {
    setEditingEmployeeId(null);
    setUserForm({ name: '', position: '' });
  };

  // Trigger AI Analysis
  const handleAiAnalyze = async () => {
    if (!selectedEmployee) return;
    setIsAiModalOpen(true);
    setIsAiLoading(true);
    setAiAnalysis('');

    const result = await analyzeLeaveData(selectedEmployee.name, leaves, employees);
    setAiAnalysis(result);
    setIsAiLoading(false);
  };

  // Render Landing Page
  if (!currentDepartment) {
    return (
      <div className="min-h-screen bg-slate-50 flex flex-col items-center justify-center p-6 relative">
