/**
 * Google Apps Script สำหรับระบบจัดการวันลา
 * วิธีใช้: 
 * 1. เปิด Google Sheets
 * 2. ไปที่ Extensions -> Apps Script
 * 3. วางโค้ดนี้ลงไปแล้วกด Save
 * 4. กดปุ่ม 'setupSheets' เพื่อสร้างโครงสร้างตาราง
 */

const DEPARTMENTS = ["เวชระเบียนผู้ป่วยนอก", "เวชระเบียนผู้ป่วยใน", "ศูนย์ข้อมูล"];

/**
 * สร้างเมนูเมื่อเปิด Sheet
 */
function onOpen() {
  const ui = SpreadsheetApp.getUi();
  ui.createMenu('🚀 ระบบจัดการพนักงาน')
    .addItem('1. ตั้งค่าเริ่มต้น (สร้าง 3 แผนก)', 'setupSheets')
    .addSeparator()
    .addItem('2. ดูข้อมูลที่ส่งออก (JSON)', 'testFetch')
    .addToUi();
}

/**
 * สร้าง Sheet ตามรายชื่อแผนก
 */
function setupSheets() {
  const ss = SpreadsheetApp.getActiveSpreadsheet();

  DEPARTMENTS.forEach(deptName => {
    let sheet = ss.getSheetByName(deptName);
    if (!sheet) {
      sheet = ss.insertSheet(deptName);
      // สร้างหัวตาราง
      sheet.appendRow(["ชื่อ - นามสกุล", "ตำแหน่ง"]);

      // ตกแต่งหัวตาราง
      const headerRange = sheet.getRange("A1:B1");
      headerRange.setFontWeight("bold");
      headerRange.setBackground("#e2e8f0");
      headerRange.setFontFamily("Kanit");
      sheet.setColumnWidth(1, 250);
      sheet.setColumnWidth(2, 200);
    }
  });

  // ลบ Sheet1 ที่ว่างอยู่ออกถ้ามี
  const sheet1 = ss.getSheetByName("Sheet1");
  if (sheet1) ss.deleteSheet(sheet1);

  SpreadsheetApp.getUi().alert('✅ สร้างตาราง 3 แผนกเรียบร้อยแล้ว!');
}

/**
 * ส่วนของ API สำหรับดึงข้อมูลไปใช้ใน Web App
 * เมื่อ Deploy เป็น Web App ฟังก์ชันนี้จะทำงานเมื่อมีการเรียก GET request
 */
function doGet(e) {
  const ss = SpreadsheetApp.getActiveSpreadsheet();
  const allEmployees = [];

  DEPARTMENTS.forEach(deptName => {
    const sheet = ss.getSheetByName(deptName);
    if (sheet) {
      const data = sheet.getDataRange().getValues();
      // ข้ามแถวหัวตาราง (index 0)
      for (let i = 1; i < data.length; i++) {
        const name = data[i][0];
        const position = data[i][1];
        if (name) {
          allEmployees.push({
            id: Utilities.getUuid(),
            name: name,
            position: position || "ไม่ได้ระบุ",
            department: deptName
          });
        }
      }
    }
  });

  return ContentService.createTextOutput(JSON.stringify(allEmployees))
    .setMimeType(ContentService.MimeType.JSON);
}

function testFetch() {
  const result = doGet();
  Logger.log(result.getContent());
  SpreadsheetApp.getUi().alert('ตรวจสอบข้อมูลในเมนู View -> Logs');
}

