  const [userForm, setUserForm] = useState({ name: '', position: '' });
  const [editingEmployeeId, setEditingEmployeeId] = useState<string | null>(null);
  const [isSyncing, setIsSyncing] = useState(false);

  // Modal State: Delete Confirmation
  const [deleteConfirm, setDeleteConfirm] = useState<{isOpen: boolean, id: string | null, name: string}>({
    isOpen: false, id: null, name: ''
  });

  // AI State
  const [aiAnalysis, setAiAnalysis] = useState<string>('');
  const [isAiLoading, setIsAiLoading] = useState(false);
  const [isAiModalOpen, setIsAiModalOpen] = useState(false);

  // Refs for date inputs to programmatic control
  const startDateRef = useRef<HTMLInputElement>(null);
  const endDateRef = useRef<HTMLInputElement>(null);

  // Filter employees based on department (for management list)
  const departmentEmployees = useMemo(() => {
    if (!currentDepartment) return [];
    return employees.filter(emp => emp.department === currentDepartment);
  }, [currentDepartment, employees]);

  // Filter employees based on department and search (for sidebar)
  const filteredEmployees = useMemo(() => {
    if (!currentDepartment) return [];
    return employees.filter(emp => {
      const matchDept = emp.department === currentDepartment;
      const matchSearch = emp.name.toLowerCase().includes(searchQuery.toLowerCase());
      return matchDept && matchSearch;
    });
  }, [currentDepartment, searchQuery, employees]);

  // Helper to format date for display (DD/MM/YYYY + 543)
  const formatDateDisplay = (dateStr: string) => {
    if (!dateStr) return "";
    const [y, m, d] = dateStr.split('-');
    return `${d}/${m}/${parseInt(y) + 543}`;
  };

  // Calculate leave dates dynamically for display and saving
  const calculatedDatesToAdd = useMemo(() => {
    if (!leaveStartDate || !leaveEndDate) return [];

    const start = new Date(leaveStartDate);
    const end = new Date(leaveEndDate);

    if (isNaN(start.getTime()) || isNaN(end.getTime()) || start > end) return [];

    const dates: string[] = [];
    const loopDate = new Date(start);

    while (loopDate <= end) {
        const dateStr = loopDate.toISOString().split('T')[0];
        let shouldAdd = true;
        const dayOfWeek = loopDate.getUTCDay(); 

        if (skipWeekends && (dayOfWeek === 0 || dayOfWeek === 6)) {
            shouldAdd = false;
        }

        if (shouldAdd && skipHolidays) {
            const [y, m, d] = dateStr.split('-').map(Number);
            const checkDate = new Date(y, m - 1, d); 
            if (getHolidayName(checkDate)) {
                shouldAdd = false;
            }
        }

        if (shouldAdd) {
            dates.push(dateStr);
        }
        loopDate.setDate(loopDate.getDate() + 1);
    }
    return dates;
  }, [leaveStartDate, leaveEndDate, skipWeekends, skipHolidays]);

  // Handle department selection
  const handleDepartmentSelect = (dept: Department) => {
    setCurrentDepartment(dept);
    setSearchQuery('');
    setSelectedEmployee(null);
  };

  const handleUserSelect = (emp: Employee) => {
    setSelectedEmployee(emp);
    setSearchQuery(emp.name);
  };

  const handleDateClick = (dateStr: string) => {
    if (!selectedEmployee) return;
    setLeaveStartDate(dateStr);
    setLeaveEndDate(dateStr); 
    setSkipWeekends(true);
    setSkipHolidays(true);

    const existing = leaves.find(l => l.employeeId === selectedEmployee.id && l.date === dateStr);
    if (existing) {
        setLeaveType(existing.type);
    } else {
        setLeaveType(LeaveType.PERSONAL);
    }
    setIsLeaveModalOpen(true);
  };

  const handleSaveLeave = () => {
    if (!selectedEmployee || calculatedDatesToAdd.length === 0) return;
    setLeaves(prev => {
      const filtered = prev.filter(l => !(l.employeeId === selectedEmployee.id && calculatedDatesToAdd.includes(l.date)));
      const newLeaves = calculatedDatesToAdd.map(date => ({
        id: Math.random().toString(36).substr(2, 9),
        employeeId: selectedEmployee.id!,
        date: date,
        type: leaveType
      }));
      return [...filtered, ...newLeaves];
    });
    setIsLeaveModalOpen(false);
  };

  const handleUserSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    if (!userForm.name || !userForm.position || !currentDepartment) return;

    if (editingEmployeeId) {
        setEmployees(prev => prev.map(emp => 
            emp.id === editingEmployeeId 
                ? { ...emp, name: userForm.name, position: userForm.position }
                : emp
        ));
        if (selectedEmployee?.id === editingEmployeeId) {
            setSelectedEmployee(prev => prev ? { ...prev, name: userForm.name, position: userForm.position } : null);
            setSearchQuery(userForm.name);
        }
        setEditingEmployeeId(null);
    } else {
        const newEmp: Employee = {
            id: Math.random().toString(36).substr(2, 9),
            name: userForm.name,
            position: userForm.position,
            department: currentDepartment
        };
        setEmployees(prev => [...prev, newEmp]);
    }
    setUserForm({ name: '', position: '' });
  };

  const handleSyncFromSheets = async () => {
    setIsSyncing(true);
    // ในสถานการณ์จริง จะต้อง Deploy Apps Script เป็น Web App แล้วนำ URL มาใส่ตรงนี้
    // สำหรับตัวอย่างนี้ เราจะจำลองการดึงข้อมูลหลังจากหน่วงเวลา 1.5 วินาที
    setTimeout(() => {
      // ตัวอย่างข้อมูลที่อาจจะได้จาก Sheets
      const mockSyncedData = [
        ...employees,
        { id: 's1', name: 'บุญมี มานะ', position: 'เจ้าหน้าที่บริหาร', department: currentDepartment! }
      ].filter((v, i, a) => a.findIndex(t => t.name === v.name) === i); // ลบชื่อซ้ำ

      setEmployees(mockSyncedData);
      setIsSyncing(false);
      alert('✅ ซิงค์ข้อมูลจาก Google Sheets สำเร็จ (จำลอง)');
    }, 1500);
  };

  const handleEditUserClick = (emp: Employee) => {
    setEditingEmployeeId(emp.id);
    setUserForm({ name: emp.name, position: emp.position });
  };

  const handleDeleteUserClick = (emp: Employee) => {
    setDeleteConfirm({ isOpen: true, id: emp.id, name: emp.name });
  };

  const executeDeleteUser = () => {
    const id = deleteConfirm.id;
    if (!id) return;
    setEmployees(prev => prev.filter(e => e.id !== id));
    setLeaves(prev => prev.filter(l => l.employeeId !== id));
    if (selectedEmployee?.id === id) {
        setSelectedEmployee(null);
        setSearchQuery('');
    }
    if (editingEmployeeId === id) {
        setEditingEmployeeId(null);
        setUserForm({ name: '', position: '' });
    }
    setDeleteConfirm({ isOpen: false, id: null, name: '' });
  };

  const handleCancelEdit = () => {
    setEditingEmployeeId(null);
    setUserForm({ name: '', position: '' });
  };

  const handleAiAnalyze = async () => {
    if (!selectedEmployee) return;
    setIsAiModalOpen(true);
    setIsAiLoading(true);
    setAiAnalysis('');
    const result = await analyzeLeaveData(selectedEmployee.name, leaves, employees);
    setAiAnalysis(result);
    setIsAiLoading(false);
  };

  if (!currentDepartment) {
    return (
      <div className="min-h-screen bg-slate-50 flex flex-col items-center justify-center p-6 relative">
        <div className="text-center mb-12 relative z-10">
          <h1 className="text-3xl md:text-5xl font-bold text-slate-800 mb-4 tracking-tight">
             ระบบจัด<span className="text-blue-700">วันลา</span>ออนไลน์
          </h1>
          <p className="text-slate-500 text-base md:text-lg max-w-2xl mx-auto font-light">
            กรุณาเลือกหน่วยงานต้นสังกัดเพื่อเข้าสู่ระบบ
          </p>
        </div>

        <div className="grid grid-cols-1 md:grid-cols-3 gap-6 max-w-5xl w-full relative z-10 px-4">
          {DEPARTMENTS.map((dept) => {
            const Icon = dept.icon === 'Users' ? Users : dept.icon === 'Activity' ? Activity : Database;
            return (
              <button
                key={dept.id}
                onClick={() => handleDepartmentSelect(dept.id as Department)}
                className="group relative bg-white rounded-lg p-8 shadow-sm hover:shadow-md transition-all duration-200 border border-slate-200 hover:border-blue-300 text-left"
              >
                <div className={`absolute top-0 left-0 w-1 h-full ${dept.color} transition-all duration-200 group-hover:w-2 rounded-l-lg`}></div>
                <div className="flex flex-col h-full justify-between gap-6">
                  <div className="flex items-start justify-between">
                     <div className="bg-slate-50 p-3 rounded-lg border border-slate-100 group-hover:bg-blue-50 group-hover:border-blue-100 transition-colors">
                        <Icon className={`w-6 h-6 text-slate-700 group-hover:text-blue-700`} />
                     </div>
                  </div>
                  <div>
                    <h3 className="text-xl font-bold text-slate-800 mb-1">{dept.label}</h3>
                    <div className="flex items-center text-slate-400 text-sm gap-1 group-hover:text-blue-700 transition-colors font-medium">
                      <span>เข้าสู่ระบบ</span>
                      <ChevronRight className="w-4 h-4" />
                    </div>
                  </div>
                </div>
              </button>
            );
          })}
        </div>
      </div>
    );
  }

  return (
    <div className="min-h-screen bg-slate-50 flex flex-col font-sans">
      <nav className="bg-white shadow-sm border-b border-slate-200 sticky top-0 z-40">
        <div className="max-w-[1600px] mx-auto px-4 md:px-6 py-4 flex items-center justify-between">
          <div className="flex items-center gap-4">
            <button onClick={() => setCurrentDepartment(null)} className="p-2 hover:bg-slate-100 rounded-lg text-slate-600 transition-colors border border-transparent">
              <ArrowLeft className="w-5 h-5" />
            </button>
            <div className="flex flex-col">
                <h1 className="text-xl font-bold text-slate-800 leading-none">{currentDepartment}</h1>
                <span className="text-xs text-slate-500 mt-1">HR Management System</span>
            </div>
          </div>
          <div className="flex items-center gap-4">
             <div className="hidden lg:flex items-center gap-2 bg-slate-50 px-4 py-2 rounded-lg border border-slate-200">
               {Object.entries(LEAVE_COLORS).map(([type, color]) => (
                <div key={type} className="flex items-center gap-2 mr-4 last:mr-0">
                  <div className={`w-2 h-2 rounded-sm ${color}`}></div>
                  <span className="text-xs text-slate-600 font-medium">{type}</span>
                </div>
              ))}
             </div>
             <div className="h-9 w-9 rounded-full bg-slate-800 flex items-center justify-center text-white shadow-sm">
                <Users className="w-4 h-4" />
             </div>
          </div>
        </div>
      </nav>

      <main className="flex-1 max-w-[1600px] w-full mx-auto p-4 md:p-6 grid grid-cols-1 lg:grid-cols-12 gap-6 items-start">
        <aside className="lg:col-span-3 space-y-6 lg:sticky lg:top-24">
          <div className="bg-white rounded-lg shadow-sm border border-slate-200 overflow-hidden">
             <div className="px-5 py-4 border-b border-slate-100 bg-slate-50/50 flex justify-between items-center">
                <h2 className="text-slate-800 font-bold text-sm uppercase tracking-wide flex items-center gap-2">
                   <Search className="w-4 h-4 text-slate-500" />
                   รายชื่อพนักงาน
                </h2>
                <button onClick={() => setIsManageUserModalOpen(true)} className="text-xs flex items-center gap-1 bg-white border border-slate-200 px-2 py-1 rounded text-blue-700 hover:border-blue-300 hover:bg-blue-50 transition-all font-medium">
                    <UserPlus className="w-3 h-3" />
                    จัดการรายชื่อ
                </button>
             </div>
             <div className="p-5">
                <div className="relative mb-4">
                  <Search className="absolute left-3 top-1/2 -translate-y-1/2 text-slate-400 w-4 h-4" />
                  <input
                    type="text"
                    className="w-full pl-10 pr-4 py-2.5 bg-white border border-slate-200 rounded-lg focus:ring-1 focus:ring-blue-500 focus:border-blue-500 outline-none transition-all text-sm text-slate-900 placeholder-slate-400 font-medium"
                    placeholder="ค้นหาชื่อ หรืออักษรย่อ..."
                    value={searchQuery}
                    onChange={(e) => {
                        setSearchQuery(e.target.value);
                        if (selectedEmployee && e.target.value !== selectedEmployee.name) {
                            setSelectedEmployee(null);
                        }
                    }}
                  />
                  {searchQuery && !selectedEmployee && filteredEmployees.length > 0 && (
                    <div className="absolute top-full left-0 right-0 mt-1 bg-white rounded-lg shadow-lg border border-slate-200 max-h-60 overflow-y-auto z-50">
                      {filteredEmployees.map(emp => (
                        <button key={emp.id} onClick={() => handleUserSelect(emp)} className="w-full text-left px-4 py-2.5 hover:bg-slate-50 flex items-center gap-3 transition-colors border-b border-slate-50 last:border-0">
                          <div className="w-7 h-7 rounded bg-slate-100 text-slate-600 flex items-center justify-center font-bold text-xs shrink-0 border border-slate-200">
                            {emp.name.charAt(0)}
                          </div>
                          <div>
                              <p className="text-slate-800 text-sm font-medium">{emp.name}</p>
                              <p className="text-xs text-slate-500">{emp.position}</p>
                          </div>
                        </button>
                      ))}
                    </div>
                  )}
                </div>
                {selectedEmployee ? (
                  <div className="bg-slate-50 border border-slate-200 rounded-lg p-4 animate-fade-in">
                      <div className="flex items-start justify-between mb-4">
                         <div className="flex items-start gap-3">
                            <div className="w-10 h-10 rounded-lg bg-white border border-slate-200 text-slate-700 flex items-center justify-center font-bold text-lg shadow-sm">
                                {selectedEmployee.name.charAt(0)}
                            </div>
                            <div>
                                <h3 className="font-bold text-slate-800 text-sm">{selectedEmployee.name}</h3>
                                <p className="text-xs text-slate-500 flex items-center gap-1 mt-0.5"><Briefcase className="w-3 h-3" />{selectedEmployee.position}</p>
                            </div>
                         </div>
                         <CheckCircle2 className="text-blue-600 w-5 h-5" />
                      </div>
                      <button onClick={handleAiAnalyze} className="w-full flex items-center justify-center gap-2 bg-white border border-indigo-200 text-indigo-700 py-2 rounded-md hover:bg-indigo-50 transition-all text-xs font-semibold shadow-sm">
                          <Bot className="w-3.5 h-3.5" />วิเคราะห์ข้อมูล (AI Insight)
                      </button>
                  </div>
                ) : (
                  <div className="text-center py-8 px-4 border border-dashed border-slate-300 rounded-lg">
                     <Users className="w-6 h-6 text-slate-300 mx-auto mb-2" />
                     <p className="text-xs text-slate-400">เลือกรายชื่อเพื่อดูข้อมูล หรือบันทึกวันลา</p>
                  </div>
                )}
             </div>
          </div>

          <div className="bg-white rounded-lg shadow-sm border border-slate-200 overflow-hidden">
             <div className="px-5 py-4 border-b border-slate-100 bg-slate-50/50 flex items-center justify-between">
                <h2 className="text-slate-800 font-bold text-sm uppercase tracking-wide flex items-center gap-2">
                   <LayoutDashboard className="w-4 h-4 text-slate-500" />สถิติประจำปี
                </h2>
                <span className="text-xs font-bold bg-white border border-slate-200 text-slate-600 px-2 py-0.5 rounded">{new Date().getFullYear() + 543}</span>
             </div>
             <div className="p-4">
                <StatsChart leaves={selectedEmployee ? leaves.filter(l => l.employeeId === selectedEmployee.id) : leaves.filter(l => departmentEmployees.some(e => e.id === l.employeeId))} currentYear={new Date().getFullYear()} />
             </div>
          </div>
        </aside>

        <section className="lg:col-span-9 h-full">
            <div className="bg-white rounded-lg shadow-sm border border-slate-200 overflow-hidden min-h-[650px]">
                <CalendarView leaves={leaves} employees={departmentEmployees} selectedEmployeeId={selectedEmployee?.id || null} onDateClick={handleDateClick} />
            </div>
        </section>
      </main>

      {/* Leave Modal */}
      {isLeaveModalOpen && (
        <div className="fixed inset-0 bg-slate-900/40 backdrop-blur-sm z-50 flex items-center justify-center p-4">
          <div className="bg-white rounded-lg shadow-2xl w-full max-w-md p-0 overflow-hidden animate-in fade-in zoom-in-95 duration-200">
            <div className="bg-slate-50 px-6 py-4 border-b border-slate-100 flex justify-between items-center">
                <h3 className="font-bold text-slate-800 flex items-center gap-2"><CalendarRange className="w-5 h-5 text-blue-600" />บันทึกการลา</h3>
                <button onClick={() => setIsLeaveModalOpen(false)} className="text-slate-400 hover:text-slate-600"><X className="w-5 h-5" /></button>
            </div>
            <div className="p-6">
                <div className="grid grid-cols-2 gap-4 mb-4">
                    <div>
                        <label className="block text-xs font-semibold text-slate-600 mb-1.5">จากวันที่</label>
                        <div className="relative group cursor-pointer">
                            <div className="w-full flex items-center bg-white border border-slate-300 rounded-md overflow-hidden transition-colors group-hover:border-blue-400 h-[38px]">
                                <div className="flex-1 px-3 text-sm text-slate-800 truncate">{leaveStartDate ? formatDateDisplay(leaveStartDate) : <span className="text-slate-400">วว/ดด/ปปปป</span>}</div>
                                <div className="bg-slate-50 border-l border-slate-200 h-full px-3 flex items-center justify-center group-hover:bg-blue-50 transition-colors"><CalendarIcon className="w-4 h-4 text-slate-500 group-hover:text-blue-600" /></div>
                            </div>
                            <input ref={startDateRef} type="date" value={leaveStartDate} onChange={(e) => { setLeaveStartDate(e.target.value); if (e.target.value > leaveEndDate) setLeaveEndDate(e.target.value); }} className="absolute inset-0 w-full h-full opacity-0 cursor-pointer z-10" />
                        </div>
                    </div>
                    <div>
                        <label className="block text-xs font-semibold text-slate-600 mb-1.5">ถึงวันที่</label>
                        <div className="relative group cursor-pointer">
                            <div className="w-full flex items-center bg-white border border-slate-300 rounded-md overflow-hidden transition-colors group-hover:border-blue-400 h-[38px]">
                                <div className="flex-1 px-3 text-sm text-slate-800 truncate">{leaveEndDate ? formatDateDisplay(leaveEndDate) : <span className="text-slate-400">วว/ดด/ปปปป</span>}</div>
                                <div className="bg-slate-50 border-l border-slate-200 h-full px-3 flex items-center justify-center group-hover:bg-blue-50 transition-colors"><CalendarIcon className="w-4 h-4 text-slate-500 group-hover:text-blue-600" /></div>
                            </div>
                            <input ref={endDateRef} type="date" value={leaveEndDate} min={leaveStartDate} onChange={(e) => setLeaveEndDate(e.target.value)} className="absolute inset-0 w-full h-full opacity-0 cursor-pointer z-10" />
                        </div>
                    </div>
                </div>
                <div className="mb-4 flex items-center justify-between p-3 bg-indigo-50 border border-indigo-100 rounded-md text-indigo-900">
                    <div className="flex items-center gap-2 text-sm font-semibold"><Clock className="w-4 h-4 text-indigo-600" /><span>รวมจำนวนวันลา</span></div>
                    <span className="text-lg font-bold text-indigo-700">{calculatedDatesToAdd.length} วัน</span>
                </div>
                <div className="flex flex-col gap-2 mb-4 bg-slate-50 p-3 rounded-md border border-slate-200">
                    <label className="flex items-center gap-2 text-sm text-slate-700 cursor-pointer select-none">
                        <input type="checkbox" checked={skipWeekends} onChange={e => setSkipWeekends(e.target.checked)} className="w-4 h-4 rounded text-blue-600 focus:ring-blue-500 border-gray-300" />
                        <span>ข้ามวันเสาร์ - อาทิตย์</span>
                    </label>
                    <label className="flex items-center gap-2 text-sm text-slate-700 cursor-pointer select-none">
                        <input type="checkbox" checked={skipHolidays} onChange={e => setSkipHolidays(e.target.checked)} className="w-4 h-4 rounded text-blue-600 focus:ring-blue-500 border-gray-300" />
                        <span>ข้ามวันหยุดนักขัตฤกษ์</span>
                    </label>
                </div>
                <div className="space-y-2 mb-6 max-h-[200px] overflow-y-auto custom-scrollbar pr-1">
                {Object.values(LeaveType).map((type) => (
                    <button key={type} onClick={() => setLeaveType(type)} className={`w-full px-4 py-3 rounded-md border text-sm flex items-center justify-between transition-all ${leaveType === type ? `border-blue-600 bg-blue-50 text-blue-700 font-semibold shadow-sm` : 'border-slate-200 hover:border-slate-300 hover:bg-slate-50 text-slate-600'}`}>
                    <span>{type}</span>{leaveType === type && <CheckCircle2 className="w-4 h-4" />}
                    </button>
                ))}
                </div>
                <div className="flex gap-3 pt-2 border-t border-slate-100">
                    <button onClick={() => setIsLeaveModalOpen(false)} className="flex-1 py-2.5 rounded-md border border-slate-300 text-slate-700 hover:bg-slate-50 font-medium text-sm">ยกเลิก</button>
                    <button onClick={handleSaveLeave} className="flex-1 py-2.5 rounded-md bg-blue-700 text-white hover:bg-blue-800 font-medium text-sm shadow-sm">บันทึกข้อมูล</button>
                </div>
            </div>
          </div>
        </div>
      )}

      {/* User Management Modal */}
      {isManageUserModalOpen && (
        <div className="fixed inset-0 bg-slate-900/40 backdrop-blur-sm z-50 flex items-center justify-center p-4">
          <div className="bg-white rounded-xl shadow-2xl w-full max-w-2xl p-0 overflow-hidden animate-in fade-in zoom-in-95 duration-200 flex flex-col max-h-[85vh]">
            <div className="bg-slate-50 px-6 py-4 border-b border-slate-100 flex justify-between items-center">
                <div>
                    <h3 className="font-bold text-slate-800 flex items-center gap-2 text-lg"><Users className="w-5 h-5 text-blue-700" />จัดการรายชื่อพนักงาน</h3>
                    <p className="text-xs text-slate-500 mt-1">แผนก: {currentDepartment}</p>
                </div>
                <div className="flex items-center gap-3">
                    <button 
                        onClick={handleSyncFromSheets} 
                        disabled={isSyncing}
                        className="text-xs flex items-center gap-2 bg-blue-50 text-blue-700 border border-blue-200 px-3 py-1.5 rounded-md hover:bg-blue-100 transition-all font-semibold disabled:opacity-50"
                    >
                        {isSyncing ? <RefreshCw className="w-3.5 h-3.5 animate-spin" /> : <FileSpreadsheet className="w-3.5 h-3.5" />}
                        {isSyncing ? 'กำลังซิงค์...' : 'ดึงข้อมูลจาก Sheets'}
                    </button>
                    <button onClick={() => { setIsManageUserModalOpen(false); handleCancelEdit(); }} className="text-slate-400 hover:text-slate-600"><X className="w-6 h-6" /></button>
                </div>
            </div>

            <div className="flex-1 overflow-hidden flex flex-col">
                <div className="p-6 bg-white border-b border-slate-100">
                    <h4 className="text-xs font-bold text-slate-500 uppercase tracking-wide mb-4">{editingEmployeeId ? 'แก้ไขข้อมูล' : 'เพิ่มพนักงานใหม่'}</h4>
                    <form onSubmit={handleUserSubmit} className="grid grid-cols-1 md:grid-cols-12 gap-4 items-end">
                        <div className="md:col-span-5">
                            <label className="block text-xs font-medium text-slate-700 mb-1.5">ชื่อ - นามสกุล</label>
                            <input type="text" required placeholder="เช่น สมชาย ใจดี" value={userForm.name} onChange={e => setUserForm({...userForm, name: e.target.value})} className="w-full px-3 py-2 bg-white border border-slate-300 rounded-md focus:ring-1 focus:ring-blue-500 focus:border-blue-500 outline-none text-sm text-slate-900 placeholder-slate-400" />
                        </div>
                        <div className="md:col-span-5">
                            <label className="block text-xs font-medium text-slate-700 mb-1.5">ตำแหน่ง</label>
                            <input type="text" required placeholder="เช่น พยาบาลวิชาชีพ" value={userForm.position} onChange={e => setUserForm({...userForm, position: e.target.value})} className="w-full px-3 py-2 bg-white border border-slate-300 rounded-md focus:ring-1 focus:ring-blue-500 focus:border-blue-500 outline-none text-sm text-slate-900 placeholder-slate-400" />
                        </div>
                        <div className="md:col-span-2 flex gap-2">
                             {editingEmployeeId ? (
                                <>
                                    <button type="submit" className="w-full py-2 bg-amber-500 hover:bg-amber-600 text-white rounded-md flex items-center justify-center transition-colors" title="บันทึกการแก้ไข"><Save className="w-4 h-4" /></button>
                                    <button type="button" onClick={handleCancelEdit} className="w-full py-2 bg-slate-200 hover:bg-slate-300 text-slate-600 rounded-md flex items-center justify-center transition-colors" title="ยกเลิก"><X className="w-4 h-4" /></button>
                                </>
                             ) : (
                                <button type="submit" className="w-full py-2 bg-blue-700 hover:bg-blue-800 text-white rounded-md flex items-center justify-center gap-1 font-medium text-sm shadow-sm transition-colors"><UserPlus className="w-4 h-4" /><span className="hidden md:inline">เพิ่ม</span></button>
                             )}
                        </div>
                    </form>
                </div>

                <div className="flex-1 overflow-y-auto bg-slate-50/50 p-6">
                     <h4 className="text-xs font-bold text-slate-500 uppercase tracking-wide mb-3 flex justify-between items-center">รายชื่อในระบบ ({departmentEmployees.length})</h4>
                     <div className="bg-white border border-slate-200 rounded-lg shadow-sm overflow-hidden">
                        {departmentEmployees.length > 0 ? (
                            <table className="w-full text-sm text-left">
                                <thead className="bg-slate-50 text-slate-500 font-medium border-b border-slate-200">
                                    <tr><th className="px-4 py-3 w-12 text-center">#</th><th className="px-4 py-3">ชื่อ - นามสกุล</th><th className="px-4 py-3">ตำแหน่ง</th><th className="px-4 py-3 text-right">จัดการ</th></tr>
                                </thead>
                                <tbody className="divide-y divide-slate-100">
                                    {departmentEmployees.map((emp, index) => (
                                        <tr key={emp.id} className={`hover:bg-blue-50/30 transition-colors ${editingEmployeeId === emp.id ? 'bg-amber-50' : ''}`}>
                                            <td className="px-4 py-3 text-center text-slate-400 text-xs">{index + 1}</td>
                                            <td className="px-4 py-3 font-medium text-slate-800">{emp.name}</td>
                                            <td className="px-4 py-3 text-slate-600">{emp.position}</td>
                                            <td className="px-4 py-3 text-right">
                                                <div className="flex items-center justify-end gap-2">
                                                    <button onClick={() => handleEditUserClick(emp)} className="p-1.5 text-slate-400 hover:text-amber-600 hover:bg-amber-50 rounded transition-colors" title="แก้ไข"><Pencil className="w-4 h-4" /></button>
                                                    <button onClick={() => handleDeleteUserClick(emp)} className="p-1.5 text-slate-400 hover:text-red-600 hover:bg-red-50 rounded transition-colors" title="ลบ"><Trash2 className="w-4 h-4" /></button>
                                                </div>
                                            </td>
                                        </tr>
                                    ))}
                                </tbody>
                            </table>
                        ) : (
                            <div className="p-8 text-center text-slate-400"><Users className="w-8 h-8 mx-auto mb-2 opacity-50" /><p>ยังไม่มีรายชื่อพนักงานในแผนกนี้</p></div>
                        )}
                     </div>
                </div>
            </div>
          </div>
        </div>
      )}

      {/* Delete Confirmation */}
      {deleteConfirm.isOpen && (
        <div className="fixed inset-0 bg-slate-900/40 backdrop-blur-sm z-[60] flex items-center justify-center p-4">
          <div className="bg-white rounded-lg shadow-2xl w-full max-w-sm p-6 animate-in fade-in zoom-in-95 duration-200">
            <div className="flex flex-col items-center text-center">
                <div className="w-12 h-12 rounded-full bg-red-100 text-red-600 flex items-center justify-center mb-4"><AlertTriangle className="w-6 h-6" /></div>
                <h3 className="text-lg font-bold text-slate-800 mb-2">ยืนยันการลบรายชื่อ</h3>
                <p className="text-slate-500 text-sm mb-6">คุณต้องการลบรายชื่อ <span className="font-bold text-slate-800">"{deleteConfirm.name}"</span> จริงไหม?<br/>ข้อมูลประวัติการลาทั้งหมดจะถูกลบด้วย</p>
                <div className="flex gap-3 w-full">
                    <button onClick={() => setDeleteConfirm({ isOpen: false, id: null, name: '' })} className="flex-1 py-2.5 rounded-md border border-slate-300 text-slate-700 hover:bg-slate-50 font-medium text-sm transition-colors">ยกเลิก</button>
                    <button onClick={executeDeleteUser} className="flex-1 py-2.5 rounded-md bg-red-600 text-white hover:bg-red-700 font-medium text-sm shadow-sm transition-colors">ยืนยันลบ</button>
                </div>
            </div>
          </div>
        </div>
      )}

      {/* AI Insight Modal */}
      {isAiModalOpen && (
        <div className="fixed inset-0 bg-slate-900/50 backdrop-blur-sm z-50 flex items-center justify-center p-4">
          <div className="bg-white rounded-lg shadow-2xl w-full max-w-lg p-0 overflow-hidden flex flex-col max-h-[85vh] animate-in fade-in zoom-in-95 duration-200">
            <div className="bg-indigo-700 p-6 text-white flex justify-between items-start">
                <div>
                    <div className="flex items-center gap-2 mb-2"><Bot className="w-5 h-5" /><h3 className="text-lg font-bold">AI Analytics</h3></div>
                    <p className="text-indigo-100 text-xs">รายงานสรุปผลสุขภาพการทำงานและวันลาของ: <span className="font-semibold text-white">{selectedEmployee?.name}</span></p>
                </div>
                <button onClick={() => setIsAiModalOpen(false)} className="text-indigo-200 hover:text-white"><X className="w-5 h-5" /></button>
            </div>
            <div className="p-6 overflow-y-auto bg-white min-h-[300px]">
                {isAiLoading ? (
                    <div className="flex flex-col items-center justify-center py-12 text-slate-400"><Activity className="w-8 h-8 animate-spin mb-3 text-indigo-500" /><p className="font-medium text-sm">กำลังวิเคราะห์ข้อมูล...</p></div>
                ) : (
                    <div className="prose prose-slate prose-sm max-w-none"><div className="whitespace-pre-line text-slate-700 leading-relaxed text-sm">{aiAnalysis}</div></div>
                )}
            </div>
            <div className="p-4 border-t border-slate-100 bg-slate-50 flex justify-end">
                 <button onClick={() => setIsAiModalOpen(false)} className="px-4 py-2 rounded border border-slate-300 bg-white text-slate-700 hover:bg-slate-50 font-medium transition-colors text-xs">ปิดหน้าต่าง</button>
            </div>
          </div>
        </div>
      )}
    </div>
  );
}

export default App;

import React, { useState, useMemo, useRef } from 'react';
import { 
  Users, Activity, Database, Search, Calendar as CalendarIcon, 
  ArrowLeft, CheckCircle2, Bot, LayoutDashboard, ChevronRight, UserPlus, X, Briefcase,
  Pencil, Trash2, Save, AlertTriangle, CalendarRange, Clock, RefreshCw, FileSpreadsheet
} from 'lucide-react';
import { Department, Employee, LeaveRecord, LeaveType, LEAVE_COLORS } from './types';
import { INITIAL_EMPLOYEES, INITIAL_LEAVES, DEPARTMENTS, getHolidayName } from './constants';
import CalendarView from './components/CalendarView';
import StatsChart from './components/StatsChart';
import { analyzeLeaveData } from './services/geminiService';

function App() {
  const [currentDepartment, setCurrentDepartment] = useState<Department | null>(null);
  const [employees, setEmployees] = useState<Employee[]>(INITIAL_EMPLOYEES);
  const [searchQuery, setSearchQuery] = useState('');
  const [selectedEmployee, setSelectedEmployee] = useState<Employee | null>(null);
  const [leaves, setLeaves] = useState<LeaveRecord[]>(INITIAL_LEAVES);

  // Modal State: Leave
  const [isLeaveModalOpen, setIsLeaveModalOpen] = useState(false);
  const [leaveStartDate, setLeaveStartDate] = useState<string>('');
  const [leaveEndDate, setLeaveEndDate] = useState<string>('');
  const [leaveType, setLeaveType] = useState<LeaveType>(LeaveType.PERSONAL);
  const [skipWeekends, setSkipWeekends] = useState(false);
  const [skipHolidays, setSkipHolidays] = useState(false);

  // Modal State: User Management (Add/Edit/List)
  const [isManageUserModalOpen, setIsManageUserModalOpen] = useState(false);
  const [userForm, setUserForm] = useState({ name: '', position: '' });
  const [editingEmployeeId, setEditingEmployeeId] = useState<string | null>(null);
  const [isSyncing, setIsSyncing] = useState(false);

  // Modal State: Delete Confirmation
  const [deleteConfirm, setDeleteConfirm] = useState<{isOpen: boolean, id: string | null, name: string}>({
    isOpen: false, id: null, name: ''
  });

  // AI State
  const [aiAnalysis, setAiAnalysis] = useState<string>('');
  const [isAiLoading, setIsAiLoading] = useState(false);
  const [isAiModalOpen, setIsAiModalOpen] = useState(false);

  // Refs for date inputs to programmatic control
  const startDateRef = useRef<HTMLInputElement>(null);
  const endDateRef = useRef<HTMLInputElement>(null);

  // Filter employees based on department (for management list)
  const departmentEmployees = useMemo(() => {
    if (!currentDepartment) return [];
    return employees.filter(emp => emp.department === currentDepartment);
  }, [currentDepartment, employees]);

  // Filter employees based on department and search (for sidebar)
  const filteredEmployees = useMemo(() => {
    if (!currentDepartment) return [];
    return employees.filter(emp => {
      const matchDept = emp.department === currentDepartment;
      const matchSearch = emp.name.toLowerCase().includes(searchQuery.toLowerCase());
      return matchDept && matchSearch;
    });
  }, [currentDepartment, searchQuery, employees]);

  // Helper to format date for display (DD/MM/YYYY + 543)
  const formatDateDisplay = (dateStr: string) => {
    if (!dateStr) return "";
    const [y, m, d] = dateStr.split('-');
    return `${d}/${m}/${parseInt(y) + 543}`;
  };

  // Calculate leave dates dynamically for display and saving
  const calculatedDatesToAdd = useMemo(() => {
    if (!leaveStartDate || !leaveEndDate) return [];

    const start = new Date(leaveStartDate);
    const end = new Date(leaveEndDate);

    if (isNaN(start.getTime()) || isNaN(end.getTime()) || start > end) return [];

    const dates: string[] = [];
    const loopDate = new Date(start);

    while (loopDate <= end) {
        const dateStr = loopDate.toISOString().split('T')[0];
        let shouldAdd = true;
        const dayOfWeek = loopDate.getUTCDay(); 

        if (skipWeekends && (dayOfWeek === 0 || dayOfWeek === 6)) {
            shouldAdd = false;
        }

        if (shouldAdd && skipHolidays) {
            const [y, m, d] = dateStr.split('-').map(Number);
            const checkDate = new Date(y, m - 1, d); 
            if (getHolidayName(checkDate)) {
                shouldAdd = false;
            }
        }

        if (shouldAdd) {
            dates.push(dateStr);
        }
        loopDate.setDate(loopDate.getDate() + 1);
    }
    return dates;
  }, [leaveStartDate, leaveEndDate, skipWeekends, skipHolidays]);

  // Handle department selection
  const handleDepartmentSelect = (dept: Department) => {
    setCurrentDepartment(dept);
    setSearchQuery('');
    setSelectedEmployee(null);
  };

  const handleUserSelect = (emp: Employee) => {
    setSelectedEmployee(emp);
    setSearchQuery(emp.name);
  };

  const handleDateClick = (dateStr: string) => {
    if (!selectedEmployee) return;
    setLeaveStartDate(dateStr);
    setLeaveEndDate(dateStr); 
    setSkipWeekends(true);
    setSkipHolidays(true);

    const existing = leaves.find(l => l.employeeId === selectedEmployee.id && l.date === dateStr);
    if (existing) {
        setLeaveType(existing.type);
    } else {
        setLeaveType(LeaveType.PERSONAL);
    }
    setIsLeaveModalOpen(true);
  };

  const handleSaveLeave = () => {
    if (!selectedEmployee || calculatedDatesToAdd.length === 0) return;
    setLeaves(prev => {
      const filtered = prev.filter(l => !(l.employeeId === selectedEmployee.id && calculatedDatesToAdd.includes(l.date)));
      const newLeaves = calculatedDatesToAdd.map(date => ({
        id: Math.random().toString(36).substr(2, 9),
        employeeId: selectedEmployee.id!,
        date: date,
        type: leaveType
      }));
      return [...filtered, ...newLeaves];
    });
    setIsLeaveModalOpen(false);
  };

  const handleUserSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    if (!userForm.name || !userForm.position || !currentDepartment) return;

    if (editingEmployeeId) {
        setEmployees(prev => prev.map(emp => 
            emp.id === editingEmployeeId 
                ? { ...emp, name: userForm.name, position: userForm.position }
                : emp
        ));
        if (selectedEmployee?.id === editingEmployeeId) {
            setSelectedEmployee(prev => prev ? { ...prev, name: userForm.name, position: userForm.position } : null);
            setSearchQuery(userForm.name);
        }
        setEditingEmployeeId(null);
    } else {
        const newEmp: Employee = {
            id: Math.random().toString(36).substr(2, 9),
            name: userForm.name,
            position: userForm.position,
            department: currentDepartment
        };
        setEmployees(prev => [...prev, newEmp]);
    }
    setUserForm({ name: '', position: '' });
  };

  /**
   * ฟังก์ชันสำหรับซิงค์ข้อมูลจาก Google Sheets (Apps Script)
   */
  const handleSyncFromSheets = async () => {
    setIsSyncing(true);
    const SCRIPT_URL = 'https://script.google.com/macros/s/AKfycbyL7IgTF8R6rddviSxdFICcYT3Bq5sfyelHso1mIZAgRBcIVt_WgegUUy0SfNXe_08aTg/exec';

    try {
      // เรียกใช้ API จาก Google Apps Script
      const response = await fetch(SCRIPT_URL);
      if (!response.ok) throw new Error('ไม่สามารถเชื่อมต่อกับ Google Sheets ได้');

      const syncedEmployees: Employee[] = await response.json();

      // นำข้อมูลที่ซิงค์มารวมกับข้อมูลเดิม โดยใช้ชื่อเป็นตัวตัดสินความซ้ำซ้อน
      setEmployees(prev => {
        const combined = [...prev, ...syncedEmployees];
        // กรองเอาเฉพาะข้อมูลที่ไม่ซ้ำชื่อกัน
        return combined.filter((v, i, a) => a.findIndex(t => t.name === v.name) === i);
      });

      alert('✅ ซิงค์ข้อมูลจาก Google Sheets สำเร็จ!');
    } catch (error) {
      console.error('Sync error:', error);
      alert('❌ เกิดข้อผิดพลาด: ' + (error instanceof Error ? error.message : 'ไม่ทราบสาเหตุ'));
    } finally {
      setIsSyncing(false);
    }
  };

  const handleEditUserClick = (emp: Employee) => {
    setEditingEmployeeId(emp.id);
    setUserForm({ name: emp.name, position: emp.position });
  };

  const handleDeleteUserClick = (emp: Employee) => {
    setDeleteConfirm({ isOpen: true, id: emp.id, name: emp.name });
  };

  const executeDeleteUser = () => {
    const id = deleteConfirm.id;
    if (!id) return;
    setEmployees(prev => prev.filter(e => e.id !== id));
    setLeaves(prev => prev.filter(l => l.employeeId !== id));
    if (selectedEmployee?.id === id) {
        setSelectedEmployee(null);
        setSearchQuery('');
    }
    if (editingEmployeeId === id) {
        setEditingEmployeeId(null);
        setUserForm({ name: '', position: '' });
    }
    setDeleteConfirm({ isOpen: false, id: null, name: '' });
  };

  const handleCancelEdit = () => {
    setEditingEmployeeId(null);
    setUserForm({ name: '', position: '' });
  };

  const handleAiAnalyze = async () => {
    if (!selectedEmployee) return;
    setIsAiModalOpen(true);
    setIsAiLoading(true);
    setAiAnalysis('');
    const result = await analyzeLeaveData(selectedEmployee.name, leaves, employees);
    setAiAnalysis(result);
    setIsAiLoading(false);
  };

  if (!currentDepartment) {
    return (
      <div className="min-h-screen bg-slate-50 flex flex-col items-center justify-center p-6 relative">
        <div className="text-center mb-12 relative z-10">
          <h1 className="text-3xl md:text-5xl font-bold text-slate-800 mb-4 tracking-tight">
             ระบบจัด<span className="text-blue-700">วันลา</span>ออนไลน์
          </h1>
          <p className="text-slate-500 text-base md:text-lg max-w-2xl mx-auto font-light">
            กรุณาเลือกหน่วยงานต้นสังกัดเพื่อเข้าสู่ระบบ
          </p>
        </div>

        <div className="grid grid-cols-1 md:grid-cols-3 gap-6 max-w-5xl w-full relative z-10 px-4">
          {DEPARTMENTS.map((dept) => {
            const Icon = dept.icon === 'Users' ? Users : dept.icon === 'Activity' ? Activity : Database;
            return (
              <button
                key={dept.id}
                onClick={() => handleDepartmentSelect(dept.id as Department)}
                className="group relative bg-white rounded-lg p-8 shadow-sm hover:shadow-md transition-all duration-200 border border-slate-200 hover:border-blue-300 text-left"
              >
                <div className={`absolute top-0 left-0 w-1 h-full ${dept.color} transition-all duration-200 group-hover:w-2 rounded-l-lg`}></div>
                <div className="flex flex-col h-full justify-between gap-6">
                  <div className="flex items-start justify-between">
                     <div className="bg-slate-50 p-3 rounded-lg border border-slate-100 group-hover:bg-blue-50 group-hover:border-blue-100 transition-colors">
                        <Icon className={`w-6 h-6 text-slate-700 group-hover:text-blue-700`} />
                     </div>
                  </div>
                  <div>
                    <h3 className="text-xl font-bold text-slate-800 mb-1">{dept.label}</h3>
                    <div className="flex items-center text-slate-400 text-sm gap-1 group-hover:text-blue-700 transition-colors font-medium">
                      <span>เข้าสู่ระบบ</span>
                      <ChevronRight className="w-4 h-4" />
                    </div>
                  </div>
                </div>
              </button>
            );
          })}
        </div>
      </div>
    );
  }

  return (
    <div className="min-h-screen bg-slate-50 flex flex-col font-sans">
      <nav className="bg-white shadow-sm border-b border-slate-200 sticky top-0 z-40">
        <div className="max-w-[1600px] mx-auto px-4 md:px-6 py-4 flex items-center justify-between">
          <div className="flex items-center gap-4">
            <button onClick={() => setCurrentDepartment(null)} className="p-2 hover:bg-slate-100 rounded-lg text-slate-600 transition-colors border border-transparent">
              <ArrowLeft className="w-5 h-5" />
            </button>
            <div className="flex flex-col">
                <h1 className="text-xl font-bold text-slate-800 leading-none">{currentDepartment}</h1>
                <span className="text-xs text-slate-500 mt-1">HR Management System</span>
            </div>
          </div>
          <div className="flex items-center gap-4">
             <div className="hidden lg:flex items-center gap-2 bg-slate-50 px-4 py-2 rounded-lg border border-slate-200">
               {Object.entries(LEAVE_COLORS).map(([type, color]) => (
                <div key={type} className="flex items-center gap-2 mr-4 last:mr-0">
                  <div className={`w-2 h-2 rounded-sm ${color}`}></div>
                  <span className="text-xs text-slate-600 font-medium">{type}</span>
                </div>
              ))}
             </div>
             <div className="h-9 w-9 rounded-full bg-slate-800 flex items-center justify-center text-white shadow-sm">
                <Users className="w-4 h-4" />
             </div>
          </div>
        </div>
      </nav>

      <main className="flex-1 max-w-[1600px] w-full mx-auto p-4 md:p-6 grid grid-cols-1 lg:grid-cols-12 gap-6 items-start">
        <aside className="lg:col-span-3 space-y-6 lg:sticky lg:top-24">
          <div className="bg-white rounded-lg shadow-sm border border-slate-200 overflow-hidden">
             <div className="px-5 py-4 border-b border-slate-100 bg-slate-50/50 flex justify-between items-center">
                <h2 className="text-slate-800 font-bold text-sm uppercase tracking-wide flex items-center gap-2">
                   <Search className="w-4 h-4 text-slate-500" />
                   รายชื่อพนักงาน
                </h2>
                <button onClick={() => setIsManageUserModalOpen(true)} className="text-xs flex items-center gap-1 bg-white border border-slate-200 px-2 py-1 rounded text-blue-700 hover:border-blue-300 hover:bg-blue-50 transition-all font-medium">
                    <UserPlus className="w-3 h-3" />
                    จัดการรายชื่อ
                </button>
             </div>
             <div className="p-5">
                <div className="relative mb-4">
                  <Search className="absolute left-3 top-1/2 -translate-y-1/2 text-slate-400 w-4 h-4" />
                  <input
                    type="text"
                    className="w-full pl-10 pr-4 py-2.5 bg-white border border-slate-200 rounded-lg focus:ring-1 focus:ring-blue-500 focus:border-blue-500 outline-none transition-all text-sm text-slate-900 placeholder-slate-400 font-medium"
                    placeholder="ค้นหาชื่อ หรืออักษรย่อ..."
                    value={searchQuery}
                    onChange={(e) => {
                        setSearchQuery(e.target.value);
                        if (selectedEmployee && e.target.value !== selectedEmployee.name) {
                            setSelectedEmployee(null);
                        }
                    }}
                  />
                  {searchQuery && !selectedEmployee && filteredEmployees.length > 0 && (
                    <div className="absolute top-full left-0 right-0 mt-1 bg-white rounded-lg shadow-lg border border-slate-200 max-h-60 overflow-y-auto z-50">
                      {filteredEmployees.map(emp => (
                        <button key={emp.id} onClick={() => handleUserSelect(emp)} className="w-full text-left px-4 py-2.5 hover:bg-slate-50 flex items-center gap-3 transition-colors border-b border-slate-50 last:border-0">
                          <div className="w-7 h-7 rounded bg-slate-100 text-slate-600 flex items-center justify-center font-bold text-xs shrink-0 border border-slate-200">
                            {emp.name.charAt(0)}
                          </div>
                          <div>
                              <p className="text-slate-800 text-sm font-medium">{emp.name}</p>
