          <div className="bg-white rounded-lg shadow-2xl w-full max-w-lg p-0 overflow-hidden flex flex-col max-h-[85vh]">
            <div className="bg-indigo-700 p-6 text-white flex justify-between items-start">
                <div><h3 className="text-lg font-bold flex items-center gap-2"><Bot className="w-5 h-5" /> AI Analytics</h3><p className="text-indigo-100 text-xs">{selectedEmployee?.name}</p></div>
