                <div className="mb-4 p-3 bg-indigo-50 border border-indigo-100 rounded-md flex justify-between items-center"><span className="text-sm font-semibold">รวม</span><span className="text-lg font-bold text-indigo-700">{calculatedDatesToAdd.length} วัน</span></div>
                <div className="space-y-2 mb-6">
                {Object.values(LeaveType).map((type) => (
                    <button key={type} onClick={() => setLeaveType(type)} className={`w-full px-4 py-3 rounded-md border text-sm flex items-center justify-between transition-all ${leaveType === type ? `border-blue-600 bg-blue-50 text-blue-700 font-semibold` : 'border-slate-200 text-slate-600'}`}><span>{type}</span>{leaveType === type && <CheckCircle2 className="w-4 h-4" />}</button>
                ))}
                </div>
                <div className="flex gap-3 pt-2">
                    <button onClick={() => setIsLeaveModalOpen(false)} className="flex-1 py-2 rounded-md border text-sm">ยกเลิก</button>
                    <button onClick={handleSaveLeave} disabled={isSaving} className="flex-1 py-2 rounded-md bg-blue-700 text-white text-sm flex items-center justify-center gap-2 disabled:opacity-50">
                        {isSaving && <Loader2 className="w-4 h-4 animate-spin" />} บันทึก
                    </button>
                </div>
            </div>
          </div>
        </div>
      )}

      {/* User Management Modal */}
      {isManageUserModalOpen && (
        <div className="fixed inset-0 bg-slate-900/60 backdrop-blur-sm z-50 flex items-center justify-center p-4">
          <div className="bg-white rounded-xl shadow-2xl w-full max-w-2xl p-0 overflow-hidden flex flex-col max-h-[85vh] border border-slate-300">
            <div className="bg-slate-100 px-6 py-5 border-b border-slate-300 flex justify-between items-center">
                <div>
                  <h3 className="font-bold text-slate-950 text-xl flex items-center gap-2">
                    <Users className="w-6 h-6 text-blue-800" />จัดการรายชื่อพนักงาน
                  </h3>
                  <p className="text-sm text-slate-700 font-medium mt-1">แผนก: {currentDepartment}</p>
                </div>
                <div className="flex items-center gap-3">
                    <button onClick={handleSyncFromSheets} disabled={isSyncing} className="text-sm flex items-center gap-2 bg-blue-100 text-blue-900 border border-blue-400 px-4 py-2 rounded-md hover:bg-blue-200 disabled:opacity-50 font-bold shadow-sm transition-all">
                        {isSyncing ? <RefreshCw className="w-4 h-4 animate-spin" /> : <FileSpreadsheet className="w-4 h-4" />} 
                        {isSyncing ? 'กำลังซิงค์...' : 'ดึงข้อมูลจาก Sheets'}
                    </button>
                    <button onClick={() => setIsManageUserModalOpen(false)} className="text-slate-500 hover:text-slate-800 bg-white border border-slate-300 p-1 rounded-md transition-colors"><X className="w-7 h-7" /></button>
                </div>
            </div>

            <div className="p-6 bg-white border-b border-slate-200">
                <form onSubmit={handleUserSubmit} className="grid grid-cols-1 md:grid-cols-12 gap-5 items-end">
                    <div className="md:col-span-5">
                      <label className="text-sm font-bold text-slate-900 mb-1.5 block">ชื่อ - นามสกุล</label>
                      <input type="text" required placeholder="เช่น นายสมชาย ใจดี" value={userForm.name} onChange={e => setUserForm({...userForm, name: e.target.value})} className="w-full px-4 py-2.5 border-2 border-slate-300 rounded-md text-sm font-medium focus:border-blue-600 focus:ring-1 focus:ring-blue-600 outline-none transition-all placeholder:text-slate-400" />
                    </div>
                    <div className="md:col-span-5">
                      <label className="text-sm font-bold text-slate-900 mb-1.5 block">ตำแหน่ง</label>
                      <input type="text" required placeholder="เช่น เจ้าหน้าที่เวชระเบียน" value={userForm.position} onChange={e => setUserForm({...userForm, position: e.target.value})} className="w-full px-4 py-2.5 border-2 border-slate-300 rounded-md text-sm font-medium focus:border-blue-600 focus:ring-1 focus:ring-blue-600 outline-none transition-all placeholder:text-slate-400" />
                    </div>
                    <div className="md:col-span-2">
                      <button type="submit" disabled={isSaving} className="w-full py-2.5 bg-blue-700 text-white rounded-md flex items-center justify-center gap-2 font-bold text-sm hover:bg-blue-800 disabled:opacity-50 shadow-md active:scale-95 transition-all">
                        {isSaving ? <Loader2 className="w-5 h-5 animate-spin" /> : <UserPlus className="w-5 h-5" />}
                        เพิ่ม
                      </button>
                    </div>
                </form>
            </div>

            <div className="flex-1 overflow-y-auto bg-slate-50 p-6">
                 <h4 className="text-sm font-bold text-slate-800 mb-3 flex items-center gap-2">
                    <LayoutDashboard className="w-4 h-4" /> รายชื่อปัจจุบันในระบบ ({departmentEmployees.length})
                 </h4>
                 <div className="bg-white border-2 border-slate-200 rounded-lg overflow-hidden shadow-sm">
                    <table className="w-full text-sm text-left border-collapse">
                        <thead className="bg-slate-200 text-slate-900 border-b-2 border-slate-300">
                          <tr>
                            <th className="px-5 py-4 font-bold text-sm border-r border-slate-300">ชื่อ - นามสกุล</th>
                            <th className="px-5 py-4 font-bold text-sm border-r border-slate-300">ตำแหน่ง</th>
                            <th className="px-5 py-4 font-bold text-sm text-center">จัดการ</th>
                          </tr>
                        </thead>
                        <tbody className="divide-y-2 divide-slate-100">
                            {departmentEmployees.length > 0 ? (
                                departmentEmployees.map((emp) => (
                                    <tr key={emp.id} className="hover:bg-blue-50 transition-colors">
                                        <td className="px-5 py-4 font-bold text-slate-950 border-r border-slate-100">{emp.name}</td>
                                        <td className="px-5 py-4 text-slate-800 font-medium border-r border-slate-100">{emp.position}</td>
                                        <td className="px-5 py-4 text-center">
                                            <div className="flex items-center justify-center gap-3">
                                                <button onClick={() => setDeleteConfirm({isOpen:true, id:emp.id, name:emp.name})} className="p-2 text-red-600 hover:bg-red-100 rounded-md transition-all border border-transparent hover:border-red-300" title="ลบพนักงาน">
                                                  <Trash2 className="w-5 h-5" />
                                                </button>
                                            </div>
                                        </td>
                                    </tr>
                                ))
                            ) : (
                                <tr>
                                    <td colSpan={3} className="px-5 py-10 text-center text-slate-500 font-bold italic">
                                        ไม่มีรายชื่อพนักงานในแผนกนี้
                                    </td>
                                </tr>
                            )}
                        </tbody>
                    </table>
                 </div>
            </div>
          </div>
        </div>
      )}

      {/* Delete Confirmation Modal */}
      {deleteConfirm.isOpen && (
        <div className="fixed inset-0 bg-slate-900/40 backdrop-blur-sm z-[60] flex items-center justify-center p-4">
          <div className="bg-white rounded-lg shadow-2xl w-full max-w-sm p-6 animate-in fade-in zoom-in-95 duration-200 border-2 border-red-200">
            <div className="flex flex-col items-center text-center">
                <div className="w-14 h-14 rounded-full bg-red-100 text-red-600 flex items-center justify-center mb-4"><AlertTriangle className="w-8 h-8" /></div>
                <h3 className="text-xl font-bold text-slate-900 mb-2">ยืนยันการลบรายชื่อ?</h3>
                <p className="text-slate-700 text-sm mb-6 leading-relaxed">
                  คุณกำลังจะลบรายชื่อพนักงาน <br/><span className="font-bold text-red-600 text-base">"{deleteConfirm.name}"</span> <br/>ออกจากระบบอย่างถาวร
                </p>
                <div className="flex gap-3 w-full">
                    <button onClick={() => setDeleteConfirm({ isOpen: false, id: null, name: '' })} className="flex-1 py-2.5 rounded-md border-2 border-slate-300 text-slate-700 hover:bg-slate-50 font-bold text-sm transition-all">ยกเลิก</button>
                    <button onClick={executeDeleteUser} className="flex-1 py-2.5 rounded-md bg-red-600 text-white text-sm font-bold hover:bg-red-700 shadow-md active:scale-95 transition-all">ยืนยันการลบ</button>
                </div>
            </div>
          </div>
        </div>
      )}

      {/* AI Modal */}
      {isAiModalOpen && (
        <div className="fixed inset-0 bg-slate-900/50 backdrop-blur-sm z-50 flex items-center justify-center p-4">
          <div className="bg-white rounded-lg shadow-2xl w-full max-w-lg p-0 overflow-hidden flex flex-col max-h-[85vh]">
            <div className="bg-indigo-700 p-6 text-white flex justify-between items-start">
                <div><h3 className="text-lg font-bold flex items-center gap-2"><Bot className="w-5 h-5" /> AI Analytics</h3><p className="text-indigo-100 text-xs">{selectedEmployee?.name}</p></div>
                <button onClick={() => setIsAiModalOpen(false)} className="text-indigo-200 hover:text-white"><X className="w-5 h-5" /></button>
            </div>
            <div className="p-6 overflow-y-auto bg-white min-h-[300px]">
                {isAiLoading ? <div className="flex flex-col items-center justify-center py-12"><Activity className="w-8 h-8 animate-spin text-indigo-500 mb-3" /><p className="text-sm">วิเคราะห์ข้อมูล...</p></div> : <div className="text-slate-700 leading-relaxed text-sm whitespace-pre-line">{aiAnalysis}</div>}
            </div>
          </div>
        </div>
      )}
    </div>
  );
}

export default App;

import React, { useState, useMemo, useRef } from 'react';
import { 
  Users, Activity, Database, Search, Calendar as CalendarIcon, 
  ArrowLeft, CheckCircle2, Bot, LayoutDashboard, ChevronRight, UserPlus, X, Briefcase,
  Pencil, Trash2, Save, AlertTriangle, CalendarRange, Clock, RefreshCw, FileSpreadsheet, Loader2
} from 'lucide-react';
import { Department, Employee, LeaveRecord, LeaveType, LEAVE_COLORS } from './types';
import { INITIAL_EMPLOYEES, INITIAL_LEAVES, DEPARTMENTS, getHolidayName } from './constants';
import CalendarView from './components/CalendarView';
import StatsChart from './components/StatsChart';
import { analyzeLeaveData } from './services/geminiService';

// ลิงก์ Apps Script ของคุณ
const SCRIPT_URL = 'https://script.google.com/macros/s/AKfycbywlcsJehgmEv0Zujna3ThjX7Du43nOyA9Le5xL3iynvmFXwO1uRlIUpBUqWfV22aIl/exec';

function App() {
  const [currentDepartment, setCurrentDepartment] = useState<Department | null>(null);
  const [employees, setEmployees] = useState<Employee[]>(INITIAL_EMPLOYEES);
  const [searchQuery, setSearchQuery] = useState('');
  const [selectedEmployee, setSelectedEmployee] = useState<Employee | null>(null);
  const [leaves, setLeaves] = useState<LeaveRecord[]>(INITIAL_LEAVES);

  const [isLeaveModalOpen, setIsLeaveModalOpen] = useState(false);
  const [leaveStartDate, setLeaveStartDate] = useState<string>('');
  const [leaveEndDate, setLeaveEndDate] = useState<string>('');
  const [leaveType, setLeaveType] = useState<LeaveType>(LeaveType.PERSONAL);
  const [skipWeekends, setSkipWeekends] = useState(false);
  const [skipHolidays, setSkipHolidays] = useState(false);

  const [isManageUserModalOpen, setIsManageUserModalOpen] = useState(false);
  const [userForm, setUserForm] = useState({ name: '', position: '' });
  const [editingEmployeeId, setEditingEmployeeId] = useState<string | null>(null);
  const [isSyncing, setIsSyncing] = useState(false);
  const [isSaving, setIsSaving] = useState(false);

  const [deleteConfirm, setDeleteConfirm] = useState<{isOpen: boolean, id: string | null, name: string}>({
    isOpen: false, id: null, name: ''
  });

  const [aiAnalysis, setAiAnalysis] = useState<string>('');
  const [isAiLoading, setIsAiLoading] = useState(false);
  const [isAiModalOpen, setIsAiModalOpen] = useState(false);

  const startDateRef = useRef<HTMLInputElement>(null);
  const endDateRef = useRef<HTMLInputElement>(null);

  const departmentEmployees = useMemo(() => {
    if (!currentDepartment) return [];
    return employees.filter(emp => emp.department === currentDepartment);
  }, [currentDepartment, employees]);

  const filteredEmployees = useMemo(() => {
    if (!currentDepartment) return [];
    return employees.filter(emp => {
      const matchDept = emp.department === currentDepartment;
      const matchSearch = emp.name.toLowerCase().includes(searchQuery.toLowerCase());
      return matchDept && matchSearch;
    });
  }, [currentDepartment, searchQuery, employees]);

  const formatDateDisplay = (dateStr: string) => {
    if (!dateStr) return "";
    const [y, m, d] = dateStr.split('-');
    return `${d}/${m}/${parseInt(y) + 543}`;
  };

  const calculatedDatesToAdd = useMemo(() => {
    if (!leaveStartDate || !leaveEndDate) return [];
    const start = new Date(leaveStartDate);
    const end = new Date(leaveEndDate);
    if (isNaN(start.getTime()) || isNaN(end.getTime()) || start > end) return [];
    const dates: string[] = [];
    const loopDate = new Date(start);
    while (loopDate <= end) {
        const dateStr = loopDate.toISOString().split('T')[0];
        let shouldAdd = true;
        const dayOfWeek = loopDate.getUTCDay(); 
        if (skipWeekends && (dayOfWeek === 0 || dayOfWeek === 6)) shouldAdd = false;
        if (shouldAdd && skipHolidays) {
            const [y, m, d] = dateStr.split('-').map(Number);
            const checkDate = new Date(y, m - 1, d); 
            if (getHolidayName(checkDate)) shouldAdd = false;
        }
        if (shouldAdd) dates.push(dateStr);
        loopDate.setDate(loopDate.getDate() + 1);
    }
    return dates;
  }, [leaveStartDate, leaveEndDate, skipWeekends, skipHolidays]);

  /**
   * ฟังก์ชันส่งข้อมูลไปยัง Google Sheets
   */
  const postToSheets = async (data: any) => {
    setIsSaving(true);
    try {
      const response = await fetch(SCRIPT_URL, {
        method: 'POST',
        body: JSON.stringify(data),
      });
      console.log('Sheet update requested');
    } catch (error) {
      console.error('Error posting to sheet:', error);
    } finally {
      setIsSaving(false);
    }
  };

  const handleDepartmentSelect = (dept: Department) => {
    setCurrentDepartment(dept);
    setSearchQuery('');
    setSelectedEmployee(null);
  };

  const handleUserSelect = (emp: Employee) => {
    setSelectedEmployee(emp);
    setSearchQuery(emp.name);
  };

  const handleDateClick = (dateStr: string) => {
    if (!selectedEmployee) return;
    setLeaveStartDate(dateStr);
    setLeaveEndDate(dateStr); 
    setIsLeaveModalOpen(true);
  };

  const handleSaveLeave = async () => {
    if (!selectedEmployee || calculatedDatesToAdd.length === 0) return;

    const newLeavesLocal = calculatedDatesToAdd.map(date => ({
      id: Math.random().toString(36).substr(2, 9),
      employeeId: selectedEmployee.id!,
      date: date,
      type: leaveType
    }));

    setLeaves(prev => {
      const filtered = prev.filter(l => !(l.employeeId === selectedEmployee.id && calculatedDatesToAdd.includes(l.date)));
      return [...filtered, ...newLeavesLocal];
    });

    await postToSheets({
      action: "saveLeave",
      employeeName: selectedEmployee.name,
      department: currentDepartment,
      dates: calculatedDatesToAdd,
      leaveType: leaveType
    });

    setIsLeaveModalOpen(false);
  };

  const handleUserSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!userForm.name || !userForm.position || !currentDepartment) return;

    if (editingEmployeeId) {
        setEmployees(prev => prev.map(emp => 
            emp.id === editingEmployeeId 
                ? { ...emp, name: userForm.name, position: userForm.position }
                : emp
        ));
        setEditingEmployeeId(null);
    } else {
        const newEmp: Employee = {
            id: Math.random().toString(36).substr(2, 9),
            name: userForm.name,
            position: userForm.position,
            department: currentDepartment
        };
        setEmployees(prev => [...prev, newEmp]);

        await postToSheets({
          action: "addEmployee",
          name: userForm.name,
          position: userForm.position,
          department: currentDepartment
        });
    }
    setUserForm({ name: '', position: '' });
  };

  const handleSyncFromSheets = async () => {
    setIsSyncing(true);
    try {
      const response = await fetch(SCRIPT_URL);
      if (!response.ok) throw new Error('Network error');
      const syncedEmployees: Employee[] = await response.json();
      setEmployees(prev => {
        const combined = [...prev, ...syncedEmployees];
        return combined.filter((v, i, a) => a.findIndex(t => t.name === v.name) === i);
      });
      alert('✅ ซิงค์ข้อมูลพนักงานจาก Sheets สำเร็จ!');
    } catch (error) {
      alert('❌ ไม่สามารถซิงค์ข้อมูลได้: ' + error);
    } finally {
      setIsSyncing(false);
    }
  };

  const handleAiAnalyze = async () => {
    if (!selectedEmployee) return;
    setIsAiLoading(true);
    setIsAiModalOpen(true);
    try {
      const result = await analyzeLeaveData(
        selectedEmployee.name,
        leaves,
        employees
      );
      setAiAnalysis(result);
    } catch (error) {
      console.error("AI Analysis error:", error);
      setAiAnalysis("เกิดข้อผิดพลาดในการวิเคราะห์ข้อมูล");
    } finally {
      setIsAiLoading(false);
    }
  };

  const executeDeleteUser = () => {
    if (deleteConfirm.id) {
      setEmployees(prev => prev.filter(emp => emp.id !== deleteConfirm.id));
      if (selectedEmployee?.id === deleteConfirm.id) {
        setSelectedEmployee(null);
        setSearchQuery('');
      }
    }
    setDeleteConfirm({ isOpen: false, id: null, name: '' });
  };

  if (!currentDepartment) {
    return (
      <div className="min-h-screen bg-slate-50 flex flex-col items-center justify-center p-6 relative">
        <div className="text-center mb-12 relative z-10">
          <h1 className="text-3xl md:text-5xl font-bold text-slate-800 mb-4 tracking-tight">
             ระบบจัด<span className="text-blue-700">วันลา</span>ออนไลน์
          </h1>
          <p className="text-slate-500 text-base md:text-lg max-w-2xl mx-auto font-light">
            กรุณาเลือกหน่วยงานต้นสังกัดเพื่อเข้าสู่ระบบ
          </p>
        </div>
        <div className="grid grid-cols-1 md:grid-cols-3 gap-6 max-w-5xl w-full relative z-10 px-4">
          {DEPARTMENTS.map((dept) => {
            const Icon = dept.icon === 'Users' ? Users : dept.icon === 'Activity' ? Activity : Database;
            return (
              <button key={dept.id} onClick={() => handleDepartmentSelect(dept.id as Department)} className="group relative bg-white rounded-lg p-8 shadow-sm hover:shadow-md transition-all duration-200 border border-slate-200 hover:border-blue-300 text-left">
                <div className={`absolute top-0 left-0 w-1 h-full ${dept.color} transition-all duration-200 group-hover:w-2 rounded-l-lg`}></div>
                <div className="flex flex-col h-full justify-between gap-6">
                  <div className="flex items-start justify-between">
                     <div className="bg-slate-50 p-3 rounded-lg border border-slate-100 group-hover:bg-blue-50 group-hover:border-blue-100 transition-colors">
                        <Icon className="w-6 h-6 text-slate-700 group-hover:text-blue-700" />
                     </div>
                  </div>
                  <div>
                    <h3 className="text-xl font-bold text-slate-800 mb-1">{dept.label}</h3>
                    <div className="flex items-center text-slate-400 text-sm gap-1 group-hover:text-blue-700 transition-colors font-medium">
                      <span>เข้าสู่ระบบ</span><ChevronRight className="w-4 h-4" />
                    </div>
                  </div>
                </div>
              </button>
            );
          })}
        </div>
      </div>
    );
  }

  return (
    <div className="min-h-screen bg-slate-50 flex flex-col font-sans">
      <nav className="bg-white shadow-sm border-b border-slate-200 sticky top-0 z-40">
        <div className="max-w-[1600px] mx-auto px-4 md:px-6 py-4 flex items-center justify-between">
          <div className="flex items-center gap-4">
            <button onClick={() => setCurrentDepartment(null)} className="p-2 hover:bg-slate-100 rounded-lg text-slate-600 transition-colors border border-transparent">
              <ArrowLeft className="w-5 h-5" />
            </button>
            <div className="flex flex-col">
                <h1 className="text-xl font-bold text-slate-800 leading-none">{currentDepartment}</h1>
                <span className="text-xs text-slate-500 mt-1 flex items-center gap-1">
                   HR Management System 
                   {isSaving && <Loader2 className="w-3 h-3 animate-spin text-blue-600" />}
                </span>
            </div>
          </div>
          <div className="flex items-center gap-4">
             <div className="hidden lg:flex items-center gap-2 bg-slate-50 px-4 py-2 rounded-lg border border-slate-200">
               {Object.entries(LEAVE_COLORS).map(([type, color]) => (
                <div key={type} className="flex items-center gap-2 mr-4 last:mr-0">
                  <div className={`w-2 h-2 rounded-sm ${color}`}></div>
                  <span className="text-xs text-slate-600 font-medium">{type}</span>
                </div>
              ))}
             </div>
             <div className="h-9 w-9 rounded-full bg-slate-800 flex items-center justify-center text-white shadow-sm"><Users className="w-4 h-4" /></div>
          </div>
        </div>
      </nav>

      <main className="flex-1 max-w-[1600px] w-full mx-auto p-4 md:p-6 grid grid-cols-1 lg:grid-cols-12 gap-6 items-start">
        <aside className="lg:col-span-3 space-y-6 lg:sticky lg:top-24">
          <div className="bg-white rounded-lg shadow-sm border border-slate-200 overflow-hidden">
             <div className="px-5 py-4 border-b border-slate-100 bg-slate-50/50 flex justify-between items-center">
                <h2 className="text-slate-800 font-bold text-sm uppercase tracking-wide flex items-center gap-2">
                   <Search className="w-4 h-4 text-slate-500" />รายชื่อพนักงาน
                </h2>
                <button onClick={() => setIsManageUserModalOpen(true)} className="text-xs flex items-center gap-1 bg-white border border-slate-200 px-2 py-1 rounded text-blue-700 hover:border-blue-300 hover:bg-blue-50 transition-all font-medium">
                    <UserPlus className="w-3 h-3" />จัดการรายชื่อ
                </button>
             </div>
             <div className="p-5">
                <div className="relative mb-4">
                  <Search className="absolute left-3 top-1/2 -translate-y-1/2 text-slate-400 w-4 h-4" />
                  <input type="text" className="w-full pl-10 pr-4 py-2.5 bg-white border border-slate-200 rounded-lg outline-none text-sm font-medium" placeholder="ค้นหาชื่อ..." value={searchQuery} onChange={(e) => setSearchQuery(e.target.value)} />
                  {searchQuery && !selectedEmployee && filteredEmployees.length > 0 && (
                    <div className="absolute top-full left-0 right-0 mt-1 bg-white rounded-lg shadow-lg border border-slate-200 max-h-60 overflow-y-auto z-50">
                      {filteredEmployees.map(emp => (
                        <button key={emp.id} onClick={() => handleUserSelect(emp)} className="w-full text-left px-4 py-2.5 hover:bg-slate-50 flex items-center gap-3 border-b border-slate-50 last:border-0">
                          <div className="w-7 h-7 rounded bg-slate-100 text-slate-600 flex items-center justify-center font-bold text-xs shrink-0 border border-slate-200">{emp.name.charAt(0)}</div>
                          <div><p className="text-slate-800 text-sm font-medium">{emp.name}</p><p className="text-xs text-slate-500">{emp.position}</p></div>
                        </button>
                      ))}
                    </div>
                  )}
                </div>
                {selectedEmployee ? (
                  <div className="bg-slate-50 border border-slate-200 rounded-lg p-4 animate-fade-in">
                      <div className="flex items-start justify-between mb-4">
                         <div className="flex items-start gap-3">
                            <div className="w-10 h-10 rounded-lg bg-white border border-slate-200 text-slate-700 flex items-center justify-center font-bold text-lg shadow-sm">{selectedEmployee.name.charAt(0)}</div>
                            <div><h3 className="font-bold text-slate-800 text-sm">{selectedEmployee.name}</h3><p className="text-xs text-slate-500 flex items-center gap-1 mt-0.5"><Briefcase className="w-3 h-3" />{selectedEmployee.position}</p></div>
                         </div>
                         <CheckCircle2 className="text-blue-600 w-5 h-5" />
                      </div>
                      <button onClick={handleAiAnalyze} className="w-full flex items-center justify-center gap-2 bg-white border border-indigo-200 text-indigo-700 py-2 rounded-md hover:bg-indigo-50 transition-all text-xs font-semibold shadow-sm"><Bot className="w-3.5 h-3.5" />วิเคราะห์ AI</button>
                  </div>
                ) : (
                  <div className="text-center py-8 px-4 border border-dashed border-slate-300 rounded-lg"><Users className="w-6 h-6 text-slate-300 mx-auto mb-2" /><p className="text-xs text-slate-400">เลือกพนักงานเพื่อดูข้อมูล</p></div>
                )}
             </div>
          </div>
          <div className="bg-white rounded-lg shadow-sm border border-slate-200 overflow-hidden">
             <div className="px-5 py-4 border-b border-slate-100 bg-slate-50/50 flex items-center justify-between"><h2 className="text-slate-800 font-bold text-sm uppercase tracking-wide">สถิติปี {new Date().getFullYear() + 543}</h2></div>
             <div className="p-4"><StatsChart leaves={selectedEmployee ? leaves.filter(l => l.employeeId === selectedEmployee.id) : leaves.filter(l => departmentEmployees.some(e => e.id === l.employeeId))} currentYear={new Date().getFullYear()} /></div>
          </div>
        </aside>

        <section className="lg:col-span-9 h-full">
            <div className="bg-white rounded-lg shadow-sm border border-slate-200 overflow-hidden min-h-[650px]">
                <CalendarView leaves={leaves} employees={departmentEmployees} selectedEmployeeId={selectedEmployee?.id || null} onDateClick={handleDateClick} />
            </div>
        </section>
      </main>

      {/* Leave Modal */}
      {isLeaveModalOpen && (
        <div className="fixed inset-0 bg-slate-900/40 backdrop-blur-sm z-50 flex items-center justify-center p-4">
          <div className="bg-white rounded-lg shadow-2xl w-full max-w-md p-0 overflow-hidden animate-in fade-in zoom-in-95 duration-200">
            <div className="bg-slate-50 px-6 py-4 border-b border-slate-100 flex justify-between items-center">
                <h3 className="font-bold text-slate-800">บันทึกการลา</h3>
                <button onClick={() => setIsLeaveModalOpen(false)} className="text-slate-400 hover:text-slate-600"><X className="w-5 h-5" /></button>
            </div>
            <div className="p-6">
                <div className="grid grid-cols-2 gap-4 mb-4">
                    <div><label className="text-xs font-semibold">เริ่ม</label><input type="date" value={leaveStartDate} onChange={(e) => setLeaveStartDate(e.target.value)} className="w-full border rounded p-1 text-sm"/></div>
                    <div><label className="text-xs font-semibold">ถึง</label><input type="date" value={leaveEndDate} onChange={(e) => setLeaveEndDate(e.target.value)} className="w-full border rounded p-1 text-sm"/></div>
                </div>
                <div className="mb-4 p-3 bg-indigo-50 border border-indigo-100 rounded-md flex justify-between items-center"><span className="text-sm font-semibold">รวม</span><span className="text-lg font-bold text-indigo-700">{calculatedDatesToAdd.length} วัน</span></div>
                <div className="space-y-2 mb-6">
                {Object.values(LeaveType).map((type) => (
                    <button key={type} onClick={() => setLeaveType(type)} className={`w-full px-4 py-3 rounded-md border text-sm flex items-center justify-between transition-all ${leaveType === type ? `border-blue-600 bg-blue-50 text-blue-700 font-semibold` : 'border-slate-200 text-slate-600'}`}><span>{type}</span>{leaveType === type && <CheckCircle2 className="w-4 h-4" />}</button>
                ))}
                </div>
                <div className="flex gap-3 pt-2">
                    <button onClick={() => setIsLeaveModalOpen(false)} className="flex-1 py-2 rounded-md border text-sm">ยกเลิก</button>
                    <button onClick={handleSaveLeave} disabled={isSaving} className="flex-1 py-2 rounded-md bg-blue-700 text-white text-sm flex items-center justify-center gap-2 disabled:opacity-50">
                        {isSaving && <Loader2 className="w-4 h-4 animate-spin" />} บันทึก
                    </button>
                </div>
            </div>
          </div>
        </div>
      )}

      {/* User Management Modal */}
      {isManageUserModalOpen && (
        <div className="fixed inset-0 bg-slate-900/60 backdrop-blur-sm z-50 flex items-center justify-center p-4">
          <div className="bg-white rounded-xl shadow-2xl w-full max-w-2xl p-0 overflow-hidden flex flex-col max-h-[85vh] border border-slate-300">
            <div className="bg-slate-100 px-6 py-5 border-b border-slate-300 flex justify-between items-center">
                <div>
                  <h3 className="font-bold text-slate-950 text-xl flex items-center gap-2">
                    <Users className="w-6 h-6 text-blue-800" />จัดการรายชื่อพนักงาน
                  </h3>
                  <p className="text-sm text-slate-700 font-medium mt-1">แผนก: {currentDepartment}</p>
                </div>
                <div className="flex items-center gap-3">
                    <button onClick={handleSyncFromSheets} disabled={isSyncing} className="text-sm flex items-center gap-2 bg-blue-100 text-blue-900 border border-blue-400 px-4 py-2 rounded-md hover:bg-blue-200 disabled:opacity-50 font-bold shadow-sm transition-all">
                        {isSyncing ? <RefreshCw className="w-4 h-4 animate-spin" /> : <FileSpreadsheet className="w-4 h-4" />} 
                        {isSyncing ? 'กำลังซิงค์...' : 'ดึงข้อมูลจาก Sheets'}
                    </button>
                    <button onClick={() => setIsManageUserModalOpen(false)} className="text-slate-500 hover:text-slate-800 bg-white border border-slate-300 p-1 rounded-md transition-colors"><X className="w-7 h-7" /></button>
                </div>
            </div>

            <div className="p-6 bg-white border-b border-slate-200">
                <form onSubmit={handleUserSubmit} className="grid grid-cols-1 md:grid-cols-12 gap-5 items-end">
                    <div className="md:col-span-5">
                      <label className="text-sm font-bold text-slate-900 mb-1.5 block">ชื่อ - นามสกุล</label>
                      <input type="text" required placeholder="เช่น นายสมชาย ใจดี" value={userForm.name} onChange={e => setUserForm({...userForm, name: e.target.value})} className="w-full px-4 py-2.5 border-2 border-slate-300 rounded-md text-sm font-bold bg-white text-slate-950 focus:border-blue-600 focus:ring-1 focus:ring-blue-600 outline-none transition-all placeholder:text-slate-400" />
                    </div>
                    <div className="md:col-span-5">
                      <label className="text-sm font-bold text-slate-900 mb-1.5 block">ตำแหน่ง</label>
                      <input type="text" required placeholder="เช่น เจ้าหน้าที่เวชระเบียน" value={userForm.position} onChange={e => setUserForm({...userForm, position: e.target.value})} className="w-full px-4 py-2.5 border-2 border-slate-300 rounded-md text-sm font-bold bg-white text-slate-950 focus:border-blue-600 focus:ring-1 focus:ring-blue-600 outline-none transition-all placeholder:text-slate-400" />
                    </div>
                    <div className="md:col-span-2">
                      <button type="submit" disabled={isSaving} className="w-full py-2.5 bg-blue-700 text-white rounded-md flex items-center justify-center gap-2 font-bold text-sm hover:bg-blue-800 disabled:opacity-50 shadow-md active:scale-95 transition-all">
                        {isSaving ? <Loader2 className="w-5 h-5 animate-spin" /> : <UserPlus className="w-5 h-5" />}
                        เพิ่ม
                      </button>
                    </div>
                </form>
            </div>

            <div className="flex-1 overflow-y-auto bg-slate-50 p-6">
                 <h4 className="text-sm font-bold text-slate-800 mb-3 flex items-center gap-2">
                    <LayoutDashboard className="w-4 h-4" /> รายชื่อปัจจุบันในระบบ ({departmentEmployees.length})
                 </h4>
                 <div className="bg-white border-2 border-slate-200 rounded-lg overflow-hidden shadow-sm">
                    <table className="w-full text-sm text-left border-collapse">
                        <thead className="bg-slate-200 text-slate-900 border-b-2 border-slate-300">
                          <tr>
                            <th className="px-5 py-4 font-bold text-sm border-r border-slate-300">ชื่อ - นามสกุล</th>
                            <th className="px-5 py-4 font-bold text-sm border-r border-slate-300">ตำแหน่ง</th>
                            <th className="px-5 py-4 font-bold text-sm text-center">จัดการ</th>
                          </tr>
                        </thead>
                        <tbody className="divide-y-2 divide-slate-100">
                            {departmentEmployees.length > 0 ? (
                                departmentEmployees.map((emp) => (
                                    <tr key={emp.id} className="hover:bg-blue-50 transition-colors">
                                        <td className="px-5 py-4 font-bold text-slate-950 border-r border-slate-100">{emp.name}</td>
                                        <td className="px-5 py-4 text-slate-800 font-medium border-r border-slate-100">{emp.position}</td>
                                        <td className="px-5 py-4 text-center">
                                            <div className="flex items-center justify-center gap-3">
                                                <button onClick={() => setDeleteConfirm({isOpen:true, id:emp.id, name:emp.name})} className="p-2 text-red-600 hover:bg-red-100 rounded-md transition-all border border-transparent hover:border-red-300" title="ลบพนักงาน">
                                                  <Trash2 className="w-5 h-5" />
                                                </button>
                                            </div>
                                        </td>
                                    </tr>
                                ))
                            ) : (
                                <tr>
                                    <td colSpan={3} className="px-5 py-10 text-center text-slate-500 font-bold italic">
                                        ไม่มีรายชื่อพนักงานในแผนกนี้
                                    </td>
                                </tr>
                            )}
                        </tbody>
                    </table>
                 </div>
            </div>
          </div>
        </div>
      )}

      {/* Delete Confirmation Modal */}
      {deleteConfirm.isOpen && (
        <div className="fixed inset-0 bg-slate-900/40 backdrop-blur-sm z-[60] flex items-center justify-center p-4">
          <div className="bg-white rounded-lg shadow-2xl w-full max-w-sm p-6 animate-in fade-in zoom-in-95 duration-200 border-2 border-red-200">
            <div className="flex flex-col items-center text-center">
                <div className="w-14 h-14 rounded-full bg-red-100 text-red-600 flex items-center justify-center mb-4"><AlertTriangle className="w-8 h-8" /></div>
                <h3 className="text-xl font-bold text-slate-900 mb-2">ยืนยันการลบรายชื่อ?</h3>
                <p className="text-slate-700 text-sm mb-6 leading-relaxed">
                  คุณกำลังจะลบรายชื่อพนักงาน <br/><span className="font-bold text-red-600 text-base">"{deleteConfirm.name}"</span> <br/>ออกจากระบบอย่างถาวร
                </p>
                <div className="flex gap-3 w-full">
                    <button onClick={() => setDeleteConfirm({ isOpen: false, id: null, name: '' })} className="flex-1 py-2.5 rounded-md border-2 border-slate-300 text-slate-700 hover:bg-slate-50 font-bold text-sm transition-all">ยกเลิก</button>
                    <button onClick={executeDeleteUser} className="flex-1 py-2.5 rounded-md bg-red-600 text-white text-sm font-bold hover:bg-red-700 shadow-md active:scale-95 transition-all">ยืนยันการลบ</button>
                </div>
            </div>
          </div>
        </div>
      )}

      {/* AI Modal */}
      {isAiModalOpen && (
        <div className="fixed inset-0 bg-slate-900/50 backdrop-blur-sm z-50 flex items-center justify-center p-4">
          <div className="bg-white rounded-lg shadow-2xl w-full max-w-lg p-0 overflow-hidden flex flex-col max-h-[85vh]">
            <div className="bg-indigo-700 p-6 text-white flex justify-between items-start">
                <div><h3 className="text-lg font-bold flex items-center gap-2"><Bot className="w-5 h-5" /> AI Analytics</h3><p className="text-indigo-100 text-xs">{selectedEmployee?.name}</p></div>
                <button onClick={() => setIsAiModalOpen(false)} className="text-indigo-200 hover:text-white"><X className="w-5 h-5" /></button>
            </div>
            <div className="p-6 overflow-y-auto bg-white min-h-[300px]">
                {isAiLoading ? <div className="flex flex-col items-center justify-center py-12"><Activity className="w-8 h-8 animate-spin text-indigo-500 mb-3" /><p className="text-sm">วิเคราะห์ข้อมูล...</p></div> : <div className="text-slate-700 leading-relaxed text-sm whitespace-pre-line">{aiAnalysis}</div>}
            </div>
          </div>
        </div>
      )}
    </div>
  );
}

export default App;

import React, { useState, useMemo, useRef } from 'react';
import { 
  Users, Activity, Database, Search, Calendar as CalendarIcon, 
  ArrowLeft, CheckCircle2, Bot, LayoutDashboard, ChevronRight, UserPlus, X, Briefcase,
  Pencil, Trash2, Save, AlertTriangle, CalendarRange, Clock, RefreshCw, FileSpreadsheet, Loader2
} from 'lucide-react';
import { Department, Employee, LeaveRecord, LeaveType, LEAVE_COLORS } from './types';
import { INITIAL_EMPLOYEES, INITIAL_LEAVES, DEPARTMENTS, getHolidayName } from './constants';
import CalendarView from './components/CalendarView';
import StatsChart from './components/StatsChart';
import { analyzeLeaveData } from './services/geminiService';

// ลิงก์ Apps Script ของคุณ
const SCRIPT_URL = 'https://script.google.com/macros/s/AKfycbywlcsJehgmEv0Zujna3ThjX7Du43nOyA9Le5xL3iynvmFXwO1uRlIUpBUqWfV22aIl/exec';

function App() {
  const [currentDepartment, setCurrentDepartment] = useState<Department | null>(null);
  const [employees, setEmployees] = useState<Employee[]>(INITIAL_EMPLOYEES);
  const [searchQuery, setSearchQuery] = useState('');
  const [selectedEmployee, setSelectedEmployee] = useState<Employee | null>(null);
  const [leaves, setLeaves] = useState<LeaveRecord[]>(INITIAL_LEAVES);

  const [isLeaveModalOpen, setIsLeaveModalOpen] = useState(false);
  const [leaveStartDate, setLeaveStartDate] = useState<string>('');
  const [leaveEndDate, setLeaveEndDate] = useState<string>('');
  const [leaveType, setLeaveType] = useState<LeaveType>(LeaveType.PERSONAL);
  const [skipWeekends, setSkipWeekends] = useState(false);
  const [skipHolidays, setSkipHolidays] = useState(false);

  const [isManageUserModalOpen, setIsManageUserModalOpen] = useState(false);
  const [userForm, setUserForm] = useState({ name: '', position: '' });
  const [editingEmployeeId, setEditingEmployeeId] = useState<string | null>(null);
  const [isSyncing, setIsSyncing] = useState(false);
  const [isSaving, setIsSaving] = useState(false);

  const [deleteConfirm, setDeleteConfirm] = useState<{isOpen: boolean, id: string | null, name: string}>({
    isOpen: false, id: null, name: ''
  });

  const [aiAnalysis, setAiAnalysis] = useState<string>('');
  const [isAiLoading, setIsAiLoading] = useState(false);
  const [isAiModalOpen, setIsAiModalOpen] = useState(false);

  const startDateRef = useRef<HTMLInputElement>(null);
  const endDateRef = useRef<HTMLInputElement>(null);

  const departmentEmployees = useMemo(() => {
    if (!currentDepartment) return [];
    return employees.filter(emp => emp.department === currentDepartment);
  }, [currentDepartment, employees]);

  const filteredEmployees = useMemo(() => {
    if (!currentDepartment) return [];
    return employees.filter(emp => {
      const matchDept = emp.department === currentDepartment;
      const matchSearch = emp.name.toLowerCase().includes(searchQuery.toLowerCase());
      return matchDept && matchSearch;
    });
  }, [currentDepartment, searchQuery, employees]);

  const formatDateDisplay = (dateStr: string) => {
    if (!dateStr) return "";
    const [y, m, d] = dateStr.split('-');
    return `${d}/${m}/${parseInt(y) + 543}`;
  };

  const calculatedDatesToAdd = useMemo(() => {
    if (!leaveStartDate || !leaveEndDate) return [];
    const start = new Date(leaveStartDate);
    const end = new Date(leaveEndDate);
    if (isNaN(start.getTime()) || isNaN(end.getTime()) || start > end) return [];
    const dates: string[] = [];
    const loopDate = new Date(start);
    while (loopDate <= end) {
        const dateStr = loopDate.toISOString().split('T')[0];
        let shouldAdd = true;
        const dayOfWeek = loopDate.getUTCDay(); 
        if (skipWeekends && (dayOfWeek === 0 || dayOfWeek === 6)) shouldAdd = false;
        if (shouldAdd && skipHolidays) {
            const [y, m, d] = dateStr.split('-').map(Number);
            const checkDate = new Date(y, m - 1, d); 
            if (getHolidayName(checkDate)) shouldAdd = false;
        }
        if (shouldAdd) dates.push(dateStr);
        loopDate.setDate(loopDate.getDate() + 1);
    }
    return dates;
  }, [leaveStartDate, leaveEndDate, skipWeekends, skipHolidays]);

  /**
   * ฟังก์ชันส่งข้อมูลไปยัง Google Sheets
   */
  const postToSheets = async (data: any) => {
    setIsSaving(true);
    try {
      const response = await fetch(SCRIPT_URL, {
        method: 'POST',
        body: JSON.stringify(data),
      });
      console.log('Sheet update requested');
    } catch (error) {
      console.error('Error posting to sheet:', error);
    } finally {
      setIsSaving(false);
    }
  };

  const handleDepartmentSelect = (dept: Department) => {
    setCurrentDepartment(dept);
    setSearchQuery('');
    setSelectedEmployee(null);
  };

  const handleUserSelect = (emp: Employee) => {
    setSelectedEmployee(emp);
    setSearchQuery(emp.name);
  };

  const handleDateClick = (dateStr: string) => {
    if (!selectedEmployee) return;
    setLeaveStartDate(dateStr);
    setLeaveEndDate(dateStr); 
    setIsLeaveModalOpen(true);
  };

  const handleSaveLeave = async () => {
    if (!selectedEmployee || calculatedDatesToAdd.length === 0) return;

    const newLeavesLocal = calculatedDatesToAdd.map(date => ({
      id: Math.random().toString(36).substr(2, 9),
      employeeId: selectedEmployee.id!,
      date: date,
      type: leaveType
    }));

    setLeaves(prev => {
      const filtered = prev.filter(l => !(l.employeeId === selectedEmployee.id && calculatedDatesToAdd.includes(l.date)));
      return [...filtered, ...newLeavesLocal];
    });

    await postToSheets({
      action: "saveLeave",
      employeeName: selectedEmployee.name,
      department: currentDepartment,
      dates: calculatedDatesToAdd,
      leaveType: leaveType
    });

    setIsLeaveModalOpen(false);
  };

  const handleUserSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!userForm.name || !userForm.position || !currentDepartment) return;

    if (editingEmployeeId) {
        setEmployees(prev => prev.map(emp => 
            emp.id === editingEmployeeId 
                ? { ...emp, name: userForm.name, position: userForm.position }
                : emp
        ));
        setEditingEmployeeId(null);
    } else {
        const newEmp: Employee = {
            id: Math.random().toString(36).substr(2, 9),
            name: userForm.name,
            position: userForm.position,
            department: currentDepartment
        };
        setEmployees(prev => [...prev, newEmp]);

        await postToSheets({
          action: "addEmployee",
          name: userForm.name,
          position: userForm.position,
          department: currentDepartment
        });
    }
    setUserForm({ name: '', position: '' });
  };

  const handleSyncFromSheets = async () => {
    setIsSyncing(true);
    try {
      const response = await fetch(SCRIPT_URL);
      if (!response.ok) throw new Error('Network error');
      const syncedEmployees: Employee[] = await response.json();
      setEmployees(prev => {
        const combined = [...prev, ...syncedEmployees];
        return combined.filter((v, i, a) => a.findIndex(t => t.name === v.name) === i);
      });
      alert('✅ ซิงค์ข้อมูลพนักงานจาก Sheets สำเร็จ!');
    } catch (error) {
      alert('❌ ไม่สามารถซิงค์ข้อมูลได้: ' + error);
    } finally {
      setIsSyncing(false);
    }
  };

  const handleAiAnalyze = async () => {
    if (!selectedEmployee) return;
    setIsAiLoading(true);
    setIsAiModalOpen(true);
    try {
      const result = await analyzeLeaveData(
        selectedEmployee.name,
        leaves,
        employees
      );
      setAiAnalysis(result);
    } catch (error) {
      console.error("AI Analysis error:", error);
      setAiAnalysis("เกิดข้อผิดพลาดในการวิเคราะห์ข้อมูล");
    } finally {
      setIsAiLoading(false);
    }
  };

  const executeDeleteUser = () => {
    if (deleteConfirm.id) {
      setEmployees(prev => prev.filter(emp => emp.id !== deleteConfirm.id));
      if (selectedEmployee?.id === deleteConfirm.id) {
        setSelectedEmployee(null);
        setSearchQuery('');
      }
    }
    setDeleteConfirm({ isOpen: false, id: null, name: '' });
  };

  if (!currentDepartment) {
    return (
      <div className="min-h-screen bg-slate-50 flex flex-col items-center justify-center p-6 relative">
        <div className="text-center mb-12 relative z-10">
          <h1 className="text-3xl md:text-5xl font-bold text-slate-900 mb-4 tracking-tight">
             ระบบจัด<span className="text-blue-700">วันลา</span>ออนไลน์
          </h1>
          <p className="text-slate-700 text-base md:text-lg max-w-2xl mx-auto font-medium">
            กรุณาเลือกหน่วยงานต้นสังกัดเพื่อเข้าสู่ระบบ
          </p>
        </div>
        <div className="grid grid-cols-1 md:grid-cols-3 gap-6 max-w-5xl w-full relative z-10 px-4">
          {DEPARTMENTS.map((dept) => {
            const Icon = dept.icon === 'Users' ? Users : dept.icon === 'Activity' ? Activity : Database;
            return (
