      {/* Weekdays */}
      <div className="grid grid-cols-7 border-b-2 border-slate-300 bg-slate-200">
        {['อาทิตย์', 'จันทร์', 'อังคาร', 'พุธ', 'พฤหัสบดี', 'ศุกร์', 'เสาร์'].map((d, i) => (
