            <div className="bg-indigo-800 p-6 text-white flex justify-between items-start shadow-md">
                <div><h3 className="text-xl font-black flex items-center gap-3"><Bot className="w-6 h-6" /> AI Analytics</h3><p className="text-indigo-100 text-xs font-bold mt-1 uppercase tracking-wider">{selectedEmployee?.name}</p></div>
                <button onClick={() => setIsAiModalOpen(false)} className="text-indigo-100 hover:text-white border border-indigo-500 rounded p-1"><X className="w-6 h-6" /></button>
            </div>
            <div className="p-8 overflow-y-auto bg-white min-h-[350px]">
                {isAiLoading ? (
                  <div className="flex flex-col items-center justify-center py-16">
                    <div className="relative">
                      <Activity className="w-12 h-12 animate-pulse text-indigo-600 mb-4" />
                      <Loader2 className="w-12 h-12 animate-spin text-indigo-200 absolute inset-0" />
                    </div>
                    <p className="text-base font-black text-slate-900 mt-4">AI กำลังประมวลผลข้อมูล...</p>
                  </div>
                ) : (
                  <div className="text-slate-950 leading-relaxed text-base font-medium whitespace-pre-line bg-slate-50 p-6 rounded-xl border border-slate-200 shadow-inner">
                    {aiAnalysis}
                  </div>
                )}
            </div>
          </div>
        </div>
      )}
    </div>
  );
}

export default App;

import React, { useState, useMemo, useRef } from 'react';
import { 
  Users, Activity, Database, Search, Calendar as CalendarIcon, 
  ArrowLeft, CheckCircle2, Bot, LayoutDashboard, ChevronRight, UserPlus, X, Briefcase,
  Pencil, Trash2, Save, AlertTriangle, CalendarRange, Clock, RefreshCw, FileSpreadsheet, Loader2
} from 'lucide-react';
import { Department, Employee, LeaveRecord, LeaveType, LEAVE_COLORS } from './types';
import { INITIAL_EMPLOYEES, INITIAL_LEAVES, DEPARTMENTS, getHolidayName } from './constants';
import CalendarView from './components/CalendarView';
import StatsChart from './components/StatsChart';
import { analyzeLeaveData } from './services/geminiService';

// ลิงก์ Apps Script ของคุณ
const SCRIPT_URL = 'https://script.google.com/macros/s/AKfycbywlcsJehgmEv0Zujna3ThjX7Du43nOyA9Le5xL3iynvmFXwO1uRlIUpBUqWfV22aIl/exec';

function App() {
  const [currentDepartment, setCurrentDepartment] = useState<Department | null>(null);
  const [employees, setEmployees] = useState<Employee[]>(INITIAL_EMPLOYEES);
  const [searchQuery, setSearchQuery] = useState('');
  const [selectedEmployee, setSelectedEmployee] = useState<Employee | null>(null);
  const [leaves, setLeaves] = useState<LeaveRecord[]>(INITIAL_LEAVES);

  const [isLeaveModalOpen, setIsLeaveModalOpen] = useState(false);
  const [leaveStartDate, setLeaveStartDate] = useState<string>('');
  const [leaveEndDate, setLeaveEndDate] = useState<string>('');
  const [leaveType, setLeaveType] = useState<LeaveType>(LeaveType.PERSONAL);
  const [skipWeekends, setSkipWeekends] = useState(false);
  const [skipHolidays, setSkipHolidays] = useState(false);

  const [isManageUserModalOpen, setIsManageUserModalOpen] = useState(false);
  const [userForm, setUserForm] = useState({ name: '', position: '' });
  const [editingEmployeeId, setEditingEmployeeId] = useState<string | null>(null);
  const [isSyncing, setIsSyncing] = useState(false);
  const [isSaving, setIsSaving] = useState(false);

  const [deleteConfirm, setDeleteConfirm] = useState<{isOpen: boolean, id: string | null, name: string}>({
    isOpen: false, id: null, name: ''
  });

  const [aiAnalysis, setAiAnalysis] = useState<string>('');
  const [isAiLoading, setIsAiLoading] = useState(false);
  const [isAiModalOpen, setIsAiModalOpen] = useState(false);

  const startDateRef = useRef<HTMLInputElement>(null);
  const endDateRef = useRef<HTMLInputElement>(null);

  const departmentEmployees = useMemo(() => {
    if (!currentDepartment) return [];
    return employees.filter(emp => emp.department === currentDepartment);
  }, [currentDepartment, employees]);

  const filteredEmployees = useMemo(() => {
    if (!currentDepartment) return [];
    return employees.filter(emp => {
      const matchDept = emp.department === currentDepartment;
      const matchSearch = emp.name.toLowerCase().includes(searchQuery.toLowerCase());
      return matchDept && matchSearch;
    });
  }, [currentDepartment, searchQuery, employees]);

  const formatDateDisplay = (dateStr: string) => {
    if (!dateStr) return "";
    const [y, m, d] = dateStr.split('-');
    return `${d}/${m}/${parseInt(y) + 543}`;
  };

  const calculatedDatesToAdd = useMemo(() => {
    if (!leaveStartDate || !leaveEndDate) return [];
    const start = new Date(leaveStartDate);
    const end = new Date(leaveEndDate);
    if (isNaN(start.getTime()) || isNaN(end.getTime()) || start > end) return [];
    const dates: string[] = [];
    const loopDate = new Date(start);
    while (loopDate <= end) {
        const dateStr = loopDate.toISOString().split('T')[0];
        let shouldAdd = true;
        const dayOfWeek = loopDate.getUTCDay(); 
        if (skipWeekends && (dayOfWeek === 0 || dayOfWeek === 6)) shouldAdd = false;
        if (shouldAdd && skipHolidays) {
            const [y, m, d] = dateStr.split('-').map(Number);
            const checkDate = new Date(y, m - 1, d); 
            if (getHolidayName(checkDate)) shouldAdd = false;
        }
        if (shouldAdd) dates.push(dateStr);
        loopDate.setDate(loopDate.getDate() + 1);
    }
    return dates;
  }, [leaveStartDate, leaveEndDate, skipWeekends, skipHolidays]);

  /**
   * ฟังก์ชันส่งข้อมูลไปยัง Google Sheets
   */
  const postToSheets = async (data: any) => {
    setIsSaving(true);
    try {
      const response = await fetch(SCRIPT_URL, {
        method: 'POST',
        body: JSON.stringify(data),
      });
      console.log('Sheet update requested');
    } catch (error) {
      console.error('Error posting to sheet:', error);
    } finally {
      setIsSaving(false);
    }
  };

  const handleDepartmentSelect = (dept: Department) => {
    setCurrentDepartment(dept);
    setSearchQuery('');
    setSelectedEmployee(null);
  };

  const handleUserSelect = (emp: Employee) => {
    setSelectedEmployee(emp);
    setSearchQuery(emp.name);
  };

  const handleDateClick = (dateStr: string) => {
    if (!selectedEmployee) return;
    setLeaveStartDate(dateStr);
    setLeaveEndDate(dateStr); 
    setIsLeaveModalOpen(true);
  };

  const handleSaveLeave = async () => {
    if (!selectedEmployee || calculatedDatesToAdd.length === 0) return;

    const newLeavesLocal = calculatedDatesToAdd.map(date => ({
      id: Math.random().toString(36).substr(2, 9),
      employeeId: selectedEmployee.id!,
      date: date,
      type: leaveType
    }));

    setLeaves(prev => {
      const filtered = prev.filter(l => !(l.employeeId === selectedEmployee.id && calculatedDatesToAdd.includes(l.date)));
      return [...filtered, ...newLeavesLocal];
    });

    await postToSheets({
      action: "saveLeave",
      employeeName: selectedEmployee.name,
      department: currentDepartment,
      dates: calculatedDatesToAdd,
      leaveType: leaveType
    });

    setIsLeaveModalOpen(false);

    // เคลียร์ค่ารายชื่อออกหลังจากบันทึก
    setSelectedEmployee(null);
    setSearchQuery('');
  };

  const handleUserSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!userForm.name || !userForm.position || !currentDepartment) return;

    if (editingEmployeeId) {
        setEmployees(prev => prev.map(emp => 
            emp.id === editingEmployeeId 
                ? { ...emp, name: userForm.name, position: userForm.position }
                : emp
        ));
        setEditingEmployeeId(null);
    } else {
        const newEmp: Employee = {
            id: Math.random().toString(36).substr(2, 9),
            name: userForm.name,
            position: userForm.position,
            department: currentDepartment
        };
        setEmployees(prev => [...prev, newEmp]);

        await postToSheets({
          action: "addEmployee",
          name: userForm.name,
          position: userForm.position,
          department: currentDepartment
        });
    }
    setUserForm({ name: '', position: '' });
  };

  const handleSyncFromSheets = async () => {
    setIsSyncing(true);
    try {
      const response = await fetch(SCRIPT_URL);
      if (!response.ok) throw new Error('Network error');
      const syncedEmployees: Employee[] = await response.json();
      setEmployees(prev => {
        const combined = [...prev, ...syncedEmployees];
        return combined.filter((v, i, a) => a.findIndex(t => t.name === v.name) === i);
      });
      alert('✅ ซิงค์ข้อมูลพนักงานจาก Sheets สำเร็จ!');
    } catch (error) {
      alert('❌ ไม่สามารถซิงค์ข้อมูลได้: ' + error);
    } finally {
      setIsSyncing(false);
    }
  };

  const handleAiAnalyze = async () => {
    if (!selectedEmployee) return;
    setIsAiLoading(true);
    setIsAiModalOpen(true);
    try {
      const result = await analyzeLeaveData(
        selectedEmployee.name,
        leaves,
        employees
      );
      setAiAnalysis(result);
    } catch (error) {
      console.error("AI Analysis error:", error);
      setAiAnalysis("เกิดข้อผิดพลาดในการวิเคราะห์ข้อมูล");
    } finally {
      setIsAiLoading(false);
    }
  };

  const executeDeleteUser = () => {
    if (deleteConfirm.id) {
      setEmployees(prev => prev.filter(emp => emp.id !== deleteConfirm.id));
      if (selectedEmployee?.id === deleteConfirm.id) {
        setSelectedEmployee(null);
        setSearchQuery('');
      }
    }
    setDeleteConfirm({ isOpen: false, id: null, name: '' });
  };

  if (!currentDepartment) {
    return (
      <div className="min-h-screen bg-slate-50 flex flex-col items-center justify-center p-6 relative">
        <div className="text-center mb-12 relative z-10">
          <h1 className="text-3xl md:text-5xl font-bold text-slate-900 mb-4 tracking-tight">
             ระบบจัด<span className="text-blue-700">วันลา</span>ออนไลน์
          </h1>
          <p className="text-slate-700 text-base md:text-lg max-w-2xl mx-auto font-medium">
            กรุณาเลือกหน่วยงานต้นสังกัดเพื่อเข้าสู่ระบบ
          </p>
        </div>
        <div className="grid grid-cols-1 md:grid-cols-3 gap-6 max-w-5xl w-full relative z-10 px-4">
          {DEPARTMENTS.map((dept) => {
            const Icon = dept.icon === 'Users' ? Users : dept.icon === 'Activity' ? Activity : Database;
            return (
              <button key={dept.id} onClick={() => handleDepartmentSelect(dept.id as Department)} className="group relative bg-white rounded-lg p-8 shadow-sm hover:shadow-md transition-all duration-200 border border-slate-300 hover:border-blue-500 text-left">
                <div className={`absolute top-0 left-0 w-1 h-full ${dept.color} transition-all duration-200 group-hover:w-2 rounded-l-lg`}></div>
                <div className="flex flex-col h-full justify-between gap-6">
                  <div className="flex items-start justify-between">
                     <div className="bg-slate-100 p-3 rounded-lg border border-slate-200 group-hover:bg-blue-50 group-hover:border-blue-200 transition-colors">
                        <Icon className="w-6 h-6 text-slate-800 group-hover:text-blue-800" />
                     </div>
                  </div>
                  <div>
                    <h3 className="text-xl font-bold text-slate-950 mb-1">{dept.label}</h3>
                    <div className="flex items-center text-slate-600 text-sm gap-1 group-hover:text-blue-800 transition-colors font-bold">
                      <span>เข้าสู่ระบบ</span><ChevronRight className="w-4 h-4" />
                    </div>
                  </div>
                </div>
              </button>
            );
          })}
        </div>
      </div>
    );
  }

  return (
    <div className="min-h-screen bg-slate-50 flex flex-col font-sans">
      <nav className="bg-white shadow-sm border-b border-slate-200 sticky top-0 z-40">
        <div className="max-w-[1600px] mx-auto px-4 md:px-6 py-4 flex items-center justify-between">
          <div className="flex items-center gap-4">
            <button onClick={() => setCurrentDepartment(null)} className="p-2 hover:bg-slate-100 rounded-lg text-slate-800 transition-colors border border-transparent">
              <ArrowLeft className="w-5 h-5" />
            </button>
            <div className="flex flex-col">
                <h1 className="text-xl font-bold text-slate-950 leading-none">{currentDepartment}</h1>
                <span className="text-xs text-slate-700 font-bold mt-1 flex items-center gap-1">
                   HR Management System 
                   {isSaving && <Loader2 className="w-3 h-3 animate-spin text-blue-800" />}
                </span>
            </div>
          </div>
          <div className="flex items-center gap-4">
             <div className="hidden lg:flex items-center gap-2 bg-slate-50 px-4 py-2 rounded-lg border border-slate-200">
               {Object.entries(LEAVE_COLORS).map(([type, color]) => (
                <div key={type} className="flex items-center gap-2 mr-4 last:mr-0">
                  <div className={`w-2.5 h-2.5 rounded-sm ${color}`}></div>
                  <span className="text-xs text-slate-800 font-bold">{type}</span>
                </div>
              ))}
             </div>
             <div className="h-9 w-9 rounded-full bg-slate-900 flex items-center justify-center text-white shadow-sm"><Users className="w-4 h-4" /></div>
          </div>
        </div>
      </nav>

      <main className="flex-1 max-w-[1600px] w-full mx-auto p-4 md:p-6 grid grid-cols-1 lg:grid-cols-12 gap-6 items-start">
        <aside className="lg:col-span-3 space-y-6 lg:sticky lg:top-24">
          <div className="bg-white rounded-lg shadow-sm border border-slate-200 overflow-hidden">
             <div className="px-5 py-4 border-b border-slate-200 bg-slate-100/50 flex justify-between items-center">
                <h2 className="text-slate-950 font-bold text-sm uppercase tracking-wide flex items-center gap-2">
                   <Search className="w-4 h-4 text-slate-700" />รายชื่อพนักงาน
                </h2>
                <button onClick={() => setIsManageUserModalOpen(true)} className="text-xs flex items-center gap-1 bg-white border-2 border-slate-300 px-2.5 py-1.5 rounded text-blue-900 hover:border-blue-600 hover:bg-blue-50 transition-all font-bold">
                    <UserPlus className="w-3.5 h-3.5" />จัดการรายชื่อ
                </button>
             </div>
             <div className="p-5">
                <div className="relative mb-4">
                  <Search className="absolute left-3 top-1/2 -translate-y-1/2 text-slate-600 w-4 h-4" />
                  <input 
                    type="text" 
                    className="w-full pl-10 pr-4 py-2.5 bg-white border-2 border-slate-300 rounded-lg outline-none text-sm font-bold text-slate-950 focus:border-blue-600" 
                    placeholder="ค้นหาชื่อ..." 
                    value={searchQuery} 
                    onChange={(e) => {
                        setSearchQuery(e.target.value);
                        if (e.target.value === '') {
                            setSelectedEmployee(null);
                        }
                    }} 
                  />
                  {searchQuery && !selectedEmployee && filteredEmployees.length > 0 && (
                    <div className="absolute top-full left-0 right-0 mt-1 bg-white rounded-lg shadow-xl border-2 border-slate-300 max-h-60 overflow-y-auto z-50">
                      {filteredEmployees.map(emp => (
                        <button key={emp.id} onClick={() => handleUserSelect(emp)} className="w-full text-left px-4 py-2.5 hover:bg-slate-50 flex items-center gap-3 border-b border-slate-100 last:border-0">
                          <div className="w-7 h-7 rounded bg-slate-200 text-slate-900 flex items-center justify-center font-bold text-xs shrink-0 border border-slate-300">{emp.name.charAt(0)}</div>
                          <div><p className="text-slate-950 text-sm font-bold">{emp.name}</p><p className="text-xs text-slate-700 font-medium">{emp.position}</p></div>
                        </button>
                      ))}
                    </div>
                  )}
                </div>
                {selectedEmployee ? (
                  <div className="bg-slate-50 border-2 border-slate-300 rounded-lg p-4 animate-fade-in">
                      <div className="flex items-start justify-between mb-4">
                         <div className="flex items-start gap-3">
                            <div className="w-10 h-10 rounded-lg bg-white border-2 border-slate-300 text-slate-950 flex items-center justify-center font-bold text-lg shadow-sm">{selectedEmployee.name.charAt(0)}</div>
                            <div><h3 className="font-bold text-slate-950 text-sm">{selectedEmployee.name}</h3><p className="text-xs text-slate-700 font-bold flex items-center gap-1 mt-0.5"><Briefcase className="w-3 h-3 text-slate-900" />{selectedEmployee.position}</p></div>
                         </div>
                         <CheckCircle2 className="text-blue-800 w-5 h-5" />
                      </div>
                      <button onClick={handleAiAnalyze} className="w-full flex items-center justify-center gap-2 bg-white border-2 border-indigo-300 text-indigo-900 py-2.5 rounded-md hover:bg-indigo-50 transition-all text-xs font-bold shadow-sm"><Bot className="w-4 h-4" />วิเคราะห์ AI</button>
                  </div>
                ) : (
                  <div className="text-center py-10 px-4 border-2 border-dashed border-slate-300 rounded-lg"><Users className="w-8 h-8 text-slate-400 mx-auto mb-3" /><p className="text-sm text-slate-600 font-bold italic">เลือกพนักงานเพื่อดูข้อมูล</p></div>
                )}
             </div>
          </div>
          <div className="bg-white rounded-lg shadow-sm border border-slate-200 overflow-hidden">
             <div className="px-5 py-4 border-b border-slate-200 bg-slate-100/50 flex items-center justify-between"><h2 className="text-slate-950 font-bold text-sm uppercase tracking-wide">สถิติปี {new Date().getFullYear() + 543}</h2></div>
             <div className="p-4"><StatsChart leaves={selectedEmployee ? leaves.filter(l => l.employeeId === selectedEmployee.id) : leaves.filter(l => departmentEmployees.some(e => e.id === l.employeeId))} currentYear={new Date().getFullYear()} /></div>
          </div>
        </aside>

        <section className="lg:col-span-9 h-full">
            <div className="bg-white rounded-lg shadow-sm border border-slate-200 overflow-hidden min-h-[650px]">
                <CalendarView leaves={leaves} employees={departmentEmployees} selectedEmployeeId={selectedEmployee?.id || null} onDateClick={handleDateClick} />
            </div>
        </section>
      </main>

      {/* Leave Modal */}
      {isLeaveModalOpen && (
        <div className="fixed inset-0 bg-slate-900/40 backdrop-blur-sm z-50 flex items-center justify-center p-4">
          <div className="bg-white rounded-lg shadow-2xl w-full max-w-md p-0 overflow-hidden animate-in fade-in zoom-in-95 duration-200 border border-slate-300">
            <div className="bg-slate-100 px-6 py-4 border-b border-slate-200 flex justify-between items-center">
                <h3 className="font-bold text-slate-950">บันทึกการลา</h3>
                <button onClick={() => setIsLeaveModalOpen(false)} className="text-slate-600 hover:text-slate-950 border border-slate-300 rounded p-1"><X className="w-5 h-5" /></button>
            </div>
            <div className="p-6">
                <div className="grid grid-cols-2 gap-4 mb-4">
                    <div>
                        <label className="text-sm font-bold text-slate-900 mb-1 block">เริ่ม</label>
                        <input 
                            type="date" 
                            value={leaveStartDate} 
                            onChange={(e) => setLeaveStartDate(e.target.value)} 
                            className="w-full border-2 border-slate-300 rounded p-2 text-sm font-light bg-white text-slate-950"
                        />
                    </div>
                    <div>
                        <label className="text-sm font-bold text-slate-900 mb-1 block">ถึง</label>
                        <input 
                            type="date" 
                            value={leaveEndDate} 
                            onChange={(e) => setLeaveEndDate(e.target.value)} 
                            className="w-full border-2 border-slate-300 rounded p-2 text-sm font-light bg-white text-slate-950"
                        />
                    </div>
                </div>
                <div className="mb-4 p-4 bg-indigo-50 border-2 border-indigo-200 rounded-md flex justify-between items-center shadow-sm"><span className="text-sm font-bold text-slate-800">รวมระยะเวลา</span><span className="text-xl font-black text-indigo-900">{calculatedDatesToAdd.length} วัน</span></div>
                <div className="space-y-2 mb-6">
                {Object.values(LeaveType).map((type) => (
                    <button key={type} onClick={() => setLeaveType(type)} className={`w-full px-4 py-3 rounded-md border-2 text-sm flex items-center justify-between transition-all ${leaveType === type ? `border-blue-700 bg-blue-100 text-blue-950 font-black shadow-inner` : 'border-slate-300 text-slate-800 font-bold hover:border-slate-400'}`}><span>{type}</span>{leaveType === type && <CheckCircle2 className="w-5 h-5 text-blue-800" />}</button>
                ))}
                </div>
                <div className="flex gap-4 pt-2">
                    <button onClick={() => setIsLeaveModalOpen(false)} className="flex-1 py-3 rounded-md border-2 border-slate-300 text-slate-800 font-bold hover:bg-slate-50">ยกเลิก</button>
                    <button onClick={handleSaveLeave} disabled={isSaving} className="flex-1 py-3 rounded-md bg-blue-800 text-white font-bold text-sm flex items-center justify-center gap-2 disabled:opacity-50 hover:bg-blue-900 shadow-md">
                        {isSaving && <Loader2 className="w-4 h-4 animate-spin text-white" />} บันทึกการลา
                    </button>
                </div>
            </div>
          </div>
        </div>
      )}

      {/* User Management Modal */}
      {isManageUserModalOpen && (
        <div className="fixed inset-0 bg-slate-900/60 backdrop-blur-sm z-50 flex items-center justify-center p-4">
          <div className="bg-white rounded-xl shadow-2xl w-full max-w-2xl p-0 overflow-hidden flex flex-col max-h-[85vh] border-2 border-slate-300">
            <div className="bg-slate-100 px-6 py-5 border-b-2 border-slate-300 flex justify-between items-center">
                <div>
                  <h3 className="font-bold text-slate-950 text-xl flex items-center gap-2">
                    <Users className="w-6 h-6 text-blue-800" />จัดการรายชื่อพนักงาน
                  </h3>
                  <p className="text-sm text-slate-800 font-black mt-1">แผนก: {currentDepartment}</p>
                </div>
                <div className="flex items-center gap-3">
                    <button onClick={handleSyncFromSheets} disabled={isSyncing} className="text-sm flex items-center gap-2 bg-blue-100 text-blue-950 border-2 border-blue-500 px-4 py-2 rounded-md hover:bg-blue-200 disabled:opacity-50 font-black shadow-md transition-all">
                        {isSyncing ? <RefreshCw className="w-4 h-4 animate-spin" /> : <FileSpreadsheet className="w-4 h-4" />} 
                        {isSyncing ? 'กำลังซิงค์...' : 'ดึงข้อมูลจาก Sheets'}
                    </button>
                    <button onClick={() => setIsManageUserModalOpen(false)} className="text-slate-800 hover:text-white hover:bg-slate-800 bg-white border-2 border-slate-300 p-1.5 rounded-md transition-all"><X className="w-7 h-7" /></button>
                </div>
            </div>

            <div className="p-6 bg-white border-b-2 border-slate-200">
                <form onSubmit={handleUserSubmit} className="grid grid-cols-1 md:grid-cols-12 gap-5 items-end">
                    <div className="md:col-span-5">
                      <label className="text-sm font-black text-slate-950 mb-2 block">ชื่อ - นามสกุล</label>
                      <input type="text" required placeholder="เช่น นายสมชาย ใจดี" value={userForm.name} onChange={e => setUserForm({...userForm, name: e.target.value})} className="w-full px-4 py-3 border-2 border-slate-400 rounded-md text-sm font-black bg-slate-100 text-slate-950 focus:border-blue-700 focus:ring-1 focus:ring-blue-700 outline-none transition-all placeholder:text-slate-500" />
