import React, { useState, useMemo } from 'react';
import { ChevronLeft, ChevronRight, Info, Calendar as CalendarIcon } from 'lucide-react';
import { LeaveRecord, LeaveType, LEAVE_COLORS, Employee } from '../types';
import { getHolidayName } from '../constants';

interface CalendarViewProps {
  leaves: LeaveRecord[];
  onDateClick: (dateStr: string) => void;
  onLeaveClick: (leaveId: string, date: string, type: LeaveType) => void; // Added prop for deletion
  selectedEmployeeId: string | null;
  employees: Employee[]; // Passed from parent to resolve names
}

interface DailyLeave {
    id: string; // Added ID
    employeeId: string;
    name: string;
    type: LeaveType;
    isSelected: boolean;
}

const CalendarView: React.FC<CalendarViewProps> = ({ leaves, onDateClick, onLeaveClick, selectedEmployeeId, employees }) => {
  const [currentDate, setCurrentDate] = useState(new Date());

  const year = currentDate.getFullYear();
  const month = currentDate.getMonth();

  const daysInMonth = new Date(year, month + 1, 0).getDate();
  const firstDayOfMonth = new Date(year, month, 1).getDay(); // 0 = Sunday

  const prevMonth = () => setCurrentDate(new Date(year, month - 1, 1));
  const nextMonth = () => setCurrentDate(new Date(year, month + 1, 1));

  // Map Date -> Array of Leaves (Name + Type)
  const leavesMap = useMemo(() => {
    const map: Record<string, DailyLeave[]> = {};
    leaves.forEach(l => {
      // Find employee info to get name
      const emp = employees.find(e => e.id === l.employeeId);

      // If employee not found (maybe not in this department), skip
      if (!emp) return;

      if (!map[l.date]) {
          map[l.date] = [];
      }

      map[l.date].push({
          id: l.id, // Include ID
          employeeId: l.employeeId,
          name: emp.name.split(' ')[0], // Get first name only
          type: l.type,
          isSelected: selectedEmployeeId === l.employeeId
      });
    });
    return map;
  }, [leaves, selectedEmployeeId, employees]);

  const renderDays = () => {
    const days = [];

    // Padding
    for (let i = 0; i < firstDayOfMonth; i++) {
      days.push(<div key={`empty-${i}`} className="min-h-[100px] md:min-h-[120px] bg-slate-50/50 border-r border-b border-slate-200"></div>);
    }

    // Days
    for (let i = 1; i <= daysInMonth; i++) {
      const dayStr = i.toString().padStart(2, '0');
      const monthStr = (month + 1).toString().padStart(2, '0');
      const dateStr = `${year}-${monthStr}-${dayStr}`;

      const currentDayDate = new Date(year, month, i);
      const dailyLeaves = leavesMap[dateStr] || []; // Array of leaves for this day

      const isToday = new Date().toDateString() === currentDayDate.toDateString();
      const isWeekend = currentDayDate.getDay() === 0 || currentDayDate.getDay() === 6;
      const holidayName = getHolidayName(currentDayDate);
      const isHoliday = !!holidayName;

      // Determine if it's a non-working day (Weekend OR Holiday)
      const isNonWorkingDay = isWeekend || isHoliday;

      days.push(
        <div 
          key={i} 
          onClick={() => {
            if (!isNonWorkingDay && selectedEmployeeId) {
                onDateClick(dateStr);
            }
          }}
          className={`min-h-[100px] md:min-h-[120px] border-r border-b border-slate-200 p-2 relative transition-all duration-150 group flex flex-col
            ${isHoliday ? 'bg-red-50/40' : isWeekend ? 'bg-slate-50/60' : 'bg-white'}
            ${selectedEmployeeId && !isNonWorkingDay ? 'cursor-pointer hover:bg-white hover:shadow-md hover:z-10' : ''}
            ${!selectedEmployeeId || isNonWorkingDay ? 'cursor-default' : ''}
            ${isToday ? '!bg-blue-50/60 ring-1 ring-inset ring-blue-200' : ''}
          `}
        >
          {/* Holiday Color Strip */}
          {isHoliday && (
             <div className="absolute top-0 left-0 right-0 h-[3px] bg-red-400 opacity-70"></div>
          )}

          <div className="flex justify-between items-start mb-1 mt-1 shrink-0">
            <span className={`
                text-sm font-medium h-7 w-7 flex items-center justify-center rounded-full relative z-20
                ${isToday ? 'bg-blue-700 text-white shadow-sm' : isHoliday ? 'text-red-600' : isNonWorkingDay ? 'text-slate-500' : 'text-slate-700'}
            `}>
              {i}
            </span>
          </div>

          {/* Holiday Label - Beautifully Styled */}
          {holidayName && (
             <div className="mt-1 mb-1 relative z-10 shrink-0">
                <span className="text-[11px] leading-tight text-red-700 font-medium bg-red-100/60 px-1.5 py-0.5 rounded border border-red-200/60 block w-fit max-w-full truncate shadow-sm">
                    {holidayName}
                </span>
             </div>
          )}

          {/* Leave List (Names) */}
          <div className="flex flex-col gap-1 overflow-y-auto max-h-[80px] custom-scrollbar relative z-10">
            {dailyLeaves.map((leave, idx) => {
                const isSelectionActive = !!selectedEmployeeId;
                const isSelf = leave.isSelected;

                // Base Color
                let colorClass = LEAVE_COLORS[leave.type];
                let styleClass = '';

                if (isSelectionActive) {
                    if (isSelf) {
                        // Selected: Darker color, bold
                        // Convert standard colors to darker variants (600->800, 500->700)
                        colorClass = colorClass.replace('600', '800').replace('500', '700');
                        styleClass = 'font-bold z-20 cursor-pointer hover:ring-2 hover:ring-red-400 hover:scale-[1.02]';
                    } else {
                        // Others: Faded out
                        styleClass = 'opacity-30 grayscale-[30%] z-0 pointer-events-none';
                    }
                } else {
                    // Normal view
                    styleClass = 'opacity-90 hover:opacity-100';
                }

                return (
                    <div 
                        key={idx}
                        onClick={(e) => {
                            if (isSelf) {
                                e.stopPropagation();
                                onLeaveClick(leave.id, dateStr, leave.type);
                            }
                        }}
                        className={`
                            px-1.5 py-0.5 rounded text-[11px] text-white font-medium truncate shadow-sm transition-all
                            ${colorClass}
                            ${styleClass}
                        `}
                        title={isSelf ? 'คลิกเพื่อลบ' : `${leave.name} - ${leave.type}`}
                    >
                        {leave.name}
                    </div>
                );
            })}
          </div>

          {!selectedEmployeeId && i === 1 && dailyLeaves.length === 0 && !isNonWorkingDay && (
            <div className="absolute inset-0 flex items-center justify-center p-2 pointer-events-none z-0 opacity-40">
                <span className="bg-slate-100 text-slate-500 text-xs px-2 py-1 rounded border border-slate-200 whitespace-nowrap">
                    ว่าง
                </span>
            </div>
          )}
        </div>
      );
    }
    return days;
  };

  const thaiMonths = [
    "มกราคม", "กุมภาพันธ์", "มีนาคม", "เมษายน", "พฤษภาคม", "มิถุนายน",
    "กรกฎาคม", "สิงหาคม", "กันยายน", "ตุลาคม", "พฤศจิกายน", "ธันวาคม"
  ];

  return (
    <div className="bg-white h-full flex flex-col">
      {/* Header */}
      <div className="px-6 py-4 flex items-center justify-between border-b border-slate-200 bg-white">
        <div className="flex items-center gap-3">
             <div className="bg-white border border-slate-200 p-2 rounded-md shadow-sm">
                 <CalendarIcon className="w-5 h-5 text-slate-700" />
             </div>
             <div>
                <h2 className="text-xl font-bold text-slate-800 flex items-baseline gap-2">
                {thaiMonths[month]} <span className="text-slate-300 font-light">|</span> {year + 543}
                </h2>
                <p className="text-xs text-slate-500 font-medium mt-0.5">คลิกวันที่ต้องการลา</p>
             </div>
        </div>

        <div className="flex items-center gap-1 bg-white border border-slate-200 rounded-md p-0.5 shadow-sm">
            <button onClick={prevMonth} className="p-1.5 hover:bg-slate-100 rounded text-slate-600 transition-all">
            <ChevronLeft className="w-5 h-5" />
            </button>
            <div className="w-px h-5 bg-slate-200 mx-1"></div>
            <button onClick={nextMonth} className="p-1.5 hover:bg-slate-100 rounded text-slate-600 transition-all">
            <ChevronRight className="w-5 h-5" />
            </button>
        </div>
      </div>

      {/* Weekdays */}
      <div className="grid grid-cols-7 border-b border-slate-200 bg-slate-50">
        {['อาทิตย์', 'จันทร์', 'อังคาร', 'พุธ', 'พฤหัสบดี', 'ศุกร์', 'เสาร์'].map((d, i) => (
          <div key={i} className={`py-3 text-center text-xs font-bold border-r border-slate-200 last:border-r-0 ${i === 0 || i === 6 ? 'text-red-600' : 'text-slate-600'}`}>
            <span className="hidden md:inline">{d}</span>
            <span className="md:hidden">{d.charAt(0)}</span>
          </div>
        ))}
      </div>

      {/* Days Grid */}
      <div className="grid grid-cols-7 flex-1 auto-rows-fr bg-slate-200 gap-px border-b border-slate-200">
        {renderDays()}
      </div>

      {!selectedEmployeeId && (
        <div className="p-3 bg-slate-50 border-t border-slate-200 text-slate-500 text-xs flex items-center justify-center gap-2">
            <Info className="w-4 h-4"/> 
            <span>แสดงข้อมูลวันลาของพนักงานทั้งหมดในแผนก</span>
        </div>
      )}
    </div>
  );
};

export default CalendarView;

