                      <label className="text-sm font-black text-slate-950 mb-2 block">ตำแหน่ง</label>
                      <input type="text" required placeholder="เช่น เจ้าหน้าที่เวชระเบียน" value={userForm.position} onChange={e => setUserForm({...userForm, position: e.target.value})} className="w-full px-4 py-3 border-2 border-slate-400 rounded-md text-sm font-black bg-slate-100 text-slate-950 focus:border-blue-700 focus:ring-1 focus:ring-blue-700 outline-none transition-all placeholder:text-slate-500" />
                    </div>
                    <div className="md:col-span-2">
                      <button type="submit" disabled={isSaving} className="w-full py-3 bg-blue-800 text-white rounded-md flex items-center justify-center gap-2 font-black text-sm hover:bg-blue-900 disabled:opacity-50 shadow-lg active:scale-95 transition-all">
