/**
 * Google Apps Script สำหรับระบบจัดการวันลา (เวอร์ชัน อัปเดตการดึงข้อมูลวันลา)
 * วิธีใช้: 
 * 1. วางโค้ดนี้แทนที่ของเดิม
 * 2. **สำคัญ**: กด Deploy -> New deployment เพื่ออัปเดตระบบ
 */

const DEPARTMENTS = ["เวชระเบียนผู้ป่วยนอก", "เวชระเบียนผู้ป่วยใน", "ศูนย์ข้อมูล"];
const LEAVE_SHEET_NAME = "บันทึกการลา";

function onOpen() {
  const ui = SpreadsheetApp.getUi();
  ui.createMenu('🚀 ระบบจัดการพนักงาน')
    .addItem('1. ตั้งค่าเริ่มต้น/สร้างตาราง', 'setupSheets')
    .addToUi();
}

function setupSheets() {
  const ss = SpreadsheetApp.getActiveSpreadsheet();

  // สร้างตารางแผนก
  DEPARTMENTS.forEach(deptName => {
    let sheet = ss.getSheetByName(deptName);
    if (!sheet) {
      sheet = ss.insertSheet(deptName);
      sheet.appendRow(["ชื่อ - นามสกุล", "ตำแหน่ง"]);
      formatHeader(sheet);
    }
  });

  // สร้างตารางบันทึกการลา
  let leaveSheet = ss.getSheetByName(LEAVE_SHEET_NAME);
  if (!leaveSheet) {
    leaveSheet = ss.insertSheet(LEAVE_SHEET_NAME);
    leaveSheet.appendRow(["วันเวลาที่บันทึก", "ชื่อพนักงาน", "แผนก", "วันที่ลา", "ประเภทการลา"]);
    formatHeader(leaveSheet);
    leaveSheet.setColumnWidth(1, 150);
    leaveSheet.setColumnWidth(2, 200);
    leaveSheet.setColumnWidth(3, 150);
    leaveSheet.setColumnWidth(4, 120);
    leaveSheet.setColumnWidth(5, 120);
  }

  const sheet1 = ss.getSheetByName("Sheet1");
  if (sheet1) ss.deleteSheet(sheet1);

  SpreadsheetApp.getUi().alert('✅ เตรียมตารางเรียบร้อยแล้ว!');
}

function formatHeader(sheet) {
  const headerRange = sheet.getRange(1, 1, 1, sheet.getLastColumn());
  headerRange.setFontWeight("bold").setBackground("#e2e8f0").setFontFamily("Kanit");
}

/**
 * รับข้อมูลจากหน้าเว็บ (GET) - ดึงทั้งรายชื่อพนักงาน และ ข้อมูลการลา
 */
function doGet(e) {
  const ss = SpreadsheetApp.getActiveSpreadsheet();

  // 1. ดึงรายชื่อพนักงาน
  const allEmployees = [];
  DEPARTMENTS.forEach(deptName => {
    const sheet = ss.getSheetByName(deptName);
    if (sheet) {
      const data = sheet.getDataRange().getValues();
      for (let i = 1; i < data.length; i++) {
        if (data[i][0]) {
          allEmployees.push({
            id: deptName + "_" + i,
            name: data[i][0],
            position: data[i][1] || "",
            department: deptName
          });
        }
      }
    }
  });

  // 2. ดึงข้อมูลการลา
  const allLeaves = [];
  const leaveSheet = ss.getSheetByName(LEAVE_SHEET_NAME);
  if (leaveSheet) {
    const data = leaveSheet.getDataRange().getValues();
    // header: ["วันเวลาที่บันทึก", "ชื่อพนักงาน", "แผนก", "วันที่ลา", "ประเภทการลา"]
    for (let i = 1; i < data.length; i++) {
       const row = data[i];
       const empName = row[1];
       const dateVal = row[3];
       const leaveType = row[4];

       if (empName && dateVal) {
          // แปลงวันที่ให้เป็น Format YYYY-MM-DD
          let dateStr = "";
          let dateObj;

          if (dateVal instanceof Date) {
            dateObj = dateVal;
          } else {
            dateObj = new Date(dateVal);
          }

          if (!isNaN(dateObj.getTime())) {
             const y = dateObj.getFullYear();
             const m = (dateObj.getMonth() + 1).toString().padStart(2, '0');
             const d = dateObj.getDate().toString().padStart(2, '0');
             dateStr = `${y}-${m}-${d}`;

             allLeaves.push({
               id: "leave_" + i,
               employeeName: empName,
               date: dateStr,
               type: leaveType
             });
          }
       }
    }
  }

  // ส่งคืนทั้งพนักงานและการลา
  const result = {
    employees: allEmployees,
    leaves: allLeaves
  };

  return ContentService.createTextOutput(JSON.stringify(result))
    .setMimeType(ContentService.MimeType.JSON);
}

/**
 * รับข้อมูลจากหน้าเว็บ (POST) - สำหรับบันทึกข้อมูล
 */
function doPost(e) {
  try {
    const data = JSON.parse(e.postData.contents);
    const ss = SpreadsheetApp.getActiveSpreadsheet();
    const action = data.action;

    if (action === "addEmployee") {
      const sheet = ss.getSheetByName(data.department);
      if (sheet) {
        sheet.appendRow([data.name, data.position]);
        return makeResponse("success", "บันทึกพนักงานเรียบร้อย");
      }
    } 

    if (action === "saveLeave") {
      const sheet = ss.getSheetByName(LEAVE_SHEET_NAME);
      if (sheet) {
        data.dates.forEach(date => {
          sheet.appendRow([
            new Date(), 
            data.employeeName, 
            data.department, 
            date, 
            data.leaveType
          ]);
        });
        return makeResponse("success", "บันทึกการลาเรียบร้อย");
      }
    }

    // เพิ่มฟังก์ชันลบการลา (ถ้าต้องการในอนาคต)
    if (action === "deleteLeave") {
       // การลบข้อมูลใน Sheets ซับซ้อนกว่าเล็กน้อย อาจจะต้องใช้วิธีวนลูปหาแถวที่ตรงกัน
       // ในเวอร์ชันนี้เราจะรับ request ไว้แต่ยังไม่ลบจริงใน sheet เพื่อความปลอดภัยของข้อมูล
       return makeResponse("success", "รับคำขอลบรายการเรียบร้อย");
    }

    return makeResponse("error", "ไม่พบ Action ที่ต้องการ");
  } catch (err) {
    return makeResponse("error", err.toString());
  }
}

function makeResponse(status, message) {
  return ContentService.createTextOutput(JSON.stringify({ status: status, message: message }))
    .setMimeType(ContentService.MimeType.JSON);
}

import React, { useState, useMemo, useRef, useEffect } from 'react';
import { 
  Users, Activity, Database, Search, Calendar as CalendarIcon, 
  ArrowLeft, CheckCircle2, Bot, LayoutDashboard, ChevronRight, UserPlus, X, Briefcase,
  Pencil, Trash2, Save, AlertTriangle, CalendarRange, Clock, RefreshCw, FileSpreadsheet, Loader2
} from 'lucide-react';
import { Department, Employee, LeaveRecord, LeaveType, LEAVE_COLORS } from './types';
import { INITIAL_EMPLOYEES, INITIAL_LEAVES, DEPARTMENTS, getHolidayName } from './constants';
import CalendarView from './components/CalendarView';
import StatsChart from './components/StatsChart';
import ThaiDatePicker from './components/ThaiDatePicker';
import { analyzeLeaveData } from './services/geminiService';

// ลิงก์ Apps Script ของคุณ
const SCRIPT_URL = 'https://script.google.com/macros/s/AKfycbywlcsJehgmEv0Zujna3ThjX7Du43nOyA9Le5xL3iynvmFXwO1uRlIUpBUqWfV22aIl/exec';

function App() {
  const [currentDepartment, setCurrentDepartment] = useState<Department | null>(null);
  const [employees, setEmployees] = useState<Employee[]>(INITIAL_EMPLOYEES);
  const [searchQuery, setSearchQuery] = useState('');
  const [selectedEmployee, setSelectedEmployee] = useState<Employee | null>(null);
  const [leaves, setLeaves] = useState<LeaveRecord[]>(INITIAL_LEAVES);

  const [isLeaveModalOpen, setIsLeaveModalOpen] = useState(false);
  const [leaveStartDate, setLeaveStartDate] = useState<string>('');
  const [leaveEndDate, setLeaveEndDate] = useState<string>('');
  const [leaveType, setLeaveType] = useState<LeaveType>(LeaveType.PERSONAL);
  const [skipWeekends, setSkipWeekends] = useState(false);
  const [skipHolidays, setSkipHolidays] = useState(false);

  const [isManageUserModalOpen, setIsManageUserModalOpen] = useState(false);
  const [userForm, setUserForm] = useState({ name: '', position: '' });
  const [editingEmployeeId, setEditingEmployeeId] = useState<string | null>(null);
  const [isSyncing, setIsSyncing] = useState(false);
  const [isSaving, setIsSaving] = useState(false);

  const [deleteConfirm, setDeleteConfirm] = useState<{isOpen: boolean, id: string | null, name: string}>({
    isOpen: false, id: null, name: ''
  });

  // New state for leave deletion
  const [leaveToDelete, setLeaveToDelete] = useState<{id: string, date: string, type: LeaveType} | null>(null);

  const [aiAnalysis, setAiAnalysis] = useState<string>('');
  const [isAiLoading, setIsAiLoading] = useState(false);
  const [isAiModalOpen, setIsAiModalOpen] = useState(false);

  // Function to fetch all data
  const fetchAndSetData = async (isShowAlert = false) => {
    setIsSyncing(true);
    try {
      const response = await fetch(SCRIPT_URL);
      if (!response.ok) throw new Error('Failed to fetch data');

      const data = await response.json();

      // จัดการข้อมูลตามรูปแบบที่ได้รับมา (รองรับทั้งแบบเก่าและใหม่)
      let fetchedEmployees: Employee[] = [];
      let fetchedLeavesRaw: any[] = [];

      if (Array.isArray(data)) {
         // กรณีแบบเก่า (ได้มาแต่อาร์เรย์พนักงาน)
         fetchedEmployees = data;
      } else if (data.employees) {
         // กรณีแบบใหม่ (ได้ทั้งพนักงานและวันลา)
         fetchedEmployees = data.employees;
         fetchedLeavesRaw = data.leaves || [];
      }

      setEmployees(fetchedEmployees);

      // แปลงข้อมูลการลา ให้เชื่อมโยงกับ ID พนักงาน
      if (fetchedLeavesRaw.length > 0) {
         const processedLeaves: LeaveRecord[] = fetchedLeavesRaw.map((l: any) => {
            // ค้นหาพนักงานจากชื่อ เพื่อเอา ID
            const employee = fetchedEmployees.find(e => e.name === l.employeeName);
            if (!employee) return null;

            return {
               id: l.id || Math.random().toString(36),
               employeeId: employee.id,
               date: l.date,
               type: l.type as LeaveType
            };
         }).filter((l): l is LeaveRecord => l !== null);

         setLeaves(processedLeaves);
      }

      if (isShowAlert) alert('✅ ซิงค์ข้อมูลสำเร็จ!');
    } catch (error) {
      console.error("Error loading data:", error);
      if (isShowAlert) alert('❌ เกิดข้อผิดพลาด: ' + error);
    } finally {
      setIsSyncing(false);
    }
  };

  // Load initial data from Sheets on mount
  useEffect(() => {
    fetchAndSetData(false);
  }, []);

  const departmentEmployees = useMemo(() => {
    if (!currentDepartment) return [];
    return employees.filter(emp => emp.department === currentDepartment);
  }, [currentDepartment, employees]);

  const filteredEmployees = useMemo(() => {
    if (!currentDepartment) return [];
    return employees.filter(emp => {
      const matchDept = emp.department === currentDepartment;
      const matchSearch = emp.name.toLowerCase().includes(searchQuery.toLowerCase());
      return matchDept && matchSearch;
    });
  }, [currentDepartment, searchQuery, employees]);

  const formatDateDisplay = (dateStr: string) => {
    if (!dateStr) return "";
    const [y, m, d] = dateStr.split('-');
    return `${d}/${m}/${parseInt(y) + 543}`;
  };

  const calculatedDatesToAdd = useMemo(() => {
    if (!leaveStartDate || !leaveEndDate) return [];
    const start = new Date(leaveStartDate);
    const end = new Date(leaveEndDate);
    if (isNaN(start.getTime()) || isNaN(end.getTime()) || start > end) return [];
    const dates: string[] = [];
    const loopDate = new Date(start);
    while (loopDate <= end) {
        const dateStr = loopDate.toISOString().split('T')[0];
        let shouldAdd = true;
        const dayOfWeek = loopDate.getUTCDay(); 
        if (skipWeekends && (dayOfWeek === 0 || dayOfWeek === 6)) shouldAdd = false;
        if (shouldAdd && skipHolidays) {
            const [y, m, d] = dateStr.split('-').map(Number);
            const checkDate = new Date(y, m - 1, d); 
            if (getHolidayName(checkDate)) shouldAdd = false;
        }
        if (shouldAdd) dates.push(dateStr);
        loopDate.setDate(loopDate.getDate() + 1);
    }
    return dates;
  }, [leaveStartDate, leaveEndDate, skipWeekends, skipHolidays]);

  /**
   * ฟังก์ชันส่งข้อมูลไปยัง Google Sheets
   */
  const postToSheets = async (data: any) => {
    setIsSaving(true);
    try {
      const response = await fetch(SCRIPT_URL, {
        method: 'POST',
        body: JSON.stringify(data),
      });
      console.log('Sheet update requested');
    } catch (error) {
      console.error('Error posting to sheet:', error);
    } finally {
      setIsSaving(false);
    }
  };

  const handleDepartmentSelect = (dept: Department) => {
    setCurrentDepartment(dept);
    setSearchQuery('');
    setSelectedEmployee(null);
  };

  const handleUserSelect = (emp: Employee) => {
    setSelectedEmployee(emp);
    setSearchQuery(emp.name);
  };

  const handleDateClick = (dateStr: string) => {
    if (!selectedEmployee) return;
    setLeaveStartDate(dateStr);
    setLeaveEndDate(dateStr); 
    setIsLeaveModalOpen(true);
  };

  const handleLeaveClick = (leaveId: string, date: string, type: LeaveType) => {
      setLeaveToDelete({ id: leaveId, date, type });
  };

  const handleConfirmDeleteLeave = async () => {
      if (!leaveToDelete || !selectedEmployee) return;

      // Update local state
      setLeaves(prev => prev.filter(l => l.id !== leaveToDelete.id));

      // Close modal
      setLeaveToDelete(null);

