import React, { useState, useEffect, useRef } from 'react';
import { ChevronLeft, ChevronRight, Calendar as CalendarIcon } from 'lucide-react';

interface ThaiDatePickerProps {
  label: string;
  value: string;
  onChange: (date: string) => void;
}

const ThaiDatePicker: React.FC<ThaiDatePickerProps> = ({ label, value, onChange }) => {
  const [isOpen, setIsOpen] = useState(false);
  const [viewDate, setViewDate] = useState(new Date());
  const containerRef = useRef<HTMLDivElement>(null);

  useEffect(() => {
    if (value) {
      const date = new Date(value);
      if (!isNaN(date.getTime())) setViewDate(date);
    }
  }, [isOpen, value]);

  useEffect(() => {
    const handleClickOutside = (event: MouseEvent) => {
      if (containerRef.current && !containerRef.current.contains(event.target as Node)) setIsOpen(false);
    };
    document.addEventListener('mousedown', handleClickOutside);
    return () => document.removeEventListener('mousedown', handleClickOutside);
  }, []);

  const thaiMonths = ["มกราคม", "กุมภาพันธ์", "มีนาคม", "เมษายน", "พฤษภาคม", "มิถุนายน", "กรกฎาคม", "สิงหาคม", "กันยายน", "ตุลาคม", "พฤศจิกายน", "ธันวาคม"];

  const handlePrevMonth = (e: React.MouseEvent) => {
    e.stopPropagation();
    setViewDate(new Date(viewDate.getFullYear(), viewDate.getMonth() - 1, 1));
  };

  const handleNextMonth = (e: React.MouseEvent) => {
    e.stopPropagation();
    setViewDate(new Date(viewDate.getFullYear(), viewDate.getMonth() + 1, 1));
  };

  const handleDateSelect = (day: number) => {
    const year = viewDate.getFullYear();
    const month = (viewDate.getMonth() + 1).toString().padStart(2, '0');
    const dayStr = day.toString().padStart(2, '0');
    onChange(`${year}-${month}-${dayStr}`);
    setIsOpen(false);
  };

  const daysInMonth = new Date(viewDate.getFullYear(), viewDate.getMonth() + 1, 0).getDate();
  const firstDay = new Date(viewDate.getFullYear(), viewDate.getMonth(), 1).getDay();

  const formatDateDisplay = (dateStr: string) => {
    if (!dateStr) return "";
    const date = new Date(dateStr);
    if (isNaN(date.getTime())) return "";
    return `${date.getDate()} ${thaiMonths[date.getMonth()]} ${date.getFullYear() + 543}`;
  };

  return (
    <div className="relative w-full" ref={containerRef}>
      <label className="text-[10px] md:text-xs font-bold text-slate-500 mb-1.5 block uppercase tracking-wider">{label}</label>
      <div 
        onClick={() => setIsOpen(!isOpen)}
        className="w-full border border-slate-200 rounded-xl px-4 py-3 text-sm font-medium bg-slate-50 text-slate-900 cursor-pointer flex items-center justify-between hover:border-blue-500 hover:bg-white transition-all shadow-sm"
      >
        <span className={!value ? "text-slate-400" : ""}>
            {value ? formatDateDisplay(value) : "เลือกวันที่..."}
        </span>
        <CalendarIcon className="w-4 h-4 text-slate-400" />
      </div>

      {isOpen && (
        <div className="fixed md:absolute top-1/2 left-1/2 md:top-full md:left-0 -translate-x-1/2 -translate-y-1/2 md:translate-x-0 md:translate-y-0 z-[100] mt-0 md:mt-2 bg-white rounded-2xl shadow-2xl border border-slate-100 p-5 w-[300px] animate-in fade-in zoom-in-95 duration-150">
          <div className="flex justify-between items-center mb-5">
            <button onClick={handlePrevMonth} className="p-2 hover:bg-slate-50 rounded-lg text-slate-400"><ChevronLeft className="w-6 h-6" /></button>
            <span className="font-bold text-slate-800 text-sm">
              {thaiMonths[viewDate.getMonth()]} {viewDate.getFullYear() + 543}
            </span>
            <button onClick={handleNextMonth} className="p-2 hover:bg-slate-50 rounded-lg text-slate-400"><ChevronRight className="w-6 h-6" /></button>
          </div>
          <div className="grid grid-cols-7 text-center text-[10px] mb-3 text-slate-400 font-bold uppercase tracking-widest">
            {['อา', 'จ', 'อ', 'พ', 'พฤ', 'ศ', 'ส'].map(d => <div key={d}>{d}</div>)}
          </div>
          <div className="grid grid-cols-7 gap-1.5">
            {Array.from({ length: firstDay }).map((_, i) => <div key={`empty-${i}`} />)}
            {Array.from({ length: daysInMonth }).map((_, i) => {
              const day = i + 1;
              const currentStr = `${viewDate.getFullYear()}-${(viewDate.getMonth() + 1).toString().padStart(2, '0')}-${day.toString().padStart(2, '0')}`;
              const isSelected = value === currentStr;
              const today = new Date();
              const isToday = today.getDate() === day && today.getMonth() === viewDate.getMonth() && today.getFullYear() === viewDate.getFullYear();

              return (
                <button
                  key={day}
                  onClick={(e) => { e.stopPropagation(); handleDateSelect(day); }}
                  className={`
                    h-9 w-9 rounded-xl flex items-center justify-center text-xs transition-all
                    ${isSelected ? 'bg-blue-600 text-white font-bold shadow-md scale-110' : 'hover:bg-blue-50 text-slate-700 hover:text-blue-600'}
                    ${!isSelected && isToday ? 'border-2 border-blue-600/30 text-blue-600 font-bold' : ''}
                  `}
                >
                  {day}
                </button>
              );
            })}
          </div>
        </div>
      )}
    </div>
  );
};

export default ThaiDatePicker;

import React, { useMemo } from 'react';
import { LeaveRecord, LeaveType } from '../types';

interface StatsChartProps {
  leaves: LeaveRecord[];
  currentYear: number;
}

const StatsChart: React.FC<StatsChartProps> = ({ leaves, currentYear }) => {
  const data = useMemo(() => {
    const yearLeaves = leaves.filter(l => new Date(l.date).getFullYear() === currentYear);
    const counts = {
      [LeaveType.PERSONAL]: { p1: 0, p2: 0 },
      [LeaveType.MATERNITY]: { p1: 0, p2: 0 },
      [LeaveType.SICK]: { p1: 0, p2: 0 },
      [LeaveType.VACATION]: { p1: 0, p2: 0 },
      [LeaveType.ORDINATION]: { p1: 0, p2: 0 }
    };

    yearLeaves.forEach(leave => {
      const month = new Date(leave.date).getMonth();
      if (month <= 4) counts[leave.type].p1 += 1;
      else counts[leave.type].p2 += 1;
    });

    const order = [LeaveType.PERSONAL, LeaveType.MATERNITY, LeaveType.SICK, LeaveType.VACATION, LeaveType.ORDINATION];
    return order.map(type => ({ name: type, p1: counts[type].p1, p2: counts[type].p2 }));
  }, [leaves, currentYear]);

  return (
    <div className="w-full overflow-hidden rounded-xl border border-slate-100 shadow-sm">
      <div className="overflow-x-auto">
        <table className="w-full text-left border-collapse min-w-[280px]">
          <thead className="bg-slate-50 text-slate-400 border-b border-slate-100">
            <tr>
              <th scope="col" className="px-3 py-3 text-[10px] font-bold uppercase tracking-wider w-[40%]">ประเภทลา</th>
              <th scope="col" className="px-2 py-3 text-center text-[10px] font-bold uppercase tracking-wider border-l border-slate-100">ม.ค.-พ.ค.</th>
              <th scope="col" className="px-2 py-3 text-center text-[10px] font-bold uppercase tracking-wider border-l border-slate-100">มิ.ย.-ธ.ค.</th>
            </tr>
          </thead>
          <tbody className="divide-y divide-slate-50 bg-white">
            {data.map((row, index) => (
              <tr key={index} className="hover:bg-slate-50/50 transition-colors">
                <td className="px-3 py-2.5 text-xs font-bold text-slate-700">{row.name}</td>
                <td className="px-2 py-2.5 text-center text-xs font-bold text-blue-600 border-l border-slate-50">{row.p1}</td>
                <td className="px-2 py-2.5 text-center text-xs font-bold text-blue-600 border-l border-slate-50">{row.p2}</td>
              </tr>
            ))}
          </tbody>
        </table>
      </div>
    </div>
  );
};

export default StatsChart;

