          </div>
          <div className="bg-white rounded-xl shadow-sm border border-slate-200 overflow-hidden">
             <div className="px-4 py-3 border-b border-slate-100 bg-slate-50/50 flex items-center justify-between">
               <h2 className="text-slate-900 font-bold text-xs uppercase tracking-wider">สถิติปี {new Date().getFullYear() + 543}</h2>
             </div>
             <div className="p-2 md:p-4">
               <StatsChart leaves={selectedEmployee ? leaves.filter(l => l.employeeId === selectedEmployee.id) : leaves.filter(l => departmentEmployees.some(e => e.id === l.employeeId))} currentYear={new Date().getFullYear()} />
             </div>
          </div>
        </aside>

        <section className="lg:col-span-9 h-full">
            <div className="bg-white rounded-xl shadow-sm border border-slate-200 overflow-hidden min-h-[500px] md:min-h-[650px]">
                <CalendarView 
                  leaves={leaves} 
                  employees={departmentEmployees} 
                  selectedEmployeeId={selectedEmployee?.id || null} 
                  onDateClick={handleDateClick} 
                  onLeaveClick={handleLeaveClick}
                />
            </div>
        </section>
      </main>

      {/* Leave Modal */}
      {isLeaveModalOpen && (
        <div className="fixed inset-0 bg-slate-900/40 backdrop-blur-sm z-50 flex items-center justify-center p-4">
