          <div className="bg-white rounded-2xl shadow-2xl w-full max-sm p-8 animate-in fade-in zoom-in-95 duration-200 text-center">
                <div className="w-16 h-16 rounded-full bg-red-50 text-red-600 flex items-center justify-center mx-auto mb-5 border border-red-100"><AlertTriangle className="w-9 h-9" /></div>
