import React, { useState, useMemo } from 'react';
import { ChevronLeft, ChevronRight, Info, Calendar as CalendarIcon } from 'lucide-react';
import { LeaveRecord, LeaveType, LEAVE_COLORS, Employee } from '../types';
import { getHolidayName } from '../constants';

interface CalendarViewProps {
  leaves: LeaveRecord[];
  onDateClick: (dateStr: string) => void;
  onLeaveClick: (leaveId: string, date: string, type: LeaveType) => void;
  selectedEmployeeId: string | null;
  employees: Employee[];
}

interface DailyLeave {
    id: string;
    employeeId: string;
    name: string;
    type: LeaveType;
    isSelected: boolean;
}

const CalendarView: React.FC<CalendarViewProps> = ({ leaves, onDateClick, onLeaveClick, selectedEmployeeId, employees }) => {
  const [currentDate, setCurrentDate] = useState(new Date());

  const year = currentDate.getFullYear();
  const month = currentDate.getMonth();

  const daysInMonth = new Date(year, month + 1, 0).getDate();
  const firstDayOfMonth = new Date(year, month, 1).getDay();

  const prevMonth = () => setCurrentDate(new Date(year, month - 1, 1));
  const nextMonth = () => setCurrentDate(new Date(year, month + 1, 1));

  const leavesMap = useMemo(() => {
    const map: Record<string, DailyLeave[]> = {};
    leaves.forEach(l => {
      const emp = employees.find(e => e.id === l.employeeId);
      if (!emp) return;

      if (!map[l.date]) map[l.date] = [];
      map[l.date].push({
          id: l.id,
          employeeId: l.employeeId,
          name: emp.name.split(' ')[0],
          type: l.type,
          isSelected: selectedEmployeeId === l.employeeId
      });
    });
    return map;
  }, [leaves, selectedEmployeeId, employees]);

  const renderDays = () => {
    const days = [];
    for (let i = 0; i < firstDayOfMonth; i++) {
      days.push(<div key={`empty-${i}`} className="min-h-[80px] md:min-h-0 h-full bg-slate-50/50 border-r border-b border-slate-100"></div>);
    }

    for (let i = 1; i <= daysInMonth; i++) {
      const dayStr = i.toString().padStart(2, '0');
      const monthStr = (month + 1).toString().padStart(2, '0');
      const dateStr = `${year}-${monthStr}-${dayStr}`;

      const currentDayDate = new Date(year, month, i);
      const dailyLeaves = leavesMap[dateStr] || [];

      const isToday = new Date().toDateString() === currentDayDate.toDateString();
      const isWeekend = currentDayDate.getDay() === 0 || currentDayDate.getDay() === 6;
      const holidayName = getHolidayName(currentDayDate);
      const isHoliday = !!holidayName;
      const isNonWorkingDay = isWeekend || isHoliday;

      // Check if selected employee has a leave on this day
      const userExistingLeave = selectedEmployeeId 
        ? dailyLeaves.find(l => l.employeeId === selectedEmployeeId) 
        : null;

      days.push(
        <div 
          key={i} 
          onClick={() => { 
              if (isNonWorkingDay || !selectedEmployeeId) return;

              if (userExistingLeave) {
                  // If user has leave, open Edit/Delete modal
                  onLeaveClick(userExistingLeave.id, dateStr, userExistingLeave.type);
              } else {
                  // If no leave, open Create modal
                  onDateClick(dateStr); 
              }
          }}
          className={`min-h-[80px] md:min-h-0 h-full border-r border-b border-slate-100 p-1 md:p-2 relative transition-all duration-150 group flex flex-col
            ${isHoliday ? 'bg-red-50/30' : isWeekend ? 'bg-slate-50/50' : 'bg-white'}
            ${selectedEmployeeId && !isNonWorkingDay ? 'cursor-pointer hover:bg-white hover:shadow-md hover:z-10' : ''}
            ${isToday ? '!bg-blue-50/50 ring-1 ring-inset ring-blue-100' : ''}
          `}
        >
          <div className="flex justify-between items-start mb-0.5 md:mb-1 shrink-0">
            <span className={`
                text-[11px] md:text-sm font-bold h-6 w-6 md:h-7 md:w-7 flex items-center justify-center rounded-full
                ${isToday ? 'bg-blue-600 text-white shadow-sm' : isHoliday ? 'text-red-500' : isNonWorkingDay ? 'text-slate-400' : 'text-slate-700'}
            `}>
              {i}
            </span>
          </div>

          {holidayName && (
             <div className="mb-0.5 md:mb-1 shrink-0">
                <span className="text-[9px] md:text-[10px] leading-tight text-red-600 font-bold px-1 py-0.5 rounded bg-red-50 border border-red-100 block w-fit max-w-full truncate">
                    {holidayName}
                </span>
             </div>
          )}

          <div className="flex flex-col gap-0.5 md:gap-1 overflow-y-auto custom-scrollbar relative z-10 flex-1 min-h-0">
            {dailyLeaves.map((leave, idx) => {
                const isSelectionActive = !!selectedEmployeeId;
                const isSelf = leave.isSelected;
                let colorClass = LEAVE_COLORS[leave.type];
                let styleClass = '';

                if (isSelectionActive) {
                    if (isSelf) {
                        colorClass = colorClass.replace('600', '700').replace('500', '600');
                        styleClass = 'font-bold z-20 cursor-pointer scale-[1.02] shadow-sm ring-1 ring-white';
                    } else {
                        styleClass = 'opacity-20 grayscale z-0 pointer-events-none';
                    }
                } else {
                    styleClass = 'opacity-90';
                }

                return (
                    <div 
                        key={idx}
                        // Stop propagation is still useful if clicking specific pill, 
                        // though parent handler now covers it for isSelf.
                        onClick={(e) => { 
                            if (isSelf) { 
                                e.stopPropagation(); 
                                onLeaveClick(leave.id, dateStr, leave.type); 
                            } 
                        }}
                        className={`px-1 py-0.5 rounded text-[9px] md:text-[10px] text-white truncate transition-all ${colorClass} ${styleClass}`}
                    >
                        {leave.name}
                    </div>
                );
            })}
          </div>
        </div>
      );
    }
    return days;
  };

  const thaiMonths = ["มกราคม", "กุมภาพันธ์", "มีนาคม", "เมษายน", "พฤษภาคม", "มิถุนายน", "กรกฎาคม", "สิงหาคม", "กันยายน", "ตุลาคม", "พฤศจิกายน", "ธันวาคม"];

  return (
    <div className="bg-white h-full flex flex-col">
      <div className="px-4 py-3 md:px-6 md:py-4 flex items-center justify-between border-b border-slate-100 bg-white">
        <div className="flex items-center gap-2 md:gap-3">
             <div className="hidden md:block bg-slate-50 border border-slate-100 p-2 rounded-lg">
                 <CalendarIcon className="w-5 h-5 text-slate-500" />
             </div>
             <div>
                <h2 className="text-base md:text-xl font-bold text-slate-900 flex items-baseline gap-1.5">
                {thaiMonths[month]} <span className="text-slate-300 font-light text-sm">|</span> {year + 543}
                </h2>
                <p className="hidden md:block text-[10px] text-slate-400 font-bold mt-0.5">เลือกพนักงานเพื่อบันทึกการลาในปฏิทิน</p>
             </div>
        </div>

        <div className="flex items-center gap-1 bg-slate-50 border border-slate-100 rounded-lg p-1">
            <button onClick={prevMonth} className="p-2 md:p-1.5 hover:bg-white hover:shadow-sm rounded-md text-slate-600 transition-all">
            <ChevronLeft className="w-5 h-5 md:w-5 md:h-5" />
            </button>
            <button onClick={nextMonth} className="p-2 md:p-1.5 hover:bg-white hover:shadow-sm rounded-md text-slate-600 transition-all">
            <ChevronRight className="w-5 h-5 md:w-5 md:h-5" />
            </button>
        </div>
      </div>

      <div className="grid grid-cols-7 border-b border-slate-100 bg-slate-50/50">
        {['อา.', 'จ.', 'อ.', 'พ.', 'พฤ.', 'ศ.', 'ส.'].map((d, i) => (
          <div key={i} className={`py-2 md:py-3 text-center text-[10px] md:text-xs font-bold border-r border-slate-100 last:border-r-0 ${i === 0 || i === 6 ? 'text-red-500' : 'text-slate-500'}`}>
            {d}
          </div>
        ))}
      </div>

      <div className="grid grid-cols-7 flex-1 auto-rows-fr bg-slate-100 gap-px border-b border-slate-100">
        {renderDays()}
      </div>

      {!selectedEmployeeId && (
        <div className="p-2 md:p-3 bg-slate-50 border-t border-slate-100 text-slate-400 text-[10px] md:text-xs flex items-center justify-center gap-2 font-bold italic">
            <Info className="w-3.5 h-3.5"/> 
            <span>แสดงข้อมูลวันลาของพนักงานทั้งแผนก</span>
        </div>
      )}
    </div>
  );
};

export default CalendarView;

import React, { useState, useMemo, useRef, useEffect } from 'react';
import { 
  Users, Activity, Database, Search, Calendar as CalendarIcon, 
  ArrowLeft, CheckCircle2, LayoutDashboard, ChevronRight, ChevronLeft, UserPlus, X, Briefcase,
  Trash2, Save, AlertTriangle, RefreshCw, FileSpreadsheet, Loader2, User, Eraser,
  Pencil, Undo2, Edit3
} from 'lucide-react';
import { Department, Employee, LeaveRecord, LeaveType, LEAVE_COLORS } from './types';
import { INITIAL_EMPLOYEES, INITIAL_LEAVES, DEPARTMENTS, getHolidayName } from './constants';
import CalendarView from './components/CalendarView';
import StatsChart from './components/StatsChart';
import ThaiDatePicker from './components/ThaiDatePicker';
import { supabase } from './lib/supabaseClient';

// Define interface for batch delete/edit state
interface BatchLeaveState {
  ids: string[];
  startDate: string;
  endDate: string;
  type: LeaveType;
  totalDays: number;
}

function App() {
  const [currentDepartment, setCurrentDepartment] = useState<Department | null>(null);
  const [employees, setEmployees] = useState<Employee[]>(INITIAL_EMPLOYEES);
  const [searchQuery, setSearchQuery] = useState('');
  const [selectedEmployee, setSelectedEmployee] = useState<Employee | null>(null);
  const [leaves, setLeaves] = useState<LeaveRecord[]>(INITIAL_LEAVES);

  const [isLeaveModalOpen, setIsLeaveModalOpen] = useState(false);
  const [leaveStartDate, setLeaveStartDate] = useState<string>('');
  const [leaveEndDate, setLeaveEndDate] = useState<string>('');
  const [leaveType, setLeaveType] = useState<LeaveType>(LeaveType.PERSONAL);

  const [isManageUserModalOpen, setIsManageUserModalOpen] = useState(false);
  const [userForm, setUserForm] = useState({ name: '', position: '' });
  const [editingEmployeeId, setEditingEmployeeId] = useState<string | null>(null);
  const [isSyncing, setIsSyncing] = useState(false);
  const [isSaving, setIsSaving] = useState(false);

  // State for Statistics Year
  const [statsYear, setStatsYear] = useState(new Date().getFullYear());

  const [deleteConfirm, setDeleteConfirm] = useState<{isOpen: boolean, id: string | null, name: string}>({
    isOpen: false, id: null, name: ''
  });

  // State for Editing an existing leave (Change Type)
  const [editingLeaveBatch, setEditingLeaveBatch] = useState<BatchLeaveState | null>(null);

  // State for Deleting Confirmation
  const [leaveToDelete, setLeaveToDelete] = useState<BatchLeaveState | null>(null);

  const fetchAndSetData = async (isShowAlert = false) => {
    setIsSyncing(true);
    try {
      // Fetch Employees
      const { data: empData, error: empError } = await supabase
        .from('employees')
        .select('*')
        .order('name');

      if (empError) throw empError;

      // Fetch Leaves
      const { data: leaveData, error: leaveError } = await supabase
        .from('leaves')
        .select('*');

      if (leaveError) throw leaveError;

      const fetchedEmployees: Employee[] = (empData || []).map((e: any) => ({
        id: e.id,
        name: e.name,
        position: e.position,
        department: e.department as Department
      }));

      const processedLeaves: LeaveRecord[] = (leaveData || []).map((l: any) => ({
        id: l.id,
        employeeId: l.employee_id, // Map database column snake_case to camelCase
        date: l.date,
        type: l.type as LeaveType
      }));

      setEmployees(fetchedEmployees);
      setLeaves(processedLeaves);

      if (isShowAlert) alert('✅ ซิงค์ข้อมูลสำเร็จ!');

    } catch (error: any) {
      console.error("Error loading data:", error);
      if (isShowAlert) alert('❌ เกิดข้อผิดพลาด: ' + error.message);
    } finally {
      setIsSyncing(false);
    }
  };

  useEffect(() => {
    fetchAndSetData(false);
  }, []);

  const departmentEmployees = useMemo(() => {
    if (!currentDepartment) return [];
    return employees.filter(emp => emp.department === currentDepartment);
  }, [currentDepartment, employees]);

  const filteredEmployees = useMemo(() => {
    if (!currentDepartment) return [];
    return employees.filter(emp => {
      const matchDept = emp.department === currentDepartment;
      const matchSearch = emp.name.toLowerCase().includes(searchQuery.toLowerCase());
      return matchDept && matchSearch;
    });
  }, [currentDepartment, searchQuery, employees]);

  const formatDateDisplay = (dateStr: string) => {
    if (!dateStr) return "";
    const [y, m, d] = dateStr.split('-');
    return `${d}/${m}/${parseInt(y) + 543}`;
  };

  const calculatedDatesToAdd = useMemo(() => {
    if (!leaveStartDate || !leaveEndDate) return [];
    const start = new Date(leaveStartDate);
    const end = new Date(leaveEndDate);
    if (isNaN(start.getTime()) || isNaN(end.getTime()) || start > end) return [];
    const dates: string[] = [];
    const loopDate = new Date(start);

    while (loopDate <= end) {
        const dateStr = loopDate.toISOString().split('T')[0];

        // Strict Logic: Exclude Weekends and Holidays automatically
        const dayOfWeek = loopDate.getDay(); // 0 = Sunday, 6 = Saturday (Local time)
        const isWeekend = dayOfWeek === 0 || dayOfWeek === 6;

        // Check Holiday
        const [y, m, d] = dateStr.split('-').map(Number);
        // Create date object for checking holiday (using local time components)
        const checkDate = new Date(y, m - 1, d); 
        const isHoliday = !!getHolidayName(checkDate);

        // Only add if it's a Working Day (Not Weekend AND Not Holiday)
        if (!isWeekend && !isHoliday) {
            dates.push(dateStr);
        }

        loopDate.setDate(loopDate.getDate() + 1);
    }
    return dates;
  }, [leaveStartDate, leaveEndDate]);

  const handleDepartmentSelect = (dept: Department) => {
    setCurrentDepartment(dept);
    setSearchQuery('');
    setSelectedEmployee(null);
  };

  const handleUserSelect = (emp: Employee) => {
    setSelectedEmployee(emp);
    setSearchQuery(emp.name);
  };

  const handleDateClick = (dateStr: string) => {
    if (!selectedEmployee) return;

    // Prevent clicking on weekends or holidays to start a leave
    const [y, m, d] = dateStr.split('-').map(Number);
    const dateObj = new Date(y, m - 1, d);
    const day = dateObj.getDay();
    const isHoliday = !!getHolidayName(dateObj);

    if (day === 0 || day === 6 || isHoliday) {
      alert("ไม่สามารถเลือกวันหยุดเสาร์-อาทิตย์ หรือวันหยุดนักขัตฤกษ์ได้");
      return;
    }

    setLeaveStartDate(dateStr);
    setLeaveEndDate(dateStr); 
    setLeaveType(LeaveType.PERSONAL); // Reset to default when opening new
    setIsLeaveModalOpen(true);
  };

  const handleLeaveClick = (leaveId: string, date: string, type: LeaveType) => {
      // Find the specific clicked leave
      const clickedLeave = leaves.find(l => l.id === leaveId);
      if (!clickedLeave) return;

      // Smart Grouping Logic:
      // 1. Filter leaves by same employee and same type
      const relatedLeaves = leaves.filter(l => 
          l.employeeId === clickedLeave.employeeId && 
          l.type === clickedLeave.type
      ).sort((a, b) => new Date(a.date).getTime() - new Date(b.date).getTime());

      // 2. Group consecutive leaves (allowing small gaps for weekends/holidays, e.g., <= 4 days)
      const groups: LeaveRecord[][] = [];
      let currentGroup: LeaveRecord[] = [];

      relatedLeaves.forEach((l) => {
          if (currentGroup.length === 0) {
              currentGroup.push(l);
          } else {
              const lastDate = new Date(currentGroup[currentGroup.length - 1].date);
              const currDate = new Date(l.date);
              const diffTime = Math.abs(currDate.getTime() - lastDate.getTime());
              const diffDays = Math.ceil(diffTime / (1000 * 60 * 60 * 24));

              // If gap is <= 4 days (e.g., Fri -> Mon is 3 days gap), group them
              if (diffDays <= 4) {
                  currentGroup.push(l);
              } else {
                  groups.push(currentGroup);
                  currentGroup = [l];
              }
          }
      });
      if (currentGroup.length > 0) groups.push(currentGroup);

      // 3. Find which group the clicked ID belongs to
      const targetGroup = groups.find(g => g.some(l => l.id === leaveId)) || [clickedLeave];

      const batchData = { 
          ids: targetGroup.map(l => l.id), 
          startDate: targetGroup[0].date,
          endDate: targetGroup[targetGroup.length - 1].date,
          type: type,
          totalDays: targetGroup.length
      };

      // Open the Edit/Manage Modal instead of immediately Deleting
      setLeaveType(type); // Set the current type to state so radio button is checked
      setEditingLeaveBatch(batchData);
  };

  const handleUpdateLeaveType = async () => {
    if (!editingLeaveBatch || !selectedEmployee) return;

    // If type hasn't changed, just close
    if (leaveType === editingLeaveBatch.type) {
        setEditingLeaveBatch(null);
        return;
    }

    setIsSaving(true);
    try {
        const { error } = await supabase
            .from('leaves')
            .update({ type: leaveType })
            .in('id', editingLeaveBatch.ids);

        if (error) throw error;

        // Update local state
        setLeaves(prev => prev.map(l => 
            editingLeaveBatch.ids.includes(l.id) 
            ? { ...l, type: leaveType } 
            : l
        ));

        setEditingLeaveBatch(null);
    } catch (error: any) {
        console.error('Error updating leave:', error);
        alert('เกิดข้อผิดพลาดในการแก้ไข: ' + error.message);
    } finally {
        setIsSaving(false);
    }
  };

  const handleInitiateDelete = () => {
      if (editingLeaveBatch) {
          setLeaveToDelete(editingLeaveBatch);
          setEditingLeaveBatch(null);
      }
  };

  const handleConfirmDeleteLeave = async () => {
      if (!leaveToDelete || !selectedEmployee) return;
      setIsSaving(true);
      try {
        // Delete multiple IDs
        const { error } = await supabase
          .from('leaves')
          .delete()
          .in('id', leaveToDelete.ids);

        if (error) throw error;

        // Filter out all deleted IDs from local state
        setLeaves(prev => prev.filter(l => !leaveToDelete.ids.includes(l.id)));
        setLeaveToDelete(null);
      } catch (error: any) {
        console.error('Error deleting leave:', error);
        alert('เกิดข้อผิดพลาดในการลบ: ' + error.message);
      } finally {
        setIsSaving(false);
      }
  };

  const handleSaveLeave = async () => {
    if (!selectedEmployee || calculatedDatesToAdd.length === 0) return;

    // Check for duplicate leaves on the same day for the selected employee
    const duplicateDate = calculatedDatesToAdd.find(dateToAdd => 
      leaves.some(l => l.employeeId === selectedEmployee.id && l.date === dateToAdd)
    );

    if (duplicateDate) {
      alert(`ไม่สามารถบันทึกได้: วันที่ ${formatDateDisplay(duplicateDate)} มีข้อมูลการลาอยู่แล้ว\n(บุคลากร 1 คน สามารถเลือกประเภทการลาได้เพียง 1 ประเภทต่อวัน)`);
      return;
    }

    setIsSaving(true);

    try {
      const inserts = calculatedDatesToAdd.map(date => ({
        employee_id: selectedEmployee.id,
        date: date,
        type: leaveType
      }));

      const { data, error } = await supabase
        .from('leaves')
        .insert(inserts)
        .select();

      if (error) throw error;

      if (data) {
        const newLeaves: LeaveRecord[] = data.map((l: any) => ({
          id: l.id,
          employeeId: l.employee_id,
          date: l.date,
          type: l.type as LeaveType
        }));

        setLeaves(prev => [...prev, ...newLeaves]);
      }

      setIsLeaveModalOpen(false);
    } catch (error: any) {
      console.error('Error saving leave:', error);
      alert('เกิดข้อผิดพลาดในการบันทึก: ' + error.message);
    } finally {
      setIsSaving(false);
    }
  };

  const handleEditClick = (emp: Employee) => {
    setUserForm({ name: emp.name, position: emp.position });
    setEditingEmployeeId(emp.id);
  };

  const handleCancelEdit = () => {
    setUserForm({ name: '', position: '' });
    setEditingEmployeeId(null);
  };

  const handleUserSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!userForm.name || !userForm.position || !currentDepartment) return;

    // Normalize name (remove extra spaces) to ensure "Name  Surname" == "Name Surname"
    const normalizeName = (name: string) => name.replace(/\s+/g, ' ').trim();
    const normalizedInputName = normalizeName(userForm.name);
    const trimmedPosition = userForm.position.trim();

    // Check for Duplicate Name (Only check exact full name match)
    // Allows: Same Firstname (diff Lastname), Same Lastname (diff Firstname)
    // Blocks: Same Firstname AND Same Lastname
    const isDuplicate = employees.some(emp => 
      normalizeName(emp.name) === normalizedInputName && 
      emp.id !== editingEmployeeId 
    );

    if (isDuplicate) {
      alert(`ไม่สามารถบันทึกได้: พบรายชื่อ "${normalizedInputName}" ซ้ำกันในระบบ`);
      return;
    }

    setIsSaving(true);

    try {
      if (editingEmployeeId) {
          // Update existing
          const { error } = await supabase
            .from('employees')
            .update({ name: normalizedInputName, position: trimmedPosition })
            .eq('id', editingEmployeeId);

          if (error) throw error;

          // Update local state
          setEmployees(prev => prev.map(emp => 
              emp.id === editingEmployeeId 
                  ? { ...emp, name: normalizedInputName, position: trimmedPosition }
                  : emp
          ));

          // Also update selectedEmployee if it's the one being edited
          if (selectedEmployee?.id === editingEmployeeId) {
            setSelectedEmployee(prev => prev ? { ...prev, name: normalizedInputName, position: trimmedPosition } : null);
          }

          setEditingEmployeeId(null);
      } else {
          // Create new
          const { data, error } = await supabase
            .from('employees')
            .insert([{
              name: normalizedInputName,
              position: trimmedPosition,
              department: currentDepartment
            }])
            .select()
            .single();

          if (error) throw error;

          if (data) {
            const newEmp: Employee = {
                id: data.id,
                name: data.name,
                position: data.position,
                department: data.department as Department
            };
            setEmployees(prev => [newEmp, ...prev]);
          }
      }
      setUserForm({ name: '', position: '' });
    } catch (error: any) {
      console.error('Error saving user:', error);
      alert('เกิดข้อผิดพลาดในการบันทึกบุคลากร: ' + error.message);
    } finally {
      setIsSaving(false);
    }
  };

  const handleSyncFromSheets = async () => {
