              <button 
                onClick={executeDeleteUser} 
                disabled={isSaving}
                className="flex-1 py-2.5 rounded-xl bg-red-600 text-white font-bold hover:bg-red-700 shadow-lg shadow-red-200 transition-colors text-sm flex items-center justify-center gap-2"
